/* 自动生成，请勿手改：列表页精简数据集（由 js/data.js 生成，工具见 tools/lib/index-data.mjs） */
const articles = [{"id":"shiji-yanjiu","title":"《史记》中的时间观与历史书写","date":"2026-06-10","category":"史学理论","tags":["史记","司马迁","史学史"],"summary":"司马迁在《史记》中以十二本纪为经、十表为纬，把上古传说至汉武时代的三千年纳入同一时间框架。本纪、表、书、传各依不同的时间尺度展开，纪传体由此获得同时性与纵深。这套时间观不仅是纪年工具，更暗含他对历史意义的理解：循环的节律与个体的能动性彼此张力，构成《史记》独特的史学品格。"},{"id":"song-dynasty","title":"宋代士大夫的政治理想与现实困境","date":"2026-05-28","category":"中国史","tags":["宋代","士大夫","政治史"],"summary":"宋代士大夫以天下为己任，依托科举、台谏与经筵，形成前所未有的政治主体意识。然而庆历新政与熙宁变法相继受挫，新旧党争把政策分歧转化为道德审判。文章从文官体制、财政军备与道学话语三处入手，解释士大夫政治的繁荣与自我消耗何以同时发生。"},{"id":"historiography-modern","title":"二十世纪西方史学的三次转向","date":"2026-05-15","category":"史学理论","tags":["西方史学","年鉴学派","后现代"],"summary":"二十世纪西方史学经历三次方法论转向：年鉴学派以结构与长时段取代政治叙事，新文化史转向微观经验与意义世界，全球史则突破民族国家框架。文章梳理三次转向的制度背景与代表研究，并讨论叙事建构与证据约束之间的张力，以及转向叠加之后史学所处的处境。"},{"id":"silk-road","title":"丝绸之路上的文化交融与知识传播","date":"2026-06-14","category":"世界史","tags":["丝绸之路","文化交流","世界史"],"summary":"丝绸之路常被理解为丝绸与香料的贸易通道，但它更重要的角色是知识传播的动脉。佛教东传、造纸术西传、天文历法与医药的往还，都沿着这条网络展开，并伴随战争、征服与瘟疫。粟特商人、译经僧团与蒙古时代的驿站，构成了交流的具体机制。把它放回历史情境，才能看清文明互动的复杂与代价。"},{"id":"western-learning","title":"明清之际的“西学东渐”与知识转型","date":"2026-06-12","category":"中国史","tags":["明清","思想史","中西交流"],"summary":"十六至十八世纪，耶稣会士把西方的数学、天文、地理与火炮技术带入中国，也把中国典籍送回欧洲，形成一场持续两百年的跨文明知识对话。这场对话既有丰硕的成果，也暴露了不同知识体系之间的张力。本文考察其传播路径、接受方式以及礼仪之争后的中断。"},{"id":"historical-memory","title":"历史记忆与集体遗忘——纪念的伦理","date":"2026-06-11","category":"史学理论","tags":["记忆研究","史学理论","近代史"],"summary":"历史不仅是过去发生的事，更是一个社会集体记忆与遗忘的产物。从纪念馆到教科书，从纪念日到公共艺术，一个社会选择记住什么、遗忘什么，深刻地塑造着它的身份认同与政治走向。本文讨论记忆场所、遗忘机制，以及纪念所涉及的伦理尺度。"},{"id":"periodization","title":"从“封建”到“帝国”——中国历史分期概念的反思","date":"2026-06-09","category":"史学理论","tags":["概念史","史学理论","中国史"],"summary":"如何划分中国历史的阶段，从来不只是技术性的编年问题。从封建与郡县的古典之辨，到奴隶社会与封建社会的马克思主义框架，再到晚近帝国概念的复兴，分期标准的每一次更换都伴随理论预设的转移。本文梳理这三条脉络，并追问分期背后关于历史动力与历史意义的假设。"},{"id":"ww2-origins","title":"第二次世界大战起源的史学辩论","date":"2026-06-08","category":"世界史","tags":["二战","史学史","世界史"],"summary":"第二次世界大战的起源是二十世纪史学中最富争议的议题之一。从纽伦堡审判后的罪责追问，到费舍尔关于德国连续性的论战、泰勒的修正主义解释，再到七十年代的结构分析与冷战后的多国档案研究，解释的重心在个人意图、社会结构与国际体系之间反复移动。"},{"id":"ancient-greek-democracy","title":"古希腊的民主制度与历史书写","date":"2026-06-14","category":"西方史","tags":["“古希腊”","“民主”","“希罗多德”","“修昔底德”"],"summary":"雅典民主不仅是一套政治制度，也塑造了古希腊人理解过去的方式。公民大会的公开辩论、抽签分配的官职与刻石公布的文书，使证据与理由成为公共生活的通货。希罗多德的多方求证、修昔底德对因果与语义的追问，都带着这种批判性的印记。文章同时讨论其盲点与后世影响。"},{"id":"american-chinese-studies","title":"从“冲击—回应”到“在中国发现历史”：美国中国学的范式转换","date":"2026-06-07","category":"史学理论","tags":["“美国中国学”","“费正清”","“柯文”","“范式”"],"summary":"二十世纪下半叶，美国中国学经历了一场范式转换。费正清所代表的冲击—回应模式，把近代中国的变迁解释为对西方压力的被动反应；柯文在1984年提出中国中心观，主张从中国自身的区域、阶层与日常经验出发理解其历史。此后全球史与后殖民研究又从外部联系与叙事结构两方面提出质疑。"},{"id":"tang-fanzhen","title":"唐代藩镇制度：从军事防御到地方割据","date":"2026-06-15","category":"制度史","tags":["唐代","藩镇","制度史"],"summary":"藩镇之制起于睿宗景云年间，本是应对边疆威胁的军事防御体系。安史之乱后，降将授节、内地增镇，河朔三镇渐成世袭割据。但藩镇并非铁板一块：中原防遏、边疆御边与东南财源各具功能，与朝廷形成以军事服务交换财赋、以名义权威交换地方自主的复杂共生关系。"},{"id":"song-keju","title":"宋代科举社会的形成与影响","date":"2026-06-15","category":"社会史","tags":["宋代","科举","社会流动"],"summary":"宋代是中国历史上第一个真正意义上的科举社会。解试、省试、殿试三级考试与糊名、誊录等技术安排，把选官权逐层收归中央；录取名额的扩张使寒门士人获得前所未有的上升通道。科举同时重塑了印刷业、宗族组织与地方权力结构，也留下了应试僵化与朋党倾轧的长久遗产。"},{"id":"ming-qing-jiangnan","title":"明清江南市镇经济：资本主义萌芽的温床","date":"2026-06-15","category":"经济史","tags":["明清","江南","经济史","市镇"],"summary":"明清江南市镇星罗棋布，棉布、丝货与米粮在密布的水网间集散，出现了机户出资、织工出力的雇佣关系与一镇专营一业的分工格局。然而发达的商品经济并未自行导向工业革命。人口压力、资本流向土地、国家管制与煤炭及海外市场的缺失，构成了学界持续争论的解释。"},{"id":"tang-song-transition","title":"唐宋变革论再思考：内藤湖南的假说与后世回应","date":"2026-07-10","category":"史学理论","tags":["唐宋变革","内藤湖南","史学史"],"summary":"内藤湖南在1910年提出唐宋变革论，把唐宋之际视为中国从中世走向近世的转折，并从政治、社会、经济、文化四个层面加以概括。这一假说为二十世纪的唐宋史研究提供了框架，也招致京都学派的发展与东京学派的封建制论说。1980年代以后，量化研究、区域史与环境史倾向于把它看作渐进而区域差异显著的长过程。"},{"id":"dunhuang-daily-life","title":"从敦煌文书看唐代社会的日常生活","date":"2026-07-08","category":"中国史","tags":["唐代","敦煌","社会史"],"summary":"敦煌藏经洞出土的数万件文书，让人得以绕过正史的宏大叙事，直接触摸唐代普通人的日常生活：契约、账簿、书信、户籍与书仪。这些为实用而写的纸片，记录着借贷、分家、差役与节庆，也暴露出制度在边地的实际运行方式。它们既是社会史的原料，也是理解国家与基层关系的入口。"},{"id":"environmental-history-rise","title":"环境史的兴起：当自然成为历史的主角","date":"2026-07-05","category":"西方史学","tags":["环境史","全球史","方法论"],"summary":"环境史在二十世纪后期异军突起，将气候、疾病、物种与地形纳入历史叙事，动摇了以人类活动为唯一中心的传统史观。从克罗斯比的哥伦布大交换到麦克尼尔的瘟疫叙事，再到伊懋可对中国生态变迁的追踪，历史书写的边界被重新界定，自然不再只是舞台，而成为行动者。"},{"id":"mongol-global-history","title":"全球史视野下的蒙古帝国","date":"2026-07-02","category":"世界史","tags":["蒙古帝国","全球史","欧亚史"],"summary":"蒙古帝国的征服一度将欧亚大陆连为一体，被一些学者称为最早的世界体系。驿路、站赤与商队把相距万里的区域编入同一张网络，商品、技术、宗教与病原体沿同一通道流动。蒙古和平与黑死病因此成为同一进程的两面，其制度遗产又深刻影响了明清中国、罗斯与西亚的政治走向。"},{"id":"north-dynasties-china","title":"辽金元史视角下的北族王朝与中华文明","date":"2026-06-28","category":"中国史","tags":["辽金元","民族史","制度史"],"summary":"辽、金、元长期被放在征服王朝的框架中，被视为汉地文明的破坏者。但南北面官的双轨行政、猛安谋克与汉法的折冲、行省与土司的制度实验，恰恰为多民族中国的形成提供了关键经验。近年辽金元研究的推进，正在把这段历史从华夷叙事的边缘拉回制度史的中心。"},{"id":"baekgang-battle","title":"白江口之战：663年东亚格局的转折点","date":"2026-08-05","category":"中国史","tags":["唐代","白江口","东亚史"],"summary":"663年唐与新罗联军在白江口大破倭国水军，焚船四百余艘。这场海战终结了倭国介入朝鲜半岛的企图，倭国自此转向遣唐使与律令建设，唐朝则把百济故地纳入羁縻体系。从战前博弈、水军战术到战后格局，白江口之战是一场被低估的东亚历史转折，其规模与意义在后世叙述中仍存争议。"},{"id":"tang-silla-war","title":"唐罗战争：高句丽灭亡后的半岛再平衡","date":"2026-08-03","category":"中国史","tags":["唐代","新罗","战争"],"summary":"六六八年高句丽灭亡后，唐与新罗因半岛主导权反目，战争持续七年。新罗以山地游击与民众支持消耗唐军，唐朝则因吐蕃压力与驻军成本内迁安东都护府。战争以唐退至大同江以南告终，新罗完成半岛中南部统一，东亚册封体系下的相对独立格局由此定型。"},{"id":"jangbogo-sea-power","title":"张保皋与新罗海上势力：合作型海权的先声","date":"2026-08-01","category":"世界史","tags":["唐代","新罗","海上丝绸之路"],"summary":"九世纪的新罗将领张保皋以清海镇为基地，经营连接唐、新罗、日本的海上贸易网络，打击海盗、赎回被掠人口、保障航道。他代表了一种与征服型海权不同的合作型海权：以秩序维护与商业互利为核心，为海上丝路的和平繁荣提供了范例。但清海镇的财政与合法性系于他一身，其遇害也暴露了这种秩序提供者的脆弱。"},{"id":"two-tax-law-tang","title":"两税法与唐代财政国家的转型","date":"2026-11-16","category":"制度史","tags":["唐代","两税法","财政史"],"summary":"建中元年（780年）杨炎推行两税法，以“户无主客，以见居为簿”取代租庸调，是中国财政史上一次结构性转折。它把税基从人丁转向资产，把征收从实物劳役转向货币折算，也重新划定了中央与地方的财政边界。但两税法并非一劳永逸的方案，钱重物轻与附加税的回潮，暴露了制度设计背后的深层张力。"},{"id":"oral-history-testimony","title":"口述史的证词与记忆的边界","date":"2026-11-12","category":"史学理论","tags":["口述史","历史记忆","方法论"],"summary":"口述史在二十世纪后半叶成为史学的重要方法：它让沉默者进入历史，也把记忆的不可靠性带进了史料。口述材料既是关于过去的证词，也是关于现在的叙述。理解这一双重性，才能既不把口述史当作文献的替代品，也不因记忆的变形而否定它的价值。"},{"id":"indian-ocean-trade","title":"印度洋贸易体系：1500年前后的连续与断裂","date":"2026-11-08","category":"世界史","tags":["印度洋","贸易史","全球史"],"summary":"长期以来，1498年达伽马抵达卡利卡特被视为印度洋历史的分水岭。但近半个世纪的研究表明，葡萄牙人进入的是一个已经运转千年的贸易网络，他们更多是寄生其上的武装商人，而非秩序的创造者。真正的结构性转变，发生在十七世纪公司垄断与殖民地港口兴起之后。"},{"id":"huizhou-contracts","title":"一纸契约里的乡村：徽州文书与明清社会","date":"2026-11-21","category":"社会史","tags":["徽州文书","契约","明清社会"],"summary":"徽州文书是南宋以来留存于徽州六县的民间契约与簿册，其整理刊布使它成为观察基层社会的重要材料。文章从一件契约的固定格式入手，分析活卖、找价、典与绝卖所构成的地权分层，讨论宗族与族产如何介入土地流转，并把契约与鱼鳞图册、黄册的登记系统对照，最后指出这批文书偏向有产之家、地域集中与留存不均的局限。"},{"id":"roman-roads-communication","title":"罗马的道路与信息：帝国如何被连接","date":"2026-11-18","category":"世界史","tags":["罗马","道路","信息传递"],"summary":"罗马的道路网起于军事需要，却在数百年间演化为帝国行政与信息的骨架。文章从阿庇亚大道说起，梳理干道的工程做法、里程碑与桥梁隧道，进而分析公共驿传中 mansio 与 mutatio 的分工、公文传递的速度及其对行省治理的塑造，并讨论军团后勤、贸易网络与地方养护负担，最后与波斯御道、秦驰道作简要比较。"},{"id":"annales-school","title":"年鉴学派：从地理时间到心态史","date":"2026-11-17","category":"西方史学","tags":["年鉴学派","布罗代尔","心态史"],"summary":"年鉴学派自一九二九年费弗尔与布洛赫创办刊物起，以总体史与跨学科方法对抗事件史与制度史。文章梳理布罗代尔的三层时间及其《地中海》的结构，追踪第三代向心态史与历史人类学的转向、计量史学与系列史的方法，并讨论碎片化与长时段过度的批评，最后说明它对中国社会经济史与区域史研究的影响。"},{"id":"song-maritime-trade","title":"宋代的海上贸易与市舶司","date":"2026-11-19","category":"经济史","tags":["宋代","海上贸易","市舶司"],"summary":"以市舶司的设置与抽解、博买制度为线索，梳理宋代海上贸易的行政框架：公凭公据如何把出海与回舶纳入稽查，蕃坊与蕃商如何在广州、泉州、明州形成港口社会，香药、瓷器、丝帛与铜钱外流如何构成贸易结构，市舶收入在南宋财政中的位置，以及《宋会要辑稿》《萍洲可谈》《诸蕃志》三类史料对读时的统计困难。"},{"id":"abolition-keju-1905","title":"废科举：1905 年与读书人的出路","date":"2026-11-20","category":"中国史","tags":["科举","晚清","教育"],"summary":"从光绪三十一年停科举的谕令入手，回溯1901年废八股、1904年癸卯学制的铺垫，考察科举、学堂与留日教育之间的此消彼长，士绅向学堂、报馆、新军、自治与实业的流动，乡村教育的真空与城绅化，以及废科举同预备立宪的关系；并对科举作为社会流动通道的经典判断重作讨论。"},{"id":"qin-bamboo-slips","title":"睡虎地秦简：律令中的秦帝国日常","date":"2026-11-26","category":"中国史","tags":["秦简","出土文献","法律制度"],"summary":"1975年出土的睡虎地秦简，是秦代南郡基层吏员喜的随葬文书，含《秦律十八种》《法律答问》《封诊式》《语书》《为吏之道》等篇。它让秦的账目、勘验、考核与爵制变得可读，也保留连坐重罚的一面。简册的地方性与偶然性提醒读者，一县之书不能概括帝国全貌，其价值与局限始终并存。"},{"id":"local-gazetteers","title":"地方志：帝国如何书写一个县","date":"2026-11-27","category":"中国史","tags":["地方志","史料学","明清"],"summary":"地方志由官府倡修、士绅执笔，按沿革、疆域、户口、田赋、职官、选举、人物、艺文、杂记等门类书写一县，现存约八千余种，明清两代占绝大多数。它提供连续的地方数据与生活细节，也带来照抄旧志、攀附名人、褒贬失实的陷阱。把不同版本当作层累的文本对读，才可能既用其长又避其短。"},{"id":"byzantium-1204","title":"1204年君士坦丁堡的陷落：第四次十字军与帝国的断裂","date":"2026-11-28","category":"世界史","tags":["拜占庭","十字军","中世纪"],"summary":"第四次十字军原定远征埃及，却因巨额船债、威尼斯商业利益与拜占庭宫廷政争转向君士坦丁堡，于1204年4月攻陷该城并纵掠三日。拉丁帝国随之建立，拜占庭分裂为尼西亚、伊庇鲁斯与特拉比松三个政权。史家争论这是意外还是结构必然，通行看法是多因素叠加的结果，而非单一预谋。"},{"id":"guilds-medieval","title":"行会与城市：中世纪欧洲的手工业组织","date":"2026-11-29","category":"社会史","tags":["中世纪","行会","城市史"],"summary":"中世纪行会组织师傅、帮工与学徒，管制质量、价格与市场准入，兼有互助、宗教与市政参与的功能。它既提供培训与保障，也用封闭限制竞争；行会是否阻碍技术，至今仍有争论。与明清会馆、公所对照，可见城市自治程度与法律框架如何塑造不同的行业组织，行会并非单一的垄断反派，需要具体分析。"},{"id":"little-ice-age-crisis","title":"小冰期与十七世纪的危机","date":"2026-11-30","category":"世界史","tags":["气候史","十七世纪危机","全球史"],"summary":"以「十七世纪普遍危机」命题为线索，梳理小冰期的证据与降温幅度、欧洲三十年战争与1690年代大饥荒、明末大旱与明清易代、日本宽永饥馑、奥斯曼与莫卧儿的困境；进而分析气候如何经仓储、赋税与战争等中介放大为饥荒与叛乱，并检讨这一命题的区域差异、证据局限与气候决定论的限度。"},{"id":"qing-frontier-ethnography","title":"清代的边疆「采风」：从《皇清职贡图》看帝国的人类学","date":"2026-12-01","category":"中国史","tags":["清代","边疆","图像史料"],"summary":"《皇清职贡图》的编纂过程、九卷结构与图说体例：职贡传统与采风的双重性、以京师为中心的同心圆式分类、图像的程式化与地方进呈稿的多次转写、熟番生番一类行政命名与性别安排；再论它与近代民族志在目的与知识制度上的根本区别，以及它作为图像史料的价值与使用限制，还有它不能证明的东西。"},{"id":"soviet-archives","title":"苏联档案开放与二十世纪史的重写","date":"2026-12-02","category":"史学理论","tags":["苏联","档案","冷战史"],"summary":"1991年前后苏联档案的部分开放如何改写苏联史与冷战史：卡廷、苏德秘密议定书、大恐怖、乌克兰大饥荒、朝鲜战争起源等案例；并反思档案崇拜、沉默与缺档的证据意义、新史料与旧解释框架之间的张力，以及档案的物质性、选编问题与二十一世纪获取条件的再度收紧，说明开放并非一次完成的状态。"},{"id":"women-letter-writing","title":"闺阁与书信：明清女性的书写空间","date":"2026-12-03","category":"社会史","tags":["明清","女性史","书信"],"summary":"明清女性留下书信、诗词与弹词：家书处理银钱、田租与子女婚配，也承担族中事务的决断；闺秀之间的诗笺往还构成同性交游网络，才女文化借坊刻出版成形。作品多经男性亲属编选刊刻而存，家书则因不被视为著作而散佚。阅读时既要避免用现代自我表达的概念套用，也要从文体缝隙里读出她们的实际判断。"},{"id":"medieval-universities","title":"中世纪的大学：知识的制度化","date":"2026-12-04","category":"世界史","tags":["中世纪","大学","教育史"],"summary":"大学一词本义是行会。博洛尼亚由学生雇佣教师、签订合同，巴黎由教师行会掌握执教许可，1200 年的特许状与 1231 年的教皇诏书确立其自治。七艺之后分神学、法学、医学，教学以讲授与辩论为主，分册租抄与学院制度支撑起知识的复制。它把知识变成可考核、可授证的制度，却不是现代的研究机构。"},{"id":"microhistory-italy","title":"微观史学：从《奶酪与蛆虫》到心态史","date":"2026-12-05","category":"西方史学","tags":["微观史学","金兹堡","方法论"],"summary":"金兹堡《奶酪与蛆虫》以十六世纪磨坊主梅诺基奥的审判记录为线索，追问其宇宙观的来源；勒华拉杜里《蒙塔尤》则以一村的审讯文书重建日常生活。微观史缩小观察尺度，用异常个案揭示可能性，却受代表性不足与史料权力结构的质疑。它与心态史、全球史、数字史学的对话仍在继续，尺度与解释力的张力并未真正解决。"},{"id":"oracle-bones-king-list","title":"甲骨与王系：从卜辞重建商代历史","date":"2026-12-15","category":"中国史","tags":["甲骨文","商代","出土文献"],"summary":"1899 年王懿荣在药材龙骨上认出甲骨文字，刘鹗《铁云藏龟》刊布拓本，罗振玉确定出土地为殷墟。王国维以卜辞对照《史记·殷本纪》，证实先公先王世系，提出二重证据法；董作宾以十项标准作五期断代，并借周祭排序王位。殷墟十五次发掘、缀合与数据库检索使材料可用，但卜辞是占卜档案而非编年史，残辞与缺环使复原始终有限。"},{"id":"zoumalou-wu-slips","title":"走马楼吴简：孙吴基层的户籍与赋税","date":"2026-12-14","category":"社会史","tags":["吴简","孙吴","户籍"],"summary":"1996 年长沙走马楼 J22 井出土十万余枚孙吴简牍，年代多在嘉禾年间，属临湘侯国与长沙郡县文书。吏民簿、户口簿逐户登记年龄、身份与田亩，田家莂记录税米、限米、布钱，市租与属吏文书呈现郡县乡里的行政链条。吴简补《三国志》之缺，也暴露账面与实况的落差；残断、缀合与释读歧义，使任何统计都须先交代样本。"},{"id":"tang-exotic-culture","title":"胡风入长安：唐代的异域物质文化","date":"2026-12-13","category":"社会史","tags":["唐代","胡风","物质文化"],"summary":"胡服、胡食、胡乐、粟特聚落、金银器、三彩、马球与三夷教，共同构成唐前期长安的异域物质文化。墓葬壁画与何家村窖藏提供图像与器物证据，十部乐与市肆酒筵显示其制度化与日常化。胡风主要流行于宫廷与城市精英，安史之乱后会昌灭佛使外来宗教收缩。胡是流动的身份标签而非血统实体，将其本质化会误读唐代。"},{"id":"epidemics-late-han","title":"建安大疫：疾病如何改写东汉末年的历史","date":"2026-12-12","category":"社会史","tags":["医疗史","东汉","疫病"],"summary":"《后汉书》记建安二十二年大疫，曹丕《与吴质书》称徐干、陈琳、应玚、刘桢一时俱逝；张仲景自序宗族二百余口十年死三分之二。疫病与战乱、饥荒、迁徙交互，冲击户口、兵源与赋税，也推动医学从方技走向经典。史料只留下症状与死亡数字，没有病原学证据，病原推测与人口差额都须谨慎，大疫是叙事判断而非诊断。"},{"id":"maritime-customs-hed","title":"赫德与近代海关：一个英国人在清廷的三十年","date":"2026-12-11","category":"经济史","tags":["近代史","海关","赫德"],"summary":"1854年江海关改由外籍税务司主持，1863年赫德接任总税务司，以考录、审计与统计建立起当时中国官场罕见的行政理性，并兼办邮政、海务与对外交涉事务；关税随即成为赔款与借款的担保，1911年保管权外移。效率与主权让渡的纠缠贯穿这三十年，也塑造了后世对赫德的两种评价。"},{"id":"medieval-japan-shoen","title":"日本中世的庄园与村落","date":"2026-12-10","category":"世界史","tags":["日本史","庄园","中世"],"summary":"日本中世的庄园并非完整领地，而是本家、领家、预所与名主层层分割的一束收益权；镰仓以后地头与守护不断侵入，庄园在收益被逐层抽空中解体。名主与作人的权利分层，也远非简单的地主租佃关系。与此同时，惣村以寄合、掟与地下请形成自治。庄园与村落长期并存，与欧洲庄园制的比较须有节制，封建标签更不能替代具体制度的描述。"},{"id":"printing-reformation","title":"印刷术与宗教改革：小册子如何改变欧洲","date":"2026-12-09","category":"世界史","tags":["书籍史","宗教改革","印刷"],"summary":"古腾堡的活字印刷在十五世纪中叶成形，半个多世纪后成为路德论战的载体：1518年起，篇幅短、价格低、配木刻插图的德语小册子大量印行，方言圣经与图像把争论带出大学讲坛。罗马的审查与禁书目录随之而来。印刷是条件而非原因，它改变了争论的规模与速度，内容仍来自神学与政治。"},{"id":"bandung-nonalignment","title":"万隆与不结盟：第三世界的登场","date":"2026-12-08","category":"世界史","tags":["冷战史","第三世界","万隆"],"summary":"1955 年万隆会议汇集二十九个亚非国家，以和平共处五项原则为骨架形成十项原则，把反殖民、求发展与政治中立并置；1961 年贝尔格莱德首脑会议将不结盟组织化。运动的价值来自两极结构留给第三方的议价空间，裂痕则多是大国矛盾的投影，中印边界战争与中苏分歧使它从内部被掏空。冷战后档案解密，万隆被还原为各方各取所需的外交操作。"},{"id":"memory-nora","title":"记忆之场：从哈布瓦赫到诺拉","date":"2026-12-07","category":"史学理论","tags":["记忆研究","诺拉","法国史学"],"summary":"哈布瓦赫认为回忆总在群体的框架内进行；诺拉则在 1984 至 1992 年的七卷《记忆之场》里断言，活着的记忆已断裂，剩下的只是替代物。他清点三色旗、《马赛曲》、先贤祠一类符号，把纪念装置视为记忆消失的症状。批评指其法国中心、把记忆本质化；其方法则流入口述史与创伤研究。"},{"id":"digital-humanities-history","title":"数字人文能做什么：历史研究的文本挖掘","date":"2026-12-06","category":"史学理论","tags":["数字人文","方法论","文本挖掘"],"summary":"文本挖掘把读不完的报刊与档案变成可检索、可统计的语料：词频与共现提示话题起落，命名实体识别支撑群体传记与人物网络，地理信息系统接回空间维度，手写识别扩大档案的可及性。这些方法只缩小需要阅读的范围，并不生产意义。风险同样具体：数字化经过选择，识别错误会累积成虚假模式，代码不公开则无法复核。"},{"id":"tang-keju-recruitment","title":"唐代科举与选官：进士、明经与行卷","date":"2026-12-25","category":"制度史","tags":["科举","唐代","选官"],"summary":"唐代贡举分常科与制科，考生来源又有生徒与乡贡之别。明经重记诵、进士重诗赋策论，进士地位在中晚唐逐渐上升。行卷与公卷是考官识别人才的声誉机制，也带来请托与关节。及第仅得出身，还须吏部铨选与守选，释褐多自九品起；门荫与杂流仍占官僚多数，进士科则成为清流标榜。这一格局延续至唐末。"},{"id":"tang-law-code","title":"《唐律疏议》：条文中的帝国秩序","date":"2026-12-24","category":"制度史","tags":["唐律疏议","法律","制度"],"summary":"唐律十二篇五百余条，与令、格、式分工构成规范体系：令设范立制，格禁违正邪，式轨物程事。十恶标出不可赦的威胁，八议把身份纳入量刑程式。疏议以问答、类推与兜底条款，把抽象原则转成官吏可循的判断步骤。敦煌吐鲁番文书可印证制度运行，也显示律文与地方实践之间的距离。律疏的文本层累亦须留意。"},{"id":"qimin-yaoshu","title":"《齐民要术》：北朝农书里的生计","date":"2026-12-23","category":"经济史","tags":["齐民要术","农史","北朝"],"summary":"贾思勰约在六世纪三四十年代任高阳太守，所撰十卷农书以耕作、轮作、畜牧与食物加工为序，把口传经验整理成可操作的工序。书名齐民指平民，序中批评士人轻视农事。知识取自前代农书、农谚与亲身验证，书中亦引南方文献。它写的是良法而非普遍实况，视角限于家户经营，宜作技术史与知识史材料。"},{"id":"genealogy-ming-qing","title":"族谱：宗族如何书写自己","date":"2026-12-22","category":"社会史","tags":["族谱","宗族","明清"],"summary":"明清族谱以序、世系、家训、传记、坟图为体例，始迁祖叙事与通谱冒认构成其建构性的一面。修谱动力来自赋役登记、族产管理与地方权威，祠堂义田提供经济基础。始迁祖以上多不可信，明清部分较可靠；族谱刻印后按房分发、编定字号，须与方志契约互证。它证明的是宗族的自我叙述，而非人口实录。"},{"id":"tibetan-dunhuang-docs","title":"敦煌藏文文书与吐蕃史","date":"2026-12-21","category":"中国史","tags":["敦煌","吐蕃","文书"],"summary":"敦煌藏经洞的藏文写卷里有契约、户籍、驿传与寺院文书，它们记录了吐蕃在河西的部落编制、节儿镇守、计口授田与寺院借贷。古藏文多用无头字，需借汉藏对读与对译词汇校准。写卷是废弃堆积而非完整档案，户籍只登户与丁，编年成于事后，能证明制度如何运作，却不能直接当作人口与事件的全貌。"},{"id":"greek-inscriptions","title":"希腊铭文：刻在石头上的人民","date":"2026-12-20","category":"世界史","tags":["铭文","古希腊","碑刻"],"summary":"雅典的账目碑、法令碑与德尔斐的释奴记录，展示了铭文如何被刻立、公示与保存。行列对齐的刻法与字母形制可用于复原与断代，但石碑的存留极不均匀，能负担刻石费用的也多是城邦与富室。铭文补上了史家著作对工匠、奴隶与外邦人的沉默，也因选择机制而只呈现被公开的事实，不能当作民意的记录。"},{"id":"ottoman-tax-registers","title":"奥斯曼的税册：帝国如何清点人口","date":"2026-12-19","category":"世界史","tags":["奥斯曼","税册","人口史"],"summary":"tahrir 税册由中央派员逐村登录户、丁、土地与税项，详册附法典条文，简册供分配查阅。它服务于蒂玛尔分配与税额确定，而非人口普查，城市、游牧与免税阶层多不在册。hane 是纳税单位，nefer 是成年男子，换算系数仍有争论；册上记的是应纳额，不能直接当作实际人口与收成。"},{"id":"postcolonial-history","title":"后殖民史学：谁有资格书写历史","date":"2026-12-18","category":"史学理论","tags":["后殖民","史学史","庶民研究"],"summary":"从萨义德对东方学的制度性批判与古哈的庶民研究入手，梳理斯皮瓦克对「庶民能否说话」的追问，说明这一视角如何把档案、代言与沉默变成史学问题，并讨论它同民族国家史学的张力、语言中心主义与身份政治化的风险，最后回到档案可及性这一更朴素的问题，兼及中国学界的挪用与误读。"},{"id":"area-studies-cold-war","title":"冷战与区域研究：知识的政治","date":"2026-12-17","category":"史学理论","tags":["冷战","区域研究","学术史"],"summary":"以1958年《国防教育法》与冷战中的中国学、苏联学为例，说明语言训练、基金会资助与政策需求如何共同塑造区域研究，分析其以地区为提问单位的长处与「敌情学」的盲区，并讨论冷战后的重组、学科自主与知识生产的地理分布，指出语言训练与经费结构至今仍是决定研究形状的关键变量。"},{"id":"history-of-emotions","title":"情感史：恐惧、愤怒与眼泪","date":"2026-12-16","category":"史学理论","tags":["情感史","心态史","理论"],"summary":"从斯特恩斯夫妇的「情感学」到罗森宛恩的情感共同体、雷迪的情感体制，梳理情感如何成为历史对象，讨论日记、书信与法庭记录能读出规范与表演、却难以测量实感的限度，以及概念投射、文本偏向与身体维度这三重批评，并简述中国感情史起步较晚的现状，末尾回到「凭什么相信史料里的恐惧」这一证据问题。"},{"id":"yellow-registers-fishscale-maps","title":"黄册与鱼鳞图册：明清国家的两本账","date":"2026-12-16","category":"制度史","tags":["明清","赋役","档案"],"summary":"洪武十四年起，明清国家以黄册登记户口、以鱼鳞图册登记田土，两册互为经纬，共同支撑赋役征派。文章梳理户帖、里甲与十年大造的流程，说明后湖黄册库的保管与查阅制度，分析飞洒诡寄、过割不及时造成的册籍失真，并交代摊丁入亩后黄册废止、鱼鳞图册延续至民国的制度转折，最后讨论徽州文书对今天研究的价值与局限。"},{"id":"juntian-institution","title":"均田制与户籍：从西魏到唐前期","date":"2026-12-26","category":"制度史","tags":["均田制","户籍","隋唐"],"summary":"从西魏大统年间计帐残卷与唐令授田标准入手，说明均田制以户籍、丁中、计帐为核心，赋役按丁口摊派，并非把土地平均分给每户；敦煌吐鲁番文书中应受与已受的落差、土地买卖与人口增殖，使制度在唐前期逐渐松弛，宇文融括户与杨炎两税法相继回应，均田之名遂虚，其重心在税基而非地权，不能当作土地分配运动来理解。"},{"id":"canal-transport-grain","title":"漕运：帝国的粮道与河道","date":"2026-12-25","category":"经济史","tags":["漕运","大运河","财政"],"summary":"以关中缺粮与《史记·平准书》漕转记载切入，梳理秦汉漕渠、隋开运河、裴耀卿分段转运、刘晏以盐利雇运、宋代转般与直达之争，以及明清漕军与治河保漕的矛盾；指出运费常高于粮价，额运数不等于实到数，漕运长期存在源于政治中心与经济区的分离，其兴衰取决于运输技术与市场条件，清末改海运后终归裁撤。"},{"id":"postal-stations-empire","title":"驿传与信息：帝国的速度","date":"2026-12-24","category":"制度史","tags":["驿传","信息传递","邮驿"],"summary":"从秦邮亭、汉悬泉置简牍讲到唐驿、宋递铺、元站赤与明清驿递，分析驿距、运力、符验三者如何决定信息速度，并指出律令所载时限是规范而非实况；驿传的财政负担与私用腐败使其随王朝能力伸缩，驿马不足则政令难达，其本质是帝国治理的神经，速度即控制力的刻度，废弛则政令止于纸面，上下隔膜。"},{"id":"salt-administration-merchants","title":"盐政与商人：明清的国家专卖","date":"2026-12-23","category":"经济史","tags":["盐政","专卖","商人"],"summary":"从产地与销区划分入手，述明开中法、叶淇折银、袁世振纲法与引窝资本化、两淮盐商、陶澍票盐改革及私盐问题；说明专卖以特许把商人纳入财政，国家抽取与商人坐大之间的张力反复拉扯，盐课奏销与盐商资本多属账面或印象，不能径直当作统计，且各地盐法宽严不一，两淮经验尤难推及全国，宜分区域考察。"},{"id":"song-urbanization","title":"市镇与城市：宋代的城市化","date":"2026-12-22","category":"社会史","tags":["宋代","城市","市镇"],"summary":"由坊市制解体与乾德夜市诏令切入，述街市、草市、市镇与税场、行会、雇佣、瓦子及都城人口规模；指出城市化实为市场网络、行政管理与市民生活的重新组合，区域差异明显，而《东京梦华录》与《清明上河图》属追忆与图像材料，不能当作社会统计的底片，其繁华叙述亦经过选择，须与制度条文对读。"},{"id":"granary-famine-relief","title":"常平仓与义仓：帝制中国的仓储救荒","date":"2026-12-21","category":"社会史","tags":["仓储","救荒","灾荒"],"summary":"从汉代常平仓的籴粜平价，到隋唐义仓按户等征纳、宋明预备仓与社仓，梳理帝制中国仓储救荒的制度谱系；分析籴本短绌、仓谷折耗、考成虚报与挪借亏空如何侵蚀仓储的实际能力，并以报灾勘灾的文书链条说明荒政的层级运作，指出仓储救荒的边界与地方士绅的替代作用，仓储因此更像财政与地方治理的组成部分。"},{"id":"double-evidence-method","title":"二重证据法：考古与文献之间","date":"2026-12-20","category":"史学理论","tags":["方法论","出土文献","王国维"],"summary":"以王国维《古史新证》为起点，说明二重证据法如何以甲骨卜辞与《殷本纪》世系互证，重建商先公先王的次序；讨论疑古与信古之争、简帛出土对古书年代与文本形态的改写，并辨析该方法的适用边界：材料独立性、出土时间不等于史事时间，以及三重证据等扩展说法的争议。方法的力量来自材料的独立，限度也在于此。"},{"id":"images-as-sources","title":"图像作为史料：绘画、碑刻与物质文化","date":"2026-12-19","category":"史学理论","tags":["图像","史料","物质文化"],"summary":"从武氏祠画像石入手，讨论图像证史的谱系与限度：墓葬壁画与画像石的粉本与礼仪语境、佛教造像的供养人题记与样式断代、舆图与版画的政治意图、晚清摄影的摆拍与修版；强调图像是被制作的表象，须先做图像志并复原观看位置，才能判断其证据分量：它能显示当时人的自我呈现，不能显示生活实况。"},{"id":"inscriptions-local-society","title":"碑刻与地方社会","date":"2026-12-18","category":"中国史","tags":["碑刻","地方史","石刻"],"summary":"从华北水利碑入手，分述功德碑、去思碑、墓志、祠堂碑、乡约碑的类型与读者，分析石碑凭公开、耐久、不可移动而成为跨代证据的机制，也指出谀墓与自我表扬的局限；兼及金石学拓本传统、碑刻与方志族谱的引用关系，说明碑刻如何补正地方叙事，其价值在生成过程具体而非记载更真。碑刻因此是地方社会的一次公开表态。"},{"id":"global-history-debate","title":"全球史的兴起与争论","date":"2026-12-17","category":"世界史","tags":["全球史","方法论","比较"],"summary":"从白银、生丝与奴隶贸易的链条入手，梳理布罗代尔的经济世界、沃勒斯坦的世界体系、加州学派的大分流与麦克尼尔的疾病生态视角；讨论全球史与民族国家史学的张力、比较与关联两种方法的风险、殖民档案的视角偏向，以及欧洲中心与目的论的批评，说明全球史是一种提问方式，尺度变化会改变问题的提法。"},{"id":"han-chaju-recommendation","title":"察举与乡里评议：汉代选官的社会基础","date":"2027-01-05","category":"制度史","tags":["汉代","察举","选官"],"summary":"从郡国岁举孝廉的实际操作入手，说明员额、科目与乡里评议如何共同构成选举的地方基础，并分析阳嘉限年与策试怎样把乡论部分转为考试；继而讨论举主与故吏的恩义关系、举非其人的连坐成本，以及这套约束为何会被大族与请托消解。最后指出察举的根本难题在于把地方声望换算成中央职位，而声望本身可以被经营。"},{"id":"tang-fangshi-market","title":"坊市之间：唐代城市的管理与生活","date":"2027-01-04","category":"制度史","tags":["唐代","坊市","城市"],"summary":"从长安城的街鼓与坊门启闭入手，说明坊市制如何以墙、门、鼓把交易限定在特定空间与时段，并梳理市署、平准署与行头在管理与中介中的位置；继而分析制度的缝隙与中晚唐坊墙破口、临街开店、夜市兴起的实际过程，指出松动既来自商业压力，也来自管理成本与财政逻辑的变化，坊市制的退出因此是渐进而非断裂的。"},{"id":"song-frontier-markets","title":"榷场：宋代的边境贸易与财政","date":"2027-01-03","category":"经济史","tags":["宋代","榷场","边境贸易"],"summary":"从宋辽边境榷场的查验与征税场景入手，说明榷场同时承担控扼物资、征收商税与外交施压三重职能，并分析其官吏配置、关禁手续、茶马交换结构与控制通道的技术基础；继而讨论私贩难治、岁入数字的编制口径与宋方视角的局限，指出财政与外交冲突时制度通常向政治让步，这是设卡式贸易的通病。"},{"id":"byzantine-theme-system","title":"军区制：拜占庭的兵农合一","date":"2027-01-02","category":"世界史","tags":["拜占庭","军区制","军事"],"summary":"从七世纪阿拉伯扩张下拜占庭野战军的退守入手，说明军区与军役地产如何结合成兵农合一的防御体系，分析将军军政合一的效率与风险，以及这套体系在防御战中的成本优势；继而讨论十世纪以后大地产扩张、军役户破产与佣兵化如何使军区制空心化，指出兵农合一依赖的土地前提难以长期维持。"},{"id":"black-death-europe","title":"黑死病与欧洲社会的重组","date":"2027-01-01","category":"世界史","tags":["黑死病","中世纪","人口"],"summary":"从1347年热那亚船队把疫病带回西西里入手，说明黑死病的传播路径、病原争议与死亡率估算的材料困难；继而分析人口锐减如何改变劳动力价格与地租、推动农奴制松动与劳工立法，并讨论教会解释、替罪羊迫害与港口检疫的初步制度化，指出疫病加速了疫前已存在的结构变化而非将其打断。"},{"id":"ming-wei-suo","title":"卫所与军户：明代的军事户籍","date":"2026-12-31","category":"制度史","tags":["明代","卫所","军户"],"summary":"卫所把兵役编成世袭的军籍，用军屯就地供养，征集成本因此降低，代价则由军户家庭承担。军丁册、勾军簿与清军文册证明的是登记口径与行政意图，不是实际在役人数；以册籍估算兵力，容易把制度想象得比实态整齐。逃军、顶替与屯田侵占并非单纯的败坏，而是这套身份兵役制运行的常态。制度的惯性往往来自沉没成本，而不是效能。"},{"id":"qing-fiscal-audit","title":"钱粮奏销：清代的财政审计与亏空","date":"2026-12-30","category":"经济史","tags":["清代","奏销","财政"],"summary":"清代奏销以四柱册与层层核销构成审计框架，账面平衡可借挪新掩旧与摊入民欠达成，户部所核是格式与印结，而非实存。亏空源于垫支、摊捐、灾缓与吏役侵挪，弥补则靠摊赔、追补与捐输。雍正清查与养廉银使地方经费正规化，却未消除亏空，真正的约束在人事与监督。册籍格式的完善与财政能力的提升，并不是同一件事。"},{"id":"atlantic-slave-trade","title":"大西洋奴隶贸易与它的账本","date":"2026-12-29","category":"世界史","tags":["奴隶贸易","大西洋","经济史"],"summary":"奴隶贸易的账本把航次记成货物、保险与佣金，风险经海上保险与合伙制分摊，使远距离贸易成为可计算的生意。船运记录与种植园账簿能证明数量、价格与死亡率，却很少记下被奴役者的名字。废奴之后，契约工、学徒制与殖民扩张接续了旧的劳动关系，奴隶贸易实为大西洋经济的基础设施。账本的分类方式，让暴力在流通中不必被看见。"},{"id":"meiji-shizoku","title":"明治维新与士族的解体","date":"2026-12-28","category":"世界史","tags":["明治维新","士族","近代化"],"summary":"废藩置县与秩禄处分拆解了武士的身份依托，金禄公债与士族授产把家禄转为资本或生计，受益者多是上层士族。士族凭识字、文书与纪律进入官僚、军队与学校，失意者则投入士族叛乱与自由民权运动。维新把身份等级拆成职业流动，而不是把武士变成资本家。制度的废除与社会关系的延续，是两件不同的事。"},{"id":"book-history-reading","title":"书籍史与阅读史：书是怎么被读的","date":"2026-12-27","category":"史学理论","tags":["书籍史","阅读史","方法论"],"summary":"书籍史把文本、印刷、流通与阅读分为四层，版本、序跋与版式等副文本塑造读者接近正文的方式。藏书印、批校与书目分别证明递藏、停留与著录，也都受存世偏差与抽样限制。阅读史要回答的不是读了什么，而是在什么条件下、以什么方式读。材料的证明力各不相同，混用便容易得出过强的结论。"},{"id":"archive-turn","title":"档案转向：历史学如何被档案重塑","date":"2027-01-25","category":"史学理论","tags":["档案","方法论","史料"],"summary":"档案转向把档案馆从史学的后勤设施变成研究对象。文章从苏联档案开放、殖民档案的分类技术与数字检索三处入手，说明全宗、案卷与保密期限如何筛除一部分过去，辨析福柯意义上的档案与实体档案馆的区别，主张把筛选机制本身写进论证，让档案研究成为对权力如何保存记忆的追问，而不只是史料存放的地点。"},{"id":"spatial-turn-history","title":"空间转向：地理与历史学的交汇","date":"2027-01-24","category":"史学理论","tags":["空间","地理","方法论"],"summary":"空间转向质疑把行政单元当作社会生活天然容器的习惯。文章梳理布罗代尔的长时段、列斐伏尔的空间生产、施坚雅的区域体系与华南的区域研究，讨论地方志、古地图、铁路与地理信息系统的证据边界，主张空间不是背景，而是被权力与生计持续生产出来的关系，这种关系还会随尺度选择而变化。"},{"id":"material-culture-turn","title":"物质文化转向：物如何进入历史","date":"2027-01-23","category":"史学理论","tags":["物质文化","博物馆","方法论"],"summary":"物质文化转向主张物不只是观念的载体，物本身参与社会关系的构成。文章以瓷器、纺织品与建筑为例，讨论物的传记、流通史与博览会陈列，分析博物馆如何把物抽出原境，追问器物、出土情境与账簿各自能证明什么，并指出收藏与修复同样参与历史叙述，物的意义在流转与反复使用中不断被改写。"},{"id":"animal-turn-history","title":"动物史：历史的非人参与者","date":"2027-01-22","category":"史学理论","tags":["动物史","环境史","方法论"],"summary":"动物史要把公文里的一行马匹倒毙记录读成一个系统。文章比较动物作为资源与动物作为行动者两种写法，以马政、牛耕与城市动物为例，讨论账簿、奏报、兽医书与动物骨骼的证据边界，主张把动物理解为受生理与制度双重约束的行动者，并说明证据为何必须跨材料拼接，而不是只当作背景或象征符号。"},{"id":"disability-history","title":"残障史：被忽略的历史经验","date":"2027-01-21","category":"史学理论","tags":["残障史","社会史","方法论"],"summary":"残障史从质疑医疗模式开始，把障碍看作环境与制度的产物。文章以唐律的残疾分等、伤残军人抚恤、盲人说唱与慈善机构为例，讨论损伤如何被换算成等级与资源，分析机构档案与口述材料的边界，反省代言与时代错置的风险，并把家庭照护劳动纳入视野，追问正常范畴如何被制造，而不是天然给定的。"},{"id":"childhood-history","title":"童年史：孩子如何被历史看见","date":"2027-01-20","category":"史学理论","tags":["童年史","家庭史","方法论"],"summary":"从阿里耶斯《儿童的世纪》关于「童年发现」的论断入手，梳理人口史家与儿童史研究者对其图像证据与断代方案的批评，进而讨论儿童在传统档案中近乎失声的结构性原因，逐一评估玩具、教材、画像与诉讼记录这些替代证据能证明什么、不能证明什么，并指出童年观念史与儿童经验史的分界。"},{"id":"chinese-marxist-historiography","title":"中国马克思主义史学的形成与变化","date":"2027-01-19","category":"史学理论","tags":["马克思主义史学","近代","学术史"],"summary":"从1930年前后的中国社会史论战讲起，说明分期问题为何同时是学术判断与政治追问，继而梳理五朵金花时期的议题设置、通史编纂与史料整理实绩，分析理论框架的组织能力如何转化为教条化的代价，最后区分这一传统留下的结论与仍然可用的史料工作，并指出亚细亚生产方式争论的反复。"},{"id":"japanese-postwar-historiography","title":"日本战后史学：从马克思主义到社会史","date":"2027-01-18","category":"史学理论","tags":["日本","战后","史学史"],"summary":"从1932年日本资本主义论战中讲座派与劳农派的分歧出发，追踪其如何塑造战后历史学研究会的共同研究体制，再由民众史、社会史与历史人口学的转向，讨论分析单位下移带来的材料变化与整合困难，以及殖民地史和战争责任问题对日本史学的持续压力，并说明共同框架消散后的碎片化局面。"},{"id":"great-war-historiography","title":"一战与历史学的断裂","date":"2027-01-17","category":"世界史","tags":["一战","史学史","欧洲"],"summary":"从凡尔赛条约第231条的法律措辞与德国方面的档案论战入手，追踪战争罪责争论如何把外交史变成文件编纂史，再经菲舍尔之争转入社会史与文化史，讨论总体战经验如何改变历史学家对国家、暴力与普通人的理解，辨析法律文本与史学判断的区别，以及档案开放不均衡造成的限制，并提示这场争论往往先于档案的完整开放。"},{"id":"nineteenth-century-public-health","title":"十九世纪的公共卫生与城市治理","date":"2027-01-16","category":"世界史","tags":["公共卫生","城市","19世纪"],"summary":"从1854年伦敦布罗德街霍乱与斯诺的调查讲起，说明瘴气说与卫生统计如何共同塑造城市治理，再以伦敦下水道、巴黎改造与纽约公寓立法为例，分析统计与警察权的互补机制及其分配后果，检讨死亡率数据、改革者报告与归因难题的史料局限，并指出这套治理在提高平均寿命的同时也生产了新的空间不平等。"},{"id":"colonial-medicine","title":"殖民医学：疾病、权力与身体","date":"2027-01-15","category":"世界史","tags":["殖民","医疗史","帝国"],"summary":"从1896年孟买鼠疫的防疫队写起，梳理隔离、疫苗与城市卫生分区如何把殖民地人口变成可登记、可分区的治理对象，也梳理被检查者的反抗与日常协商。文章分析热带医学把病因归于气候与种族的解释偏差，讨论卫生报告、死亡统计与民族主义叙述各自的视角限制，最后回到医学同时作为治理工具与抵抗场域这一双重性。"},{"id":"inca-quipu-records","title":"印加的结绳：没有文字的帝国账本","date":"2027-01-14","category":"世界史","tags":["印加","结绳","文字"],"summary":"从一件存世结绳的形制与1912年洛克对十进制位值的发现入手，讨论结绳的计数、行政与可能的叙事功能，并检讨「无文字社会」这一概念的局限。文章还分析殖民时期的销毁、收藏与诉讼文书如何过滤了被征服者的记忆，以及现代数据库方法带来的新可能与新风险，并指出结绳研究至今仍缺少可独立验证的解读钥匙。"},{"id":"mughal-fiscal-system","title":"莫卧儿的财政与军事采邑","date":"2027-01-13","category":"世界史","tags":["莫卧儿","财政","制度"],"summary":"从十六世纪后期的土地清丈与税率手册入手，解释曼萨卜等级与贾吉尔采邑如何把军事服务与田赋收入绑定，以及这套安排为何在十七世纪后期因贾吉尔短缺、包税流行而松动。文章兼及扎明达尔中间人、白银依赖与行政手册、旅行者记载的史料局限，并指出这套交换结构的效率与脆弱同源，评价它需要看交换得以维持的条件。"},{"id":"ottoman-millet-system","title":"奥斯曼的米勒特：帝国如何管理宗教共同体","date":"2027-01-12","category":"世界史","tags":["奥斯曼","宗教","制度"],"summary":"从宗主教特权文书与卡迪法庭的司法边界入手，说明米勒特并非征服之初既有的成体系自治，而是逐步系统化并被后世回溯建构的安排。文章分析授权换忠诚、责任下沉的治理机制，检讨「奥斯曼宽容」叙事的偏差，比较文书、领事报告与法庭登记册的不同视角，并强调这套安排的等级性与弹性来自同一处模糊。"},{"id":"medieval-monastic-scriptoria","title":"修道院的书写室：中世纪的知识生产","date":"2027-01-11","category":"世界史","tags":["中世纪","修道院","书籍史"],"summary":"从一部九世纪圣经抄本的制作工序入手，说明书写室如何以分工、排期与跨院网络成为中世纪的知识工厂，并讨论抄写变异、藏书目录与选择性保存。文章还检讨题记、目录与留存样本各自的史料局限，讨论女性抄写与印刷术冲击下书写室的转型，以及这套工序为何既能保存文本，也会在复制与筛选中改变文本。"},{"id":"renaissance-patronage","title":"文艺复兴的赞助人：艺术与权力","date":"2027-01-10","category":"世界史","tags":["文艺复兴","赞助","艺术史"],"summary":"文艺复兴的艺术品多半不是自由创作，而是合同、材料与家族声誉共同约束下的委托产物。本文从佛罗伦萨行会壁龛、美第奇家族礼拜堂与教皇工程入手，梳理委托流程、题材协商、作坊分工与付款方式，分析赞助如何把资金转换为政治与宗教符号，并检讨天才叙事对委托关系的遮蔽，以及合同与传记两类史料各自的证明限度。"},{"id":"reformation-marriage","title":"宗教改革与婚姻：从圣礼到契约","date":"2027-01-09","category":"世界史","tags":["宗教改革","婚姻","社会史"],"summary":"宗教改革把婚姻从七圣礼之一改写为世俗契约，管辖者、登记方式与离婚条件随之改变。本文从路德一五二五年的婚礼说起，讨论修道院解散后的婚配市场、嫁妆谈判、新教家庭伦理的双面性，以及特兰托会议与英格兰登记册的不同路径，并检讨登记册与布道文本作为史料能证明什么、不能证明什么，女性的处境为何是混合的。"},{"id":"early-modern-censorship","title":"近代早期的书报审查","date":"2027-01-08","category":"世界史","tags":["审查","书籍史","近代早期"],"summary":"许可、登记与垄断构成近代早期审查的链条，禁书目录只是其中一环。本文从英格兰书商公会、罗马禁书目录与十七世纪法国的特许制度入手，讨论审查的执行机构、出版地理与文体如何被重塑，地下印刷的成本如何转嫁给读者，手稿在严审之下如何继续流通，并检讨禁书目录与实际流通之间的落差。"},{"id":"qin-documentary-administration","title":"秦的文书行政：从里耶秦简看帝国的日常运转","date":"2027-01-07","category":"中国史","tags":["秦代","文书","行政"],"summary":"里耶秦简把秦帝国的日常行政还原为可追溯的文书流程。本文以迁陵县的簿籍、邮书与考课为例，分析文书格式如何标记层级与责任，上计与劾制如何形成闭环，封检、副本与书体又如何支撑这套流程，并检讨这批废弃档案的代表性，以及簿籍数字与实际执行之间的距离。秦的行政成本，就藏在这些细节里。"},{"id":"han-frontier-tuntian","title":"汉代的屯田：边疆的粮食与兵","date":"2027-01-06","category":"中国史","tags":["汉代","屯田","边疆"],"summary":"居延汉简里的名册与农具簿，让屯田的组织与账目变得可见。本文讨论汉代屯田的动因、层级、水利条件与收成分配，以及它在军事后勤与移民实边之间的双重角色，并检讨简牍材料在产量与自给率问题上的限度，以及居延一地能否代表整个边疆。戍卒、刑徒与假田贫民的身份差异，也在讨论之列。"}];

const snippets = [{"id":"ming-drought","title":"崇祯二年北京大旱：一份奏折里的灾情实录","source":"“《明实录·崇祯实录》卷二”","date":"2026-06-14","tags":["明代","灾荒","原始史料"],"excerpt":"“臣巡视南城，见饥民塞道，鬻子女者不可胜计。至五月不雨，赤地千里，米价腾涌，斗米直银三钱。臣窃惟京城根本重地，若不大施赈济，恐生他变。”","commentary":"<p>这条来自御史梁子璠的奏疏，寥寥数语勾勒出崇祯二年（1629年）京城的惨状。“鬻子女者不可胜计”七字，比任何史论都更有冲击力。崇祯朝正处于内忧外患的关口——辽东战事未平、陕西流寇初起，而京畿又遭大旱。明王朝的崩溃，从气候史的角度看，也并非偶然。小冰河期的极端气候与晚明社会危机，值得深思。</p>"},{"id":"sima-guang-letter","title":"司马光写给王安石的一封信","source":"“《司马温公集》卷六十”","date":"2026-06-13","tags":["宋代","书信","王安石变法"],"excerpt":"“介甫文章节义，过人远甚。但天性不晓事，而喜遂非。致忠直疏远，谗佞辐辏。又置条例司，大讲财利之事。今人皆知利之可兴，而不知其害之不可胜言也。”","commentary":"<p>这封信写于熙宁三年（1070年），是新旧党争初起时的一份珍贵文献。司马光与王安石曾是好友，在政治理念上却水火不容。司马光语气尚属平和，但“天性不晓事，而喜遂非”的批评已相当尖锐。两人都认为自己是在“为国为民”，却走上全然对立的道路。这场争论折射出的正是儒家传统中“义利之辨”的深层张力。</p>"},{"id":"yuan-ye-travel","title":"元代一个普通人从大都到杭州的旅行日记","source":"“《析津志辑佚》”","date":"2026-06-12","tags":["元代","社会生活","旅行"],"excerpt":"“延祐三年春，予自大都启行，沿御河南下。四月初至通州，见运河中粮船如织。过直沽，海舶鳞集，商贾云屯。至临清，始见棉花铺遍野。过扬州，市井繁华，不减大都。五月抵杭州，真东南第一州也。”","commentary":"<p>这段记载出自元代熊梦祥《析津志》，描述了从大都（今北京）沿运河到杭州的旅途见闻。京杭大运河是元代南北大统一的动脉，不仅运输物资，也传递着文化和信息。“棉花铺遍野”的细节透露出元代农业经济的重要变化——棉花的推广种植，这场“衣被天下”的革命，正静悄悄地改变亿万人的生活。</p>"},{"id":"song-dibao","title":"宋代邸报：中国最早的官方新闻发布制度","source":"“《宋会要辑稿·职官》”","date":"2026-06-15","tags":["宋代","信息传播","制度"],"excerpt":"“进奏院每五日具报，事无大小，皆申枢密院。边报则日奏，军期急速则不时入递。”","commentary":"<p>邸报是中国最早的官方新闻发布制度，起源于唐代，成熟于宋代。宋代设进奏院统一管理邸报的编发，内容涵盖皇帝诏令、官员任免、边疆军情等。宋代还出现了‘小报’——一种民间私自编印的新闻传单，可以视为中国古代的‘地下媒体’。</p>"},{"id":"ming-yitiao","title":"万历初年张居正推行一条鞭法的原始档案","source":"“《明史·食货志》《张文忠公全集》”","date":"2026-06-15","tags":["明代","财政改革","张居正"],"excerpt":"“总括一州县之赋役，量地计丁，丁粮毕输于官。一岁之役，官为佥募。凡额办、派办、京库岁需与存留、供亿诸费，悉并为一条，皆计亩征银，折办于官。”","commentary":"<p>一条鞭法是中国古代赋役制度史上最重要的一次改革。张居正在万历年间将其推向全国，核心是将各种名目的赋税徭役合并为一项，按田亩征收银两。这一改革简化了税收程序，减少了官吏中饱私囊的机会，推动了实物经济向货币经济的转型。</p>"},{"id":"qing-dianbao","title":"李鸿章奏请创办中国电报局的奏折","source":"“《李文忠公全书·奏稿》卷四十四”","date":"2026-06-15","tags":["晚清","洋务运动","通信史"],"excerpt":"“用兵之道，神速为贵。泰西各国，遍设电报，瞬息千里，军情易达。中国驿站虽设，迟速悬殊。”","commentary":"<p>李鸿章于光绪六年（1880年）上奏请求创办中国电报局。一年后中国第一条电报线路——天津至上海线——建成通车。电报的到来深刻改变了中国社会的时空感知：信息传递从以天为单位变成了以分钟为单位。</p>"},{"id":"baekgang-record","title":"白江口之役的唐军记录","source":"《旧唐书·刘仁轨传》","date":"2026-08-05","tags":["唐代","白江口","海战"],"excerpt":"“仁轨遇倭兵于白江之口，四战捷，焚其舟四百艘，烟焰涨天，海水皆赤，贼众大溃。”","commentary":"<p>这段记载出自《旧唐书·刘仁轨传》，是白江口之战最核心的汉文史料。短短三十余字，却包含了交战地点、战况烈度与最终结果三项关键信息。烟焰涨天、海水皆赤的描写，让人得以想象那场海战的惨烈。值得注意的是，正史记载以唐军胜利者视角书写，若对照《日本书纪》的记载，双方伤亡数字与战术细节尚有出入，这也提醒我们：即使是最直接的史料，也需要在多方对照中审慎使用。</p>"},{"id":"enin-journey","title":"圆仁《入唐求法巡礼行记》中的海上见闻","source":"圆仁《入唐求法巡礼行记》卷四","date":"2026-08-01","tags":["唐代","海上交通","日记"],"excerpt":"“十四日，海面茫茫，不见山岛。船头诸人皆忧，恐失航路。幸而有北风，船行如飞，日行百余里。”","commentary":"<p>日本求法僧圆仁的《入唐求法巡礼行记》，与玄奘《大唐西域记》、马可·波罗游记并称东方三大旅行记。圆仁于838年随遣唐使入唐，滞留近十年，以日记体记录了一路的见闻。这段关于海上航行的文字，保存了九世纪东亚航海技术、气象知识与海路险阻的珍贵细节。更难得的是，他的日记视野不止于佛寺，还记录了唐末地方社会、乡村经济与武宗灭佛等重大事件，是研究唐代社会史的独特史料。</p>"},{"id":"suishu-dongyi","title":"《隋书·东夷传》高句丽条","source":"《隋书》卷八十一《东夷传》","date":"2026-07-28","tags":["隋代","高句丽","原始史料"],"excerpt":"“高句丽，在辽东之东千里，南接朝鲜、濊貊，东据大海，西与燕接。其国东西二千里，南北千余里，都于平壤城，亦曰长安城。”","commentary":"<p>《隋书·东夷传》是系统记载高句丽地理、制度与隋朝关系的第一手文献。这段文字点明了高句丽的四至方位与都城所在，是复原其疆域的基础史料。隋唐两代对高句丽的征伐，始终与辽东领土争端纠缠在一起——隋炀帝三征高句丽更直接动摇了隋朝的统治根基。透过这条史料，可以切入一个更大的问题：为何一个半岛政权能够成为大一统王朝的远征目标？高句丽的城池防御、山地地形与政权韧性，都是关键变量。</p>"},{"id":"salsu-rout","title":"萨水之败：九军三十万五千的结局","source":"《资治通鉴》卷一八一，隋纪五","date":"2026-11-20","tags":["隋唐","高句丽","军事"],"excerpt":"初，九军渡辽，凡三十万五千，及还至辽东城，唯二千七百人，资储器械巨万计，失亡荡尽。","commentary":"<p>这条出自《资治通鉴》隋纪五，是大业八年第一次征辽失败之后的一句总结。三十万五千人渡辽，退回辽东城时只剩二千七百，资储器械尽数丧失。两组数字并置，比任何描写都更直接地说明了这场远征的结局。萨水一战的具体过程，同卷前文另有叙述：宇文述等军渡萨水，半渡之际为高句丽军所击，于是大溃。</p>"},{"id":"eulji-poem","title":"乙支文德致于仲文的四句诗","source":"《三国史记》卷四十四，乙支文德传","date":"2026-11-19","tags":["高句丽","隋唐","史料"],"excerpt":"神策究天文，妙算穷地理。战胜功既高，知足愿云止。","commentary":"<p>这是《三国史记·乙支文德传》所记的一首五言四句诗，作于大业八年隋军进逼平壤之际，通常题为《遗于仲文诗》。于仲文是隋军九军之一的主将，与宇文述同掌东征陆军。全诗只二十字，却同时是一份战书与一段外交辞令。</p>"},{"id":"taizong-withdraw","title":"唐太宗班师：辽左早寒，草枯水冻","source":"《资治通鉴》卷一九八，唐纪十四","date":"2026-11-18","tags":["唐代","唐太宗","高句丽"],"excerpt":"上以辽左早寒，草枯水冻，士马难久留，且粮食将尽，癸未，敕班师。","commentary":"<p>此条出自《资治通鉴》唐纪十四，贞观十九年九月。唐太宗亲征高句丽，连下辽东、白岩诸城，至安市城久攻不下，最终以天寒粮尽撤军。短短一句，把撤兵的两个理由写得很清楚：季节与粮食。</p>"},{"id":"gaesomun-origin","title":"泉盖苏文：自云生水中以惑众","source":"《新唐书》卷二二〇，东夷传·高句丽","date":"2026-11-17","tags":["高句丽","政治","唐代"],"excerpt":"有盖苏文者，或号盖金，姓泉氏，自云生水中以惑众。","commentary":"<p>此条出自《新唐书·东夷传》高句丽条，记泉盖苏文的出身传说。「自云生水中以惑众」是史家对其神异自述的贬抑写法：当事人借神异建立威望，修史者则用「惑众」二字定性，一褒一贬之间，正是官方史书处理民间信仰的惯常笔法。</p>"},{"id":"andong-prefecture","title":"平壤设安东都护府：九都督府、四十二州、一百县","source":"《唐会要》卷七十三，安东都护府","date":"2026-11-16","tags":["唐代","制度","高句丽"],"excerpt":"分高丽地为九都督府、四十二州、一百县，置安东都护府于平壤城以统之，擢其酋渠为都督及刺史、县令，与华人参理。","commentary":"<p>此条出自《唐会要》卷七十三「安东都护府」条，记总章元年（668）平定高句丽之后的建置。九都督府、四十二州、一百县，是把高句丽旧有五部一百七十六城重新编制的结果；都护府设于平壤，说明唐廷最初打算以半岛北部为治所直接统辖。</p>"},{"id":"baorenan-shu-purpose","title":"究天人之际，通古今之变：司马迁的自述","source":"《汉书》卷六十二《司马迁传》所引《报任安书》","date":"2026-11-21","tags":["司马迁","史学史","史记"],"excerpt":"亦欲以究天人之际，通古今之变，成一家之言。","commentary":"<p>《汉书》卷六十二《司马迁传》以大半篇幅收录《报任安书》，这在正史中并不常见。此信是司马迁答复任安责其不肯推贤进士之作，写信时他任职中书令，距受刑已数年，信中自述忍辱著书的始末。今本文字经班固剪裁入传，与《文选》所载《报任少卿书》略有异文，字句互有详略，读时宜两本对看。</p>"},{"id":"zizhi-san-jing","title":"三镜之说：唐太宗论魏徵","source":"《资治通鉴》卷一九六，唐纪十二","date":"2026-11-22","tags":["唐太宗","资治通鉴","贞观之治"],"excerpt":"人以铜为镜，可以正衣冠；以古为镜，可以见兴替；以人为镜，可以知得失。魏徵没，朕亡一镜矣！","commentary":"<p>此条见《资治通鉴》卷一九六唐纪十二，系于贞观十七年。司马光编纂此书，采摭实录、国史与传记，以年为经、以事为纬，此段即编年叙事中插入的君臣言语。魏徵卒于贞观十七年正月，太宗临哭，罢朝五日，随后有是语，语境与单纯的议论并不相同。唐纪长编由范祖禹分修，取材于实录与柳芳《唐历》诸书，故记事虽简，渊源有自。</p>"},{"id":"rizhi-baotianxia","title":"亡国与亡天下：顾炎武的判别","source":"《日知录》卷十三「正始」条","date":"2026-11-23","tags":["顾炎武","日知录","明清之际"],"excerpt":"是故知保天下，然后知保其国。保国者，其君其臣肉食者谋之；保天下者，匹夫之贱，与有责焉耳矣。","commentary":"<p>《日知录》卷十三「正始」条是顾炎武的读书札记，全书积三十余年而成，每条博引群书，末乃断以己意。条题「正始」取魏齐王正始年间玄谈误国之义，故由清谈亡国发端，层层推至亡国与亡天下之辨，非孤立的一句口号。顾氏所虑，实在名教与风俗之衰。今本经黄汝成《日知录集释》校补，引文与案语较备，然分条与文字仍有版本差异。</p>"},{"id":"huozhi-moye","title":"末业之资：太史公论求富","source":"《史记》卷一百二十九《货殖列传》","date":"2026-11-24","tags":["史记","社会经济史","货殖列传"],"excerpt":"夫用贫求富，农不如工，工不如商，刺绣文不如倚市门，此言末业，贫者之资也。","commentary":"<p>《史记》卷一百二十九《货殖列传》为司马迁所创，此前史书无专记货殖之作。传中列举各地物产、风俗与商贾行事，末以「夫用贫求富」一段总括生计次第。所记上起春秋，下迄汉武，多以人物行迹系于各地物产之下。文本间有错简与后人附益之说，然大体可据，通行点校本已作校勘。</p>"},{"id":"wentongkao-xu","title":"理乱兴衰与典章经制：马端临的编纂之志","source":"《文献通考》自序","date":"2026-11-25","tags":["马端临","文献通考","史学史"],"excerpt":"窃尝以为理乱兴衰，不相因者也；典章经制，实相因者也。","commentary":"<p>《文献通考》三百四十八卷，马端临撰，自序述其著书缘起与体例。马氏生于宋末，宋亡后家居著述，长期教授乡里，以二十余年之力成此书，分二十四门，上承《通典》而增益其目。书成于大德十一年前后，门类自田赋、钱币至四裔、草木，包罗甚广。序文自陈「理乱兴衰」与「典章经制」之别，实为全书的总纲。</p>"},{"id":"zuozhuan-three-imperishable","title":"三不朽：立德、立功、立言","source":"《左传·襄公二十四年》","date":"2026-12-05","tags":["先秦","史学观念","左传"],"excerpt":"太上有立德，其次有立功，其次有立言，虽久不废，此之谓不朽。","commentary":"<p>《左传》是编年体史书，记事起鲁隐公元年，止于哀公二十七年，成书时间一般认为是战国前期，以鲁国纪年统摄列国。这段对话见于襄公二十四年，即公元前五四九年，鲁国大夫叔孙豹出使晋国，晋国执政范宣子迎宾时问起「死而不朽」。文体是记言为主的辞令，语言整饬，经战国时人整理，未必是现场原话。</p>"},{"id":"mengzi-trust-books","title":"尽信书，则不如无书","source":"《孟子·尽心下》","date":"2026-12-04","tags":["先秦","史料批判","孟子"],"excerpt":"尽信书，则不如无书。吾于武成，取二三策而已矣。","commentary":"<p>《孟子》七篇，一般认为是孟子与其弟子万章、公孙丑等所记，成书于战国中期，《尽心下》多记其晚年议论。这段评论的是《尚书·武成》篇。孟子说「尽信书，则不如无书」，又说对《武成》只「取二三策」。「书」在这里指《尚书》，「策」是竹简，二三策即寥寥几片简，意思是只采信很小一部分。</p>"},{"id":"hanshu-yiwenzhi","title":"诸子十家：九家可观","source":"《汉书》卷三十《艺文志》","date":"2026-12-03","tags":["汉代","目录学","学术史"],"excerpt":"诸子十家，其可观者九家而已。","commentary":"<p>《汉书》十志之一，卷三十《艺文志》，班固撰，东汉前期成书。它删取西汉刘向《别录》、刘歆《七略》而成，是中国现存最早的图书分类目录，一般统计著录五百九十余家、一万三千余卷。体例是先列书名篇卷，后附小序述学派源流。此句在诸子略总序之末，是对十家的总评。</p>"},{"id":"tongjian-names","title":"天子之职莫大于礼","source":"《资治通鉴》卷一，周纪一","date":"2026-12-02","tags":["宋代","史学","资治通鉴"],"excerpt":"臣闻天子之职莫大于礼，礼莫大于分，分莫大于名。何谓礼？纪纲是也；何谓分？君臣是也；何谓名？公、侯、卿、大夫是也。","commentary":"<p>《资治通鉴》是北宋司马光主持编纂的编年体通史，起周威烈王二十三年（前四〇三年）三家分晋，迄五代后周世宗显德六年，共二百九十四卷。卷一开篇即记「初命晋大夫魏斯、赵籍、韩虔为诸侯」，紧接着是「臣光曰」的史论。史论以「臣光曰」标出，是作者直接出场议论之处，也是全书政治立场最集中的地方。</p>"},{"id":"liuzongyuan-fengjian","title":"封建非圣人之意，势也","source":"柳宗元《封建论》","date":"2026-12-01","tags":["唐代","制度史","柳宗元"],"excerpt":"封建非圣人之意也，势也。","commentary":"<p>柳宗元（七七三—八一九），字子厚，河东人，永贞革新失败后贬永州司马，后为柳州刺史。《封建论》一般认为是贬谪永州期间所作，收入《柳河东集》。文体是论说文，以设问驳难层层推进，是唐代讨论分封与郡县问题最系统的文章。此句是全文的论断句，下文全部围绕它展开。文章历论周、秦、汉、唐四代，末段还以唐代方镇之害作结，说「失不在于州而在于兵」。</p>"},{"id":"huangzongxi-yuanjun","title":"天下为主，君为客","source":"黄宗羲《明夷待访录·原君》","date":"2026-11-30","tags":["明清之际","政治思想","黄宗羲"],"excerpt":"古者以天下为主，君为客，凡君之所毕世而经营者，为天下也。","commentary":"<p>黄宗羲（一六一〇—一六九五），字太冲，号南雷，浙江余姚人，明亡后不仕，讲学著述。《明夷待访录》成于康熙二年，书名取《周易》明夷卦，意为在晦暗之世等待后人。全书二十一篇，《原君》居首，文体是政论，托三代立论，语气激切，是明清之际政治批判的代表作。</p>"},{"id":"wangfuzhi-junxian","title":"郡县之势：垂二千年而弗能改","source":"王夫之《读通鉴论》卷一","date":"2026-11-29","tags":["明清之际","制度史","王夫之"],"excerpt":"郡县之制，垂二千年而弗能改矣，合古今上下皆安之，势之所趋，岂非理而能然哉？","commentary":"<p>王夫之（一六一九—一六九二），字而农，号姜斋，湖南衡阳人，明亡后曾举兵抗清，晚年隐居石船山，人称船山先生。《读通鉴论》三十卷，是就《资治通鉴》所载史事逐条评论的史论集，撰于晚年。卷一论秦事，此句出自其中论郡县的一条。文体是札记式史论，长于辨析制度得失。</p>"},{"id":"zhangxuecheng-liujing","title":"六经皆史","source":"章学诚《文史通义·易教上》","date":"2026-11-28","tags":["清代","史学理论","章学诚"],"excerpt":"六经皆史也。古人不著书，古人未尝离事而言理，六经皆先王之政典也。","commentary":"<p>章学诚（一七三八—一八〇一），字实斋，浙江会稽人，乾隆四十三年进士，一生多任书院讲席、纂修地方志。《文史通义》撰于乾隆至嘉庆间，是继《史通》之后最重要的史学理论著作。《易教上》为内篇之首，此句开宗明义。文体是专论与札记结合，思辨性强，与当时盛行的考据学风有明显距离。</p>"},{"id":"dutong-dianxu","title":"食货为先：杜佑的编纂次序","source":"杜佑《通典》自序","date":"2026-11-27","tags":["唐代","典章制度","杜佑"],"excerpt":"所纂通典，实采群言，征诸人事，将施有政。","commentary":"<p>杜佑（七三五—八一二），字君卿，京兆万年人，历仕玄宗至宪宗，官至宰相，封岐国公。《通典》二百卷，大历年间始撰，贞元十七年成书进献，是中国第一部典章制度通史。全书分食货、选举、职官、礼、乐、兵、刑法、州郡、边防九门，以食货居首。自序述编纂缘起与体例，此句在序中，标明全书宗旨。杜佑久任地方与中央的财政、军事职务，此书有实际政务的经验背景。</p>"},{"id":"zhaoyi-buyi-jiangxiang","title":"布衣将相：秦汉之际的社会流动","source":"赵翼《廿二史札记》","date":"2026-11-26","tags":["清代","秦汉史","社会流动"],"excerpt":"其君既起自布衣，其臣亦自多亡命无赖之徒，立功以取将相，此气运为之也。","commentary":"<p>赵翼（一七二七—一八一四），字云崧，号瓯北，江苏阳湖人，乾隆二十六年进士，曾在军机处行走，后出任广西、贵州地方官，晚年归里著述。《廿二史札记》三十六卷，成于嘉庆年间，以札记形式条列正史史事，归纳比较。此条在卷二，题「汉初布衣将相之局」。文体是读史札记，不逐句注解，而是提出问题、排比证据。</p>"},{"id":"shangshu-wuyi","title":"无逸：君子所其无逸","source":"《尚书·周书·无逸》","date":"2026-12-15","tags":["尚书","西周","政治思想"],"excerpt":"周公曰：呜呼！君子所，其无逸。先知稼穑之艰难，乃逸，则知小人之依。","commentary":"<p>《尚书》今文二十八篇之一，属《周书》，文体为诰诫之辞，记周公还政成王之后对成王的训告。篇名〈无逸〉，旧题孔安国传释为戒成王毋贪逸豫；《史记·鲁周公世家》已引其文，可见西汉初年即已行世。今本文字见《十三经注疏》，属今文系统，与东晋所出古文二十五篇不同。学者大体信其为西周旧文而经后人写定润色，具体写定年代仍有讨论。</p>"},{"id":"shiji-thirty-six-commanderies","title":"三十六郡：郡县制的落地","source":"《史记》卷六《秦始皇本纪》","date":"2026-12-14","tags":["史记","秦代","郡县制"],"excerpt":"分天下以为三十六郡，郡置守、尉、监。","commentary":"<p>出自《史记》卷六《秦始皇本纪》，纪传体通史的本纪部分，西汉司马迁撰，记秦始皇二十六年（前二二一）统一天下后的措置。此十四字是秦推行郡县制最常被称引的条文，上句言分郡，下句言置官。今通行读本为中华书局点校本，一九五九年初版、二〇一四年修订，文字一仍其旧。</p>"},{"id":"hanshu-digou-shangnong","title":"籴贵伤民，籴贱伤农","source":"《汉书》卷二十四上《食货志上》","date":"2026-12-13","tags":["汉书","经济思想","李悝"],"excerpt":"籴甚贵伤民，甚贱伤农。民伤则离散，农伤则国贫。故甚贵与甚贱，其伤一也。善为国者，使民毋伤而农益劝。","commentary":"<p>见《汉书》卷二十四上《食货志上》。班固撰，东汉成书，是纪传体断代史中的经济制度专篇，其源出于《史记·平准书》而门类更广。此段系班固引述战国魏相李悝尽地力之教中的平籴之论，非汉人自道；《汉书》引前人之言常经删润，故文字与类书所引不尽相同。李悝与李克是否一人，学界有异说，《汉书·艺文志》法家有《李子》三十二篇，儒家又有《李克》七篇。</p>"},{"id":"hanyu-yuandao","title":"博爱之谓仁：韩愈的仁义道德之辨","source":"韩愈《原道》","date":"2026-12-12","tags":["韩愈","唐代","思想史"],"excerpt":"博爱之谓仁，行而宜之之谓义，由是而之焉之谓道，足乎己，无待于外之谓德。仁与义为定名，道与德为虚位。","commentary":"<p>韩愈〈原道〉，中唐古文运动的名篇，五原之首，收于《韩昌黎文集》。作年通行说法在贞元末至元和初，具体年代仍有讨论。文体是论说文，以原为名，即推究本原；其编纂意图在于辟佛老、标举儒家的道统谱系，为当时儒学应对佛教挑战提供理论支点。通行校注本为马其昶《韩昌黎文集校注》。</p>"},{"id":"liuzongyuan-bushe","title":"赋敛之毒有甚是蛇","source":"柳宗元《捕蛇者说》","date":"2026-12-11","tags":["柳宗元","唐代","赋役"],"excerpt":"孔子曰：苛政猛于虎。吾尝疑乎是，今以蒋氏观之，犹信。呜呼！孰知赋敛之毒有甚是蛇者乎？","commentary":"<p>柳宗元〈捕蛇者说〉，中唐古文家的讽刺杂说，收于《柳河东集》。通行说法作于柳宗元贬永州司马期间（八〇五至八一五），借永州蒋氏三世捕蛇抵赋事立论。文体介于记言与寓言之间，末段以说名篇，表明是议论而非实录。它与永州八记不同，八记以写景纪游为主，此篇专为议论而设。版本以《柳河东集》为主，文字歧异不大。</p>"},{"id":"fanzhongyan-yueyang","title":"先天下之忧而忧","source":"范仲淹《岳阳楼记》","date":"2026-12-10","tags":["范仲淹","宋代","士大夫"],"excerpt":"不以物喜，不以己悲。居庙堂之高则忧其民，处江湖之远则忧其君。是进亦忧，退亦忧。然则何时而乐耶？其必曰：先天下之忧而忧，后天下之乐而乐乎。","commentary":"<p>范仲淹〈岳阳楼记〉，北宋亭台记名篇，收于《范文正公集》。庆历六年（一〇四六）应滕子京之请而作，时范仲淹贬知邓州，滕子京谪守巴陵郡，重修岳阳楼在庆历五年，楼成而后请记。通行说法范氏未尝亲至岳阳楼，据来书与图经成文；此说仍有讨论，但文中写景多取概括，不似亲历。文体为记，实借楼之兴废言士大夫的出处之节。</p>"},{"id":"huangzongxi-school","title":"学校所以养士","source":"黄宗羲《明夷待访录·学校》","date":"2026-12-09","tags":["黄宗羲","明末清初","学校"],"excerpt":"学校，所以养士也。然古之圣王，其意不仅此也，必使治天下之具皆出于学校，而后设学校之意始备。","commentary":"<p>黄宗羲《明夷待访录·学校》，明末清初政治思想著作，通行说法成书于康熙初年（一六六三前后）。书名取《周易》明夷卦，寓待访之意，期待后王取法。全书有〈原君〉〈原臣〉〈学校〉诸篇，乾隆间曾列禁书，长期以抄本流传，清道光间始有刻本。今有中华书局等整理本。文体为政论，非史考。</p>"},{"id":"zhangxuecheng-shide","title":"能具史识者，必知史德","source":"章学诚《文史通义·史德》","date":"2026-12-08","tags":["章学诚","史学理论","史德"],"excerpt":"能具史识者，必知史德。德者何？谓著书者之心术也。","commentary":"<p>章学诚《文史通义·史德》，清代乾嘉时期史学理论著作，通行说法成书于乾隆末至嘉庆间，〈史德〉篇约作于嘉庆初。此书与唐刘知几《史通》并称，而重在义理；章氏另有《校雠通义》，其学以六经皆史为纲。章氏生前未大显，稿本经后人编次，有嘉业堂刻本及中华书局叶瑛校注本。文体为论学之文，非史著。</p>"},{"id":"liangqichao-new-history","title":"史界革命：梁启超的呼吁","source":"梁启超《新史学》","date":"2026-12-07","tags":["梁启超","近代史学","新史学"],"excerpt":"呜呼，史界革命不起，则吾国遂不可救。悠悠万事，惟此为大。","commentary":"<p>梁启超《新史学》，清光绪二十八年（一九〇二）连载于《新民丛报》的系列论文，后收入《饮冰室合集·文集》。是近代史界革命的宣言，作于梁氏流亡日本期间，其史观受进化论与文明史编纂影响。文体为报章论说，篇章之间不甚整齐，多有重复，属论纲而非成体系的理论著作。</p>"},{"id":"chenyinke-monument","title":"独立之精神，自由之思想","source":"陈寅恪《清华大学王观堂先生纪念碑铭》","date":"2026-12-06","tags":["陈寅恪","王国维","近代学术"],"excerpt":"先生之著述，或有时而不彰。先生之学说，或有时而可商。惟此独立之精神，自由之思想，历千万祀，与天壤而同久，共三光而永光。","commentary":"<p>陈寅恪《清华大学王观堂先生纪念碑铭》，民国十八年（一九二九）清华国学研究院为王国维立碑而作，王氏一九二七年六月自沉于颐和园昆明湖。碑铭刻石立于清华园，文收《金明馆丛稿二编》。文体为碑铭，四言韵语与散体序相间，属悼亡之文，其判断与陈氏〈王观堂先生挽词序〉的殉文化说相通。</p>"},{"id":"taizong-four-commanderies","title":"「高丽本四郡地耳」：贞观十五年的东征构想","source":"《资治通鉴》卷一九七，唐纪十三","date":"2026-12-25","tags":["唐丽战争","唐太宗","战略"],"excerpt":"高丽本四郡地耳，吾发卒数万攻辽东，彼必倾国救之。别遣舟师出东莱，自海道趋平壤，水陆合势，取之不难。但山东州县凋瘵未复，吾不欲劳之耳。","commentary":"<p>《资治通鉴》卷一九七，唐纪十三，北宋司马光主持编纂，元丰七年成书。此段系于贞观十五年，记太宗与侍臣议高丽事，属全书唐纪中以资治为旨的叙事之一。通鉴采唐实录、国史及《旧唐书》等，经删削排比，语言整饬，对话多为史臣剪裁后的书面语，并非现场记录。太宗开口便说「高丽本四郡地耳」，把辽东说成汉四郡旧壤，为后来的出兵埋下伏笔。</p>"},{"id":"qinzheng-hand-edict","title":"「取乱侮亡」：《亲征高丽手诏》的战争理由","source":"《全唐文》卷七，太宗","date":"2026-12-24","tags":["唐丽战争","诏令","合法性"],"excerpt":"行师用兵，古之常道，取乱侮亡，先哲所贵。高丽莫离支盖苏文，弑逆其主，酷害其臣，窃据边隅，肆其蜂虿。朕以君臣之义，情何可忍。若不诛翦遐秽，无以澄肃中华。","commentary":"<p>《全唐文》卷七收太宗文，清嘉庆年间董诰等奉敕编成，一千卷，汇辑唐五代单篇文章，所据为《旧唐书》《册府元龟》《文苑英华》等史书与总集。此篇《亲征高丽手诏》属诏令类，是贞观十八年决定亲征后昭告天下的文字，收入卷七太宗名下。全唐文只录正文，不加注释，诏书的颁布年月与对象需参校史传。</p>"},{"id":"chusuiliang-remonstrance","title":"褚遂良的谏阻：渡辽之后没有退路","source":"《贞观政要》卷九《征伐》","date":"2026-12-23","tags":["唐丽战争","朝议","谏诤"],"excerpt":"今闻陛下将伐高丽，意皆荧惑。然陛下神武英声，不比周隋之主，兵若渡辽，事须克捷，万一不获，无以威示远方，必更发怒，再动兵众，若至于此，安危难测。","commentary":"<p>《贞观政要》卷九《征伐》，唐吴兢撰，约成于开元年间，十卷四十篇，分类辑录太宗君臣言行，以供后世君主取法。此条记褚遂良谏阻亲征高丽，属征伐篇中反对用兵的一类。吴兢去贞观未远，所见有实录、国史为依据，但政要意在垂训，选材与文字都经过整理，谏词往往比原话更整齐。</p>"},{"id":"daeduilo-three-years","title":"大对卢：三年一代的权臣与闭宫自守的王","source":"《旧唐书》卷一九九上《东夷传·高丽》","date":"2026-12-22","tags":["唐丽战争","高句丽","政治制度"],"excerpt":"其官大者号大对卢，比一品，总知国事，三年一代，若称职者，不拘年限。交替之日，或不相祗服，皆勒兵相攻，胜者为之。其王但闭宫自守，不能制御。","commentary":"<p>《旧唐书》卷一九九上《东夷传·高丽》，后晋刘昫等撰，开运二年成书，多本唐代实录、国史旧稿，故材料来源偏早而编纂仓促。此段在高丽条叙述其官制与王权之处，属史臣对高句丽政治结构的概括，不是某一年的编年记录。全书体例为先叙地理风俗官职，再叙历代交涉，这段正处在制度概述的位置。</p>"},{"id":"liaodong-fire-arrows","title":"火弩焚楼：贞观十九年五月攻拔辽东城","source":"《旧唐书》卷三《太宗本纪下》","date":"2026-12-21","tags":["唐丽战争","辽东城","645"],"excerpt":"甲申，上亲率铁骑与李勣会围辽东城，因烈风发火弩，斯须城上屋及楼皆尽，麾战士令登，乃拔之。","commentary":"<p>《旧唐书》卷三《太宗本纪下》，后晋刘昫等撰。本纪按年月排比军国大事，此条系于贞观十九年五月，记太宗亲征高丽、攻拔辽东城。本纪文字简省，多据实录节录，一件事往往只剩时间、人物、结果，过程细节需到列传或《通鉴》中补足。此段正是这种写法：干支、亲征、合围、火攻、登城、城拔，一气而下。</p>"},{"id":"anshi-city-lord","title":"安市城主：莫离支攻不下的城","source":"《资治通鉴》卷一九八，唐纪十四","date":"2026-12-20","tags":["唐丽战争","安市城","645"],"excerpt":"吾闻安市城险而兵精，其城主材勇，莫离支之乱，城守不服，莫离支击之不能下，因而与之。","commentary":"<p>《资治通鉴》卷一九八，唐纪十四，记贞观十九年征高丽事。此段是太宗语，论安市城与其城主，出现在唐军围攻安市、久攻不下的前后。通鉴此卷多取《旧唐书》《新唐书》及实录，剪裁成编年，对话经过整理，语气虽生动，未必是原话。安市城的位置与城主姓名，后世异说颇多，此条本身只称城主，不著其名。</p>"},{"id":"anshi-lord-reward","title":"赐绢三百匹：安市城主的坚守与史源异文","source":"《贞观政要》卷九《征伐》","date":"2026-12-19","tags":["唐丽战争","安市城","史料比较"],"excerpt":"太宗将旋师，嘉安市城主坚守臣节，赐绢三百匹，以劝励事君者。","commentary":"<p>《贞观政要》卷九《征伐》，唐吴兢辑。此条记太宗班师前嘉奖安市城主，属征伐篇的收束之笔：一场未竟全功的东征，以表彰敌国守将作结。政要的编纂目的在于给君主提供可效法的故事，因此这类表彰忠节、以德服人的片段容易被收录，也容易被写得比原事更有教化意味。</p>"},{"id":"xuerengui-white-robe","title":"白衣先入：薛仁贵在安市城下的登场","source":"《旧唐书》卷八十三《薛仁贵传》","date":"2026-12-18","tags":["唐丽战争","薛仁贵","安市城"],"excerpt":"仁贵自恃骁勇，欲立奇功，乃异其服色，著白衣，握戟，腰鞬张弓，大呼先入，所向无前。贼尽披靡却走，大军乘之，贼乃大溃。","commentary":"<p>《旧唐书》卷八十三《薛仁贵传》。此传叙薛仁贵一生战功，开篇即贞观十九年安市城下白衣陷阵，是他由平民跻身将领的起点。旧唐书列传多本唐代实录、国史及家传行状，叙事重事功、喜细节，这一段写得有声有色，正见其笔法。传文先写自恃骁勇、欲立奇功，再写异服先入，因果分明。</p>"},{"id":"pyeongyang-fall-tongjian","title":"白幡出降：总章元年平壤的开门","source":"《资治通鉴》卷二〇一，唐纪十七","date":"2026-12-17","tags":["唐丽战争","平壤","668"],"excerpt":"高丽王藏遣泉男产帅首领九十八人，持白幡诣勣降，勣以礼接之。泉男建犹闭门拒守，频遣兵出战，皆败。","commentary":"<p>《资治通鉴》卷二〇一，唐纪十七，记总章元年唐灭高句丽事。此段系于平壤将陷之时，写高丽王藏遣泉男产出降、泉男建仍拒守。通鉴此卷依据唐实录、国史与《旧唐书·高丽传》，把围城、受降、城陷排成紧凑的编年，受降的礼节与降者的姿态都写得具体，带有胜利者史源的特点。</p>"},{"id":"baekgang-nihonshoki","title":"一百七十艘：白村江上的唐军船队","source":"《日本书纪》卷二十七，天智二年","date":"2026-12-16","tags":["唐丽战争","白江口","日本"],"excerpt":"大唐军将率战船一百七十艘，阵烈于白村江。","commentary":"<p>《日本书纪》卷二十七，天智二年条，日本奈良初期舍人亲王等奉敕撰，养老四年成书，汉文编年体，述神代至持统朝。此条记白村江之战中唐军船队列阵，是全书少数直接写到唐朝军队的段落。书纪以日本为本位，对白村江的败绩并不隐讳，但叙事用语、数字与胜负描写都带有本国立场。</p>"},{"id":"xintangshu-pyongyang-city","title":"平壤城的形制","source":"《新唐书》卷二二〇，东夷传·高丽","date":"2026-12-26","tags":["唐与高句丽","都城","史料"],"excerpt":"其君居平壤城，亦谓长安城，汉乐浪郡也，去京师五千余里而赢，随山屈缭为郛，南涯浿水，王筑宫其左。","commentary":"<p>《新唐书》卷二二〇东夷传高丽条，北宋欧阳修、宋祁等奉敕重修，嘉祐五年成书，晚于《旧唐书》百余年。东夷传的体例是先叙族属源流，次及山川城邑、官制风俗，此条正落在都城与道里的一段概述里，不是纪事文字，而是沿革地理的压缩叙述。</p>"},{"id":"xintangshu-goguryeo-origin","title":"高丽的族属与四至","source":"《新唐书》卷二二〇，东夷传·高丽","date":"2026-12-25","tags":["唐与高句丽","族属","史料"],"excerpt":"高丽，本扶余别种也，地东跨海距新罗，南跨海距百济，西北度辽水，与营州接。北靺鞨。","commentary":"<p>此条出自《新唐书》卷二二〇东夷传高丽条的开篇。高丽条在东夷传中篇幅最长，开篇先定族属，次列四至，再述风俗制度，这一段正是全传的纲。文字极简，四至只用四个短句交代，属于总叙而非行程记录。</p>"},{"id":"jiazhen-ando-road","title":"营州入安东道","source":"《新唐书》卷四十三下，地理志七下（引贾耽记入四夷之路）","date":"2026-12-24","tags":["唐与高句丽","交通","史料"],"excerpt":"营州东百八十里至燕郡城。又经汝罗守捉，渡辽水，至安东都护府五百里。","commentary":"<p>此条出《新唐书》卷四十三下地理志七下。地理志在叙河北道之后，附载贾耽所记「入四夷之路」七条，此为其一「营州入安东道」的首段。贾耽是德宗贞元朝的宰相，长于地理，撰《古今郡国县道四夷述》、绘《海内华夷图》，其书今佚，赖《新唐书》转录而存片段。体裁是行程记：以起点、里数、节点逐段串联，不作景物描写。</p>"},{"id":"weishu-goguryeo-territory","title":"高句丽的疆域四至","source":"《魏书》卷一百，高句丽传","date":"2026-12-23","tags":["唐与高句丽","地理","史料"],"excerpt":"其地东西二千里，南北一千余里。","commentary":"<p>《魏书》卷一百高句丽传，北齐魏收撰。魏收于天保二年奉诏修史，五年成书，记北魏及东魏与高句丽的往来。此条在传的地域概述处，全条只有一句，是正史四夷传中最简的疆域记载之一。</p>"},{"id":"zizhi-zhangliang-sea-route","title":"张亮舟师袭卑沙城","source":"《资治通鉴》卷一九七，唐纪十三，贞观十九年","date":"2026-12-22","tags":["唐与高句丽","水军","史料"],"excerpt":"张亮帅舟师自东莱渡海，袭卑沙城，其城四面悬绝，惟西门可上。","commentary":"<p>《资治通鉴》卷一九七唐纪十三，贞观十九年条。司马光主撰，元丰七年成书，编年体，取材以正史、实录为主，删繁就简。此条记张亮率舟师自东莱渡海袭卑沙城。张亮时任平壤道行军大总管，所部为舟师，与李勣统率的陆路主力并行，构成贞观十九年之役的两条轴线。</p>"},{"id":"zizhi-pyeongyang-fall","title":"信诚开城：平壤陷落的一刻","source":"《资治通鉴》卷二〇一，唐纪十七，总章元年","date":"2026-12-21","tags":["唐与高句丽","亡国","史料"],"excerpt":"男建以军事委僧信诚，信诚密遣人诣勣，请为内应。后五日，信诚开门，勣纵兵登城鼓噪。","commentary":"<p>《资治通鉴》卷二〇一唐纪十七，总章元年条。此条记李勣围平壤、泉男建委军事于僧信诚、信诚开门内应的一刻，是高句丽亡国过程的收束。编年体把这件事系于具体月日之下，叙事因此有了可数的节奏。</p>"},{"id":"tangdazhaoling-qinzheng","title":"《亲征高丽诏》的开篇","source":"《唐大诏令集》卷七，亲征·亲征高丽诏","date":"2026-12-20","tags":["唐与高句丽","诏令","史料"],"excerpt":"观乎天道，鼓雷霆以肃万物；求诸人事，陈金革以威四方。","commentary":"<p>《唐大诏令集》卷七「亲征」类所收《亲征高丽诏》的开篇。此书为北宋宋敏求所编，辑唐一代诏令，分门别类，熙宁年间成书；所收诏令多不注出处，间有删节。贞观十八年末，太宗决意亲征辽东，此诏即为此而发；这一条只是诏书起首的一组骈句，不是完整诏文。</p>"},{"id":"cefuyuangui-weiting-transport","title":"韦挺督运军粮","source":"《册府元龟》，将帅部·旷败（韦挺条）","date":"2026-12-19","tags":["唐与高句丽","后勤","史料"],"excerpt":"太宗将伐辽东，令挺先运军粮，河北诸州取挺节度。","commentary":"<p>《册府元龟》将帅部「旷败」门韦挺条。此书为北宋王钦若、杨亿等奉敕编，大中祥符六年成，一千卷，是分类抄录史传的类书；「旷败」门专收将帅失职败事之例，此条即因韦挺督运军粮失职而入选。</p>"},{"id":"jiutangshu-baekje-buyeo","title":"扶余隆与熊津都督府","source":"《旧唐书》卷一九九上，东夷传·百济","date":"2026-12-18","tags":["唐与高句丽","百济","史料"],"excerpt":"乃授扶余隆熊津都督，遣还本国，共新罗和亲，以招辑其余众。","commentary":"<p>《旧唐书》卷一九九上东夷传百济条。后晋刘昫等撰，开运二年成书，是现存最早的系统记载唐代史事的正史，东夷传多本唐实录、国史旧文。此条记百济亡后，唐授扶余隆为熊津都督、遣还本国之事，属羁縻安置的一段。</p>"},{"id":"zizhi-baekgang","title":"白江口：四战皆捷","source":"《资治通鉴》卷二〇一，唐纪十七，龙朔三年","date":"2026-12-17","tags":["唐与高句丽","白江口","史料"],"excerpt":"遇倭兵于白江口，四战皆捷，焚其舟四百艘，烟炎灼天，海水皆赤。","commentary":"<p>《资治通鉴》卷二〇一唐纪十七，龙朔三年条。此条记刘仁轨等率唐军与倭兵战于白江口，是七世纪东亚国际战争的关键一役。此役的焦点是百济故地的归属：唐罗联军水陆并进，围攻百济余众所据的周留城，倭军渡海来援，双方在白江口相遇。白江口通行说法在今韩国锦江入海口一带。</p>"},{"id":"jiutangshu-official-ranks","title":"高丽的官阶与州县","source":"《旧唐书》卷一九九上，东夷传·高丽","date":"2026-12-16","tags":["唐与高句丽","制度","史料"],"excerpt":"对卢以下，官总十二级。外置州县六十余城，大城置傉萨一人，比都督。","commentary":"<p>《旧唐书》卷一九九上东夷传高丽条，记高句丽官阶与地方城制的部分。旧唐书东夷传于族属、山川之后例叙官制风俗，此条正在制度叙述的段落里，文字简括，以唐制为参照。</p>"},{"id":"gaozong-wall-goguryeo","title":"千里长城：高句丽的防线","source":"《旧唐书》卷一九九上，东夷传·高丽","date":"2027-01-05","tags":["高句丽","长城","防御"],"excerpt":"建武惧伐其国，乃筑长城，东北自扶余城，西南至海，千有余里。","commentary":"<p>《旧唐书》卷一九九上〈东夷传·高丽〉，后晋刘昫等监修，材料多本唐前期的实录与国史。此条记荣留王建武在位时筑长城事，属纪传体正史的四夷传，叙述以唐朝为中心，对藩属的举动多从畏威、惧伐的角度解释，动机描写带有史臣的揣度成分；传文不系年月，只能借上下文与《三国史记》推定大致时段。</p>"},{"id":"jubisan-heads","title":"驻跸山：斩首二万馀级","source":"《资治通鉴》卷一九八，唐纪十四","date":"2027-01-04","tags":["唐丽战争","驻跸山","兵力"],"excerpt":"斩首二万馀级。","commentary":"<p>《资治通鉴》卷一九八唐纪十四，记贞观十九年（645）征高丽事。司马光等以唐实录、国史为底本，按年月日编排，战功数字多沿当时露布与捷报，未经独立核算；驻跸山一战是太宗亲征中最大的一次野战胜利，山在今辽宁海城一带，通行说法以其得名于太宗驻马观战。</p>"},{"id":"surrender-36800","title":"三万六千八百人：驻跸山降卒","source":"《资治通鉴》卷一九八，唐纪十四","date":"2027-01-03","tags":["唐丽战争","降卒","高延寿"],"excerpt":"延寿、惠真帅其众三万六千八百人请降，入军门，膝行而前，拜伏请命。","commentary":"<p>《资治通鉴》卷一九八唐纪十四，贞观十九年六月驻跸山战后条。此段记高延寿、高惠真率部请降的场面，二人分任高句丽北部、南部耨萨，是高句丽地方军政的首长；材料源于唐方捷报与实录，属编年体正史中的受降叙事，仪节描写多于对降众处置的交代。</p>"},{"id":"sudingfang-pyeongyang","title":"苏定方围平壤","source":"《资治通鉴》卷二百，唐纪十六","date":"2027-01-02","tags":["唐丽战争","苏定方","平壤"],"excerpt":"秋，七月，甲戌，苏定方破高丽于浿江，屡战皆捷，遂围平壤城。","commentary":"<p>《资治通鉴》卷二百唐纪十六，记龙朔元年（661）苏定方东征事。苏定方于显庆五年（660）灭百济，次年转兵高丽，通行说法以之为平壤道行军大总管，率舟师由海道北上；通鉴此段据唐实录与国史删润而成，按日系事，对战役过程只作概括。唐此役分道并进，陆路与海路未能会师于城下。</p>"},{"id":"baekje-five-prefectures","title":"百济故地五都督府","source":"《新唐书》卷二二〇，东夷传·百济","date":"2027-01-01","tags":["百济","羁縻","都督府"],"excerpt":"析置熊津、马韩、东明、金涟、德安五都督府。","commentary":"<p>《新唐书》卷二二〇〈东夷传·百济〉，宋欧阳修、宋祁等撰，采摭唐修国史与诸家记载，叙事较《旧唐书》整饬。此条记显庆五年（660）灭百济后唐在其故地设置军府，属正史四夷传中的建置记录，重点在制度名号而非治理实况；同卷于五府之外另有留守军镇与羁縻州县的零散记载。</p>"},{"id":"baekje-king-surrenders","title":"义慈王出降","source":"《资治通鉴》卷二百，唐纪十六","date":"2026-12-31","tags":["百济","义慈王","灭亡"],"excerpt":"于是义慈、隆及诸城主皆降。","commentary":"<p>《资治通鉴》卷二百唐纪十六，显庆五年（660）七月条。此段系于唐罗联军攻破百济都城之后，属编年体正史的灭国叙事，材料本于唐方露布与实录，对百济君臣的出降只作结果性交代，过程与细节从略；百济末年的王室继承纠纷，需从他卷与《三国史记》补足。</p>"},{"id":"pyeongyang-snow-withdraw","title":"大雪解围：苏定方撤兵","source":"《资治通鉴》卷二百，唐纪十六","date":"2026-12-30","tags":["唐丽战争","平壤","气候"],"excerpt":"苏定方围平壤久不下，会大雪，解围而还。","commentary":"<p>《资治通鉴》卷二百唐纪十六，记龙朔二年（662）苏定方自平壤撤军。此条极简，只以一句交代围城的结果，属编年体史书对战役收尾的常规处理；材料出自唐实录，撤军原因被压缩为单一的气候因素，与之相关的百济故地局势则别见他卷。通鉴于围城期间尚记唐军与百济故地叛军的牵制，此条则专就平壤一城立论。</p>"},{"id":"baiyan-city-surrender","title":"白岩城：受降与「赎此一城」","source":"《资治通鉴》卷一九八，唐纪十四","date":"2026-12-29","tags":["唐丽战争","白岩城","受降"],"excerpt":"城主孙代音潜遣腹心请降……得城中男女万馀口。","commentary":"<p>《资治通鉴》卷一九八唐纪十四，贞观十九年六月白岩城受降事。此段节引，前后省略了城主先请降、既而悔约、唐军攻城与太宗许降的曲折，属编年体正史中兼载君臣对话的叙事；白岩城通行说法在今辽宁灯塔一带，燕州城古城或即其故址。白岩城之降发生在唐军围攻安市之前，是太宗亲征前期的一次示范性受降。</p>"},{"id":"tongding-crossing-liao","title":"自通定济辽水","source":"《资治通鉴》卷一九七，唐纪十三","date":"2026-12-28","tags":["唐丽战争","渡辽","李世勣"],"excerpt":"李世勣军发柳城，多张形势，若出怀远镇者，而潜师北趣甬道，出高丽不意。夏，四月，戊戌朔，世勣自通定济辽水，至玄菟。","commentary":"<p>《资治通鉴》卷一九七唐纪十三，贞观十九年四月唐军渡辽事。此段记李世勣一军的行军路线，属编年体正史中的战役开篇，材料本于唐实录；通鉴按日系事，对地理与计谋的交代较两《唐书》为详，柳城、怀远、通定诸地的今地则尚待考订。</p>"},{"id":"haotaiwang-bei-yongle","title":"好太王碑：「永乐五年，岁在乙未」","source":"《好太王碑》碑文","date":"2026-12-27","tags":["高句丽","好太王碑","碑刻"],"excerpt":"永乐五年，岁在乙未，王以碑丽不贡，又躬率往讨。","commentary":"<p>《好太王碑》为高句丽长寿王于414年为其父好太王所立，1877年发现于今吉林集安太王乡，碑身四面环刻汉字，高逾六米，是现存最长的高句丽金石文献。碑文以颂德为主，属王权自我陈述的纪念性刻石，不是官方档案；碑文以好太王功业与守墓烟户为两大内容，此条属功业部分。</p>"},{"id":"tang-shipbuilding-400","title":"造船四百艘：征辽的军粮海运","source":"《资治通鉴》贞观十八年秋七月条","date":"2027-01-27","tags":["唐丽战争","后勤","造船"],"excerpt":"秋七月辛卯，敕将作大匠阎立德等诣洪、饶、江三州，造船四百艘以载军粮。","commentary":"<p>《资治通鉴》卷一九七贞观十八年七月条，记唐太宗决意亲征高丽之前的后勤筹备。此书由司马光主持、刘恕等人分修，采唐代实录与国史而成，属编年体二手编纂，不是原始档案；条首「秋七月辛卯」用干支纪日，说明史源仍保留了日历式的时间标记。整条只有一句话，却正处在备战链条的关键位置上。</p>"},{"id":"zhangjian-liaoshui-vanguard","title":"张俭渡辽：营州胡兵为前锋","source":"《资治通鉴》贞观十八年条","date":"2027-01-26","tags":["唐丽战争","营州","前锋"],"excerpt":"营州都督张俭将胡兵为前锋，进渡辽水，趋建安城，破高丽兵，斩首数千级。","commentary":"<p>此条出自《资治通鉴》贞观十八年，记唐军首次渡过辽水的试探性进攻，是亲征全面展开之前的序战。编年体本条把营州、辽水、建安城串为一线，史源当为唐实录与《旧唐书》相关纪传的整理，属二手叙述；「斩首数千级」这类战报数字往往沿袭军中奏报，未经史官核减。</p>"},{"id":"liaodong-fire-attack","title":"火攻克辽东：冲竿与西南楼","source":"《资治通鉴》贞观十九年条","date":"2027-01-25","tags":["唐丽战争","攻城","辽东城"],"excerpt":"甲申，南风急，上遣锐卒登冲竿之末，爇其西南楼，火延烧城中，因麾将士登城，高丽力战不能敌，遂克之。","commentary":"<p>此条见《资治通鉴》贞观十九年五月，记唐太宗亲征时攻克辽东城的关键一刻。辽东城即今辽阳，为高句丽西境重镇，此役是整场战争中唐军首次攻下的大型城池。材料属编年体叙述，风向、器械、登城次序都写得具体，可能采自随军记录或国史旧文，但仍经史官整饰。</p>"},{"id":"taiping-yulan-jutang","title":"局堂读书：高句丽的民间教育","source":"《太平御览》卷七八三引《唐书》","date":"2027-01-24","tags":["高句丽","教育","风俗"],"excerpt":"俗爱书籍，至于衡门厮养之家，各于街衢造大屋，谓之局堂，子弟未婚之前，昼夜于此读书、习射。","commentary":"<p>此条为《太平御览》卷七八三四夷部所引《唐书》之文，记高句丽风俗。类书编纂于宋初，所引《唐书》与今本《旧唐书》《新唐书》文字略有出入，属转引而非原书；其所标「唐书」究竟指哪一部，学界仍有讨论。即便原书，其史源也多是唐使臣、将士的见闻与唐廷掌握的边情，带有旁观者的概括口吻。</p>"},{"id":"taizong-prefer-you","title":"朕不喜得辽东，喜得卿也","source":"《旧唐书》卷八十三《薛仁贵传》","date":"2027-01-23","tags":["唐丽战争","薛仁贵","人物"],"excerpt":"及军还，太宗谓曰：朕旧将并老，不堪受阃外之寄，每欲抽擢骁雄，莫如卿者。朕不喜得辽东，喜得卿也。","commentary":"<p>此条出《旧唐书》卷八十三《薛仁贵传》，记贞观十九年征辽班师后太宗对薛仁贵的勉励。纪传体的这类君臣对话，多本于实录、国史中的行状与传记，经史臣剪裁而成，属经过整理的记言，不能视为现场速记；但所透露的用人态度，与太宗朝其他记载可以互证。</p>"},{"id":"liaoze-road-bridge","title":"辽泽泥淖：布土作桥二百里","source":"《资治通鉴》贞观十九年五月条","date":"2027-01-22","tags":["唐丽战争","后勤","辽泽"],"excerpt":"庚午，车驾至辽泽，泥淖二百馀里，人马不可通，将作大匠阎立德布土作桥，军不留行。","commentary":"<p>此条见《资治通鉴》贞观十九年五月，记太宗亲征途中穿越辽泽的工程处置。辽泽指辽河下游以西的沼泽地带，是自幽州东出辽东的必经之险。材料属编年体行军记录，所记仅工程与行程，未及用时与人力，史源当为实录一系的随军记载。</p>"},{"id":"daozong-four-thousand","title":"四千骑逆击四万：江夏王道宗的判断","source":"《资治通鉴》贞观十九年条","date":"2027-01-21","tags":["唐丽战争","骑兵","战术"],"excerpt":"道宗曰：贼恃众，有轻我心，远来疲顿，击之必败。且吾属为前军，当清道以待乘舆，乃更以贼遗君父乎！","commentary":"<p>此条见《资治通鉴》贞观十九年，记高丽以步骑四万救辽东、江夏王李道宗率四千骑迎击之前的军中争论。李道宗为宗室名将，此役与张俭渡辽、攻克辽东城同属亲征初期的一系列战斗。材料为编年体记言，对话当经史臣删润，但其中的战术推理合乎当时情境。</p>"},{"id":"bojang-offer-two-girls","title":"献二姝而还：高丽谢罪与太宗的拒绝","source":"《唐书·高丽传》（《古今图书集成·边裔典》引）","date":"2027-01-20","tags":["唐丽战争","外交","朝贡"],"excerpt":"明年春，藏遣使者上方物，且谢罪，献二姝口，帝敕还之，谓使者曰：色者人所重，然愍其去亲戚以伤乃心，我不取也。","commentary":"<p>此条为《古今图书集成·边裔典》所引《唐书·高丽传》之文，记贞观二十年高丽遣使谢罪并献女。类书成于清初，其引文所据《唐书》与今本两《唐书》高丽传文字有异，属转引性质；所记「藏」即宝藏王，时为高丽在位之君。事件背景是贞观十九年唐军大举进攻之后双方关系的修复：唐军围攻安市不下、因天寒班师，二十年春高丽遣使，时间上与班师相接。</p>"},{"id":"xue-wanche-yalu-crossing","title":"薛万彻度鸭渌：泊灼城下的弃邑","source":"《新唐书·高丽传》","date":"2027-01-19","tags":["唐丽战争","海路","鸭渌"],"excerpt":"万彻度鸭渌，次泊灼城，拒四十里而舍，虏惧，皆弃邑居去。","commentary":"<p>此条出《新唐书·高丽传》，记贞观二十二年薛万彻青丘道行军自海路入、渡鸭渌水进逼泊灼城。青丘道是唐廷为经略高句丽所设的行军道之一，取海路登陆，与陆路亲征相区别，也与辽东道诸军并出，属牵制袭扰性质。材料为纪传体叙述，欧阳修等纂修时多本唐国史旧文，行文简省，一句之内压缩了渡河、扎营、敌军反应三事。</p>"},{"id":"goguryeo-households-moved","title":"移高丽户二万八千二百","source":"《资治通鉴》卷二〇一总章二年条（参《旧唐书》卷五《高宗纪》）","date":"2027-01-18","tags":["唐丽战争","遗民","户籍"],"excerpt":"移高丽户二万八千二百，入内地莱、营二州，般次发遣，量配于江、淮以南及山南、并州、凉州以西诸州空闲处安置。","commentary":"<p>此条见《资治通鉴》卷二〇一总章二年条，记唐廷对高句丽遗民的强制迁徙，可与《旧唐书》卷五《高宗纪》对读。总章元年高句丽灭亡，次年即有大规模移民之举。材料属编年体，数字与州名较完整，史源当为唐廷诏敕与户部统计，但经史官撮述，已非原始簿籍。</p>"},{"id":"sui-shu-goguryeo-origin","title":"孤竹故地：隋人对高句丽的认识","source":"《隋书》卷六十七，裴矩传","date":"2027-01-28","tags":["高句丽","隋代","史料"],"excerpt":"高丽之地，本孤竹国也。周代以之封于箕子，汉世分为三郡，晋氏亦统辽东。今乃不臣，别为外域，故先帝疾焉，欲征之久矣。","commentary":"<p>此条出《隋书》卷六十七裴矩传，是纪传体正史里的一篇奏状，而不是东夷传的叙述文字。其时炀帝北巡，启民可汗帐下先有高丽使者通款，启民不敢隐瞒，引使者见帝，裴矩因上此状，劝帝胁令高丽王入朝。所以它是一份现场进言，带着明确的政策目的，并非对高句丽来历的冷静考订；状末还把文帝时杨谅出师无功归咎于用人不当，反衬炀帝正宜乘此有为。</p>"},{"id":"jiu-tangshu-goguryeo-customs","title":"性凶急，习战斗：正史中的高句丽人","source":"《后汉书》卷八十五，东夷列传·高句骊","date":"2027-01-29","tags":["高句丽","唐代","风俗"],"excerpt":"其人性凶急，有气力，习战斗，好寇钞，沃沮、东濊皆属焉。","commentary":"<p>此条出《后汉书》卷八十五东夷列传高句骊条，作者范晔，南朝宋人，纪传体正史；所据多为东汉一代的官府档案与旧闻，成书已在高句丽屡犯辽东之后。它常被误挂在《旧唐书·高丽传》名下，实则旧书并无此语，同一句的祖本可上溯到《三国志·魏书·东夷传》，那里只作「其人性凶急，喜寇钞」。</p>"},{"id":"tongjian-gaesomun-coup","title":"弑君专国：盖苏文政变的记载","source":"《资治通鉴》卷一九六，唐纪十二","date":"2027-01-30","tags":["高句丽","政变","史料"],"excerpt":"盖苏文凶暴多不法，其王及大臣议诛之。盖苏文密知之，悉集部兵若校阅者，并盛陈酒馔于城南，召诸大臣共临视，勒兵尽杀之，死者百余人。","commentary":"<p>此条见《资治通鉴》卷一九六唐纪十二，贞观十六年十一月丁巳条，是编年体史书中的一段叙事；司马光等据唐实录、国史与《旧唐书·高丽传》剪裁而成，叙事的起点是营州都督张俭的奏报。须说明的是，此事的年份系于卷一九六，不在卷一九七。</p>"},{"id":"tongjian-taizong-casus-belli","title":"违我诏命：唐太宗出兵的理由","source":"《资治通鉴》卷一九七，唐纪十三","date":"2027-01-31","tags":["唐丽战争","诏令","史料"],"excerpt":"盖苏文弑其君，贼其大臣，残虐其民，今又违我诏命，侵暴邻国，不可以不讨。","commentary":"<p>此条见《资治通鉴》卷一九七唐纪十三，贞观十八年二月乙巳朔条。司农丞相里玄奖出使归来，具言高丽不肯罢兵、拒绝诏命的情状，太宗遂对侍臣说了这番话；下文紧接着是褚遂良的谏阻与李世勣以薛延陀旧事相激。它是编年体史书里的一段君臣议政记录。</p>"},{"id":"xintangshu-gaesomun-origin","title":"泉氏之名：《新唐书》对盖苏文的记述","source":"《新唐书》卷二二〇，东夷传·高丽","date":"2027-02-01","tags":["高句丽","权臣","史料"],"excerpt":"有盖苏文者，或号盖金，姓泉氏，自云生水中以惑众。性忍暴。父为东部大人、大对庐，死。盖苏文当嗣，国人恶之，不得立。","commentary":"<p>此条出《新唐书》卷二二〇东夷传高丽条，欧阳修、宋祁等撰，北宋官修纪传体正史。它与《旧唐书》同记一人而文字有别：旧书作「苏文姓钱氏」，新书改作「泉氏」，又添出「或号盖金」「自云生水中以惑众」等带有志怪色彩的细节，可见宋人重修时别有所本，也更有意塑造人物。</p>"},{"id":"jiu-tangshu-liuji-liaodong","title":"李世勣拔辽东：唐军攻城的记录","source":"《旧唐书》卷六十七，李勣传","date":"2027-02-02","tags":["唐丽战争","李勣","史料"],"excerpt":"十八年，太宗将亲征高丽，授勣辽东道行军大总管，攻破盖牟、辽东、白崖等数城，又从太宗摧殄驻跸阵，以功封一子为郡公。","commentary":"<p>此条出《旧唐书》卷六十七李勣传，后晋刘昫等撰，纪传体正史。李勣本姓徐，名世勣，归唐后赐姓李，高宗时避太宗讳而单名勣。本传叙其一生战功，征辽只占数行，与高丽传中铺陈抛车撞车、飞石破楼的攻城主段相比，这里近乎电报式的记录。</p>"},{"id":"xintangshu-liuji-pyeongyang","title":"会围平壤：《新唐书》李勣传的一笔","source":"《新唐书》卷九十三，李勣传","date":"2027-02-03","tags":["唐丽战争","李勣","史料"],"excerpt":"高丽莫离支男生为其弟所逐，遣子乞师。诏勣为辽东道行军大总管，率兵二万讨之。破其国，执高藏、男建等，裂其地州县之。","commentary":"<p>此条出《新唐书》卷九十三李勣传，北宋欧阳修、宋祁等撰。总章元年高丽内乱，莫离支男生被其弟男建、男产所逐，遣子献诚入唐乞师，唐以李勣为辽东道行军大总管往讨；事见本传者仅此数句，是纪传体正史列传叙事的典型笔法。本传叙其晚年，先记废立武后时「此陛下家事」之对，再记征辽灭国，笔法上把两件大事并置。</p>"},{"id":"tongjian-pyeongyang-surrender-ritual","title":"持白幡诣勣降：平壤受降的记载","source":"《资治通鉴》卷二〇一，唐纪十七","date":"2027-02-04","tags":["唐丽战争","受降","史料"],"excerpt":"高丽王藏遣泉男产帅首领九十八人，持白幡诣勣降，勣以礼接之","commentary":"<p>《资治通鉴》卷二〇一，唐纪十七，总章元年九月条。司马光主撰，刘恕、范祖禹等分修，北宋元丰七年成书，编年体通史。此条上承李勣克大行城、契苾何力进抵平壤城下，下接城破执王，是唐灭高句丽的关键一环；唐纪取材于实录、国史与两《唐书》，经司马光删削系日，文字简净而程序清楚。</p>"},{"id":"xintangshu-baekje-fall","title":"百济亡国：《新唐书》的叙述","source":"《新唐书》卷二二〇，东夷传·百济","date":"2027-02-05","tags":["百济","亡国","史料"],"excerpt":"定方令士超堞立帜，泰开门降，定方执义慈、隆及小王孝演、酋长五十八人送京师，平其国五部、三十七郡、二百城，户七十六万","commentary":"<p>《新唐书》卷二二〇，东夷传·百济。宋祁、欧阳修等奉敕撰，嘉祐五年成书，纪传体正史；列传部分多出宋祁之手。此传叙显庆五年苏定方自城山济海、破熊津口、逼真都城，至义慈被执，文字较《旧唐书》简练，间采家传与杂史，年月不如《通鉴》细密。《旧唐书》此段较繁，宋人删并纪事，细节因之流失。</p>"},{"id":"tongjian-silla-troops","title":"新罗出兵：同盟的另一半","source":"《资治通鉴》卷二〇〇，唐纪十六","date":"2027-02-06","tags":["唐丽战争","新罗","史料"],"excerpt":"诏新罗出兵，新罗王春秋奉诏，遣其将金钦将兵救仁轨等，至古泗，福信邀击，败之","commentary":"<p>《资治通鉴》卷二〇〇，唐纪十六，龙朔元年条。司马光主撰，北宋元丰七年成书。此年唐留刘仁愿守百济府城，百济遗众据周留城围之，唐起刘仁轨检校带方州刺史，并诏新罗发兵救援；通鉴把诏书、行军与战报编入同一链条，可见同盟的实际运作方式。</p>"},{"id":"samguk-sagi-yeongyang-war","title":"婴阳王的应对：《三国史记》的记载","source":"《三国史记》卷二十，高句丽本纪·婴阳王","date":"2027-02-07","tags":["高句丽","隋唐","史料"],"excerpt":"文德见述军士有饥色，故欲疲之，每战辄走。述一日之中，七战皆捷，既恃骤胜，又逼群议，于是遂进东济萨水","commentary":"<p>《三国史记》卷二十，高句丽本纪·婴阳王。高丽金富轼奉敕撰，1145年成书，纪传体三国史；婴阳王纪主要取《隋书》《资治通鉴》及本国古记，记隋大业八年征辽之役。全篇为汉文，以王纪为纲，按年系事，战况多借隋方记载改写。《隋书·炀帝纪》系此事于大业八年，可与本卷对读。</p>"},{"id":"samguk-sagi-bojang-end","title":"表辞诡诞：宝藏王时期的唐丽往来","source":"《三国史记》卷二十一，高句丽本纪·宝藏王","date":"2027-02-08","tags":["高句丽","亡国","史料"],"excerpt":"虽遣使奉表，其言率皆诡诞，又待唐使者倨傲，常窥伺边隙。屡敕令不攻新罗，而侵凌不止","commentary":"<p>《三国史记》卷二十一，高句丽本纪·宝藏王上。金富轼奉敕撰，1145年成书。此卷起宝藏王元年，止五年，记泉盖苏文弑荣留王、立宝藏王，及唐太宗亲征辽东；真正的平壤陷落、王被迁在卷二十二《宝藏王下》，本条出自卷末对泉氏骄恣的总叙。本卷篇幅大半为唐太宗诏令与战事，王本人的事迹反而稀见。</p>"},{"id":"nihonshoki-661-expedition","title":"齐明纪的出兵准备：《日本书纪》","source":"《日本书纪》卷二十六，齐明天皇纪","date":"2027-02-09","tags":["日本","白江口","史料"],"excerpt":"是岁，欲为百济，将伐新罗。乃敕骏河国造船。已讫，挽至续麻郊之时，其船夜中无故舻舳相反。众知终败","commentary":"<p>《日本书纪》卷二十六，齐明天皇纪。舍人亲王等奉敕撰，养老四年成书，汉文体编年史。此卷记齐明六年百济覆亡后倭国造船备军，七年正月御船西征，七月天皇崩于朝仓宫；造船条置于六年「是岁」之下，正是援百济政策的动员阶段。此卷不载白江口战事，只写到出师与天皇之丧。</p>"},{"id":"beishi-goguryeo-customs","title":"《北史》里的高句丽风俗","source":"《北史》卷九十四，高丽传","date":"2027-02-10","tags":["高句丽","风俗","史料"],"excerpt":"有婚嫁，取男女相悦即为之。男家送猪酒而已，无财聘之礼；或有受财者，人共耻之，以为卖婢","commentary":"<p>《北史》卷九十四，高丽传。李延寿撰，显庆四年成书，纪传体通史；四夷传多袭《魏书》《隋书》旧文，高丽传先叙疆域、居处、饮食，次及婚丧、祭天与官制。传文是中原史官对东邻风俗的分类记述，不是田野调查。所记与《隋书·高丽传》文字相近，可视为同一源流的转抄。</p>"},{"id":"zhoushu-goguryeo-tribute","title":"《周书》所记高句丽的朝贡与物产","source":"《周书》卷四十九，异域传·高丽","date":"2027-02-11","tags":["高句丽","朝贡","史料"],"excerpt":"大统十二年，遣使献其方物。成死，子汤立。建德六年，汤又遣使来贡。高祖拜汤为上开府仪同大将军、辽东郡开国公、辽东王。","commentary":"<p>《周书》五十卷，唐初令狐德棻等奉敕修撰，记西魏、北周两朝史事，贞观年间成书。卷四十九为《异域传》，高丽条与百济、蛮、獠等并列，属正史四夷传的体例：先叙族源、疆域、官制、风俗，末记朝贡与封拜。所摘数句在传末，是传中按年编排的一段聘贡记录，前后相连，并非从两处缀合。须注意《周书》无志，此传材料多取自西魏、北周旧史与使者行记，编者对高句丽并无实地见闻。</p>"},{"id":"tongdian-goguryeo-institutions","title":"《通典》对高句丽制度的整理","source":"《通典》卷一八六，边防二·高句丽","date":"2027-02-12","tags":["高句丽","制度","史料"],"excerpt":"次皂衣头大兄，东夷相传所谓皂衣先人者也。以前五官掌机密，谋政事，征发兵马，选授官爵。","commentary":"<p>《通典》二百卷，杜佑撰，历三十年增修，至贞元十七年（801）奏进，是现存最早的政书体通史。边防典列四夷，卷一八六为高句丽条。杜佑处理四夷材料与正史四夷传不同：按类排比，先疆域，次官制，次风俗，次历代交涉，凡制度名目必求整齐，故有「其国建官有九等」的总括。本条所摘在官制段中，紧接九等官阶的罗列，属归纳之笔，而非某次出使的实录。</p>"},{"id":"tanghuiyao-gaozong-ando","title":"《唐会要》里的安东都护府沿革","source":"《唐会要》卷七十三，安东都护府","date":"2027-02-13","tags":["唐丽战争","安东都护府","史料"],"excerpt":"至仪凤二年二月二日，移安东都护府于新城安置，仍令特进左卫大将军高侃充使镇府。至圣历元年六月三十日，改安东都护府为安东都督府，以右武卫大将军高仇须为都督。","commentary":"<p>《唐会要》一百卷，宋王溥撰，成于建隆年间，是现存最早的会要体史书，按事类辑录唐代制度沿革，材料多出唐人所修实录、国史与诏敕。卷七十三列都护府，安东都护府一条自总章元年平高丽起，按年月排比置府、内迁、改名诸事，体例近乎编年的大事记。四库本此条无句读，本文标点为引者所加；同条另记「平襄城」，通行点校本多作「平壤城」，一字之差，正是版本校勘的常见情形。</p>"},{"id":"cefuyuangui-taizong-edict","title":"《册府元龟》所录征辽诏敕","source":"《册府元龟》卷一一七，帝王部·亲征","date":"2027-02-14","tags":["唐丽战争","诏令","史料"],"excerpt":"朕然后经涂白狼之右，亲巡玄菟之城，执鼖鼓而戒六军，载太常而麾八阵。使流汤者鱼烂，握炭者冰消，诛渠魁于恶稔，吊黎庶于陨角。","commentary":"<p>《册府元龟》一千卷，宋王钦若、杨亿等奉敕编，大中祥符六年（1013）成书，分类辑录历代君臣事迹，专取正史、实录与诏令，不加论断。卷一一七属帝王部亲征门，录贞观十八年十二月甲寅讨高丽诏，即《唐大诏令集》卷一百三十所题〈讨高丽诏〉，亦即后世所称《亲征高丽手诏》。诏文甚长，先述盖苏文弑君、侵新罗之罪，次命李勣、张亮等分道，末段才是太宗自述亲征行程，本文所摘即此末段。</p>"},{"id":"jiu-tangshu-weiting-transport","title":"韦挺督运：《旧唐书》的记载","source":"《旧唐书》卷七十七，韦挺传","date":"2027-02-15","tags":["唐丽战争","后勤","史料"],"excerpt":"挺至幽州，令燕州司马王安德巡渠通塞。先出幽州库物，市木造船，运米而进。自桑乾河下至卢思台，去幽州八百里，逢安德还曰：「自此之外，漕渠壅塞。」","commentary":"<p>《旧唐书》二百卷，后晋刘昫等撰，开运二年（945）成书，是现存最早的系统记录唐朝史事的纪传体正史。卷七十七为韦挺等传，本传叙其历官、督运辽东军粮及失期坐罪的始末。所摘一段是传中的叙事主体，用至、令、先出、市、运、下至、逢一串动词推进，是典型的纪传体笔法，与诏令、奏疏的文体不同。</p>"},{"id":"zhenguanzhengyao-taizong-reflect","title":"《贞观政要》记东征后的反思","source":"《贞观政要》卷九，征伐","date":"2027-02-16","tags":["唐丽战争","贞观政要","史料"],"excerpt":"夫兵甲者，国家凶器也。土地虽广，好战则人凋；中国虽安，忘战则人殆。","commentary":"<p>《贞观政要》十卷，唐吴兢撰，约成于开元前期，分类纂辑太宗君臣问对与诏议，以供后世取法。卷九《征伐》共十三章，按年编次，自武德九年渭水之盟至贞观二十二年止，末章即太宗《帝范》论兵之语。所摘四句出《帝范》，吴兢把它系于征伐篇末，用意是以太宗本人的晚年定论收束全篇，使前面十余章的谏诤与战绩有一个归宿。</p>"}];

const biographies = [{"id":"zhang-zhu","title":"张燾：一个“怕死”的使臣","period":"南宋·高宗朝","tags":["宋代","外交","小人物"],"summary":"绍兴八年金使议和，南宋须称臣纳贡，满朝噤声之际张燾自请出使，却在金营威逼下退缩失命，归国后遭朝野唾骂，贬谪而死。他的矛盾不在胆小，而在请缨的勇气与临事的崩溃并存；史书对他着墨极少，其形象多由后人转述拼接而成。"},{"id":"li-zhiyi","title":"李之仪：被历史遗忘的文学家","period":"北宋·苏门文人","tags":["宋代","文学","人物"],"summary":"李之仪是苏轼门生，党争中因代撰遗表获罪，编管当涂，长期居于姑溪。其《姑溪词》清丽中含刚健，《卜算子》以长江水写相思，传唱千年；论词主张长短句自有体性，为李清照词论之先声。正史记载寥寥，生平多赖文集与方志保存。"},{"id":"john-brill","title":"约翰·布里尔：一个被遗忘的文艺复兴人","period":"16世纪·英格兰","tags":["西方史","文艺复兴","人物"],"summary":"约翰·布里尔是英国宗教改革时期的多产作家与古物学者，写剧、编目、搜求中世纪抄本，两度流亡，曾任爱尔兰主教。他编纂的不列颠作家名录与抢救的旧稿，为后世保留了大量中世纪文学线索；称他为文艺复兴人并不准确，他更像宗教改革的产儿。"},{"id":"chen-yinke","title":"陈寅恪：‘独立之精神，自由之思想’","period":"近代·中国","tags":["近代","史学家","学术精神","隋唐","考据"],"summary":"义宁陈氏之后，游学欧美而不取学位，通晓梵文、巴利文等十余种语文。以《隋唐制度渊源略论稿》追索制度三源，以《唐代政治史述论稿》提出关陇集团与关中本位政策，强调种族与文化之别；晚年失明膑足，仍以诗证史，口授成《柳如是别传》。"},{"id":"gu-jiegang","title":"顾颉刚：疑古派与古史辨运动","period":"近代·中国","tags":["近代","史学理论","疑古派"],"summary":"顾颉刚一九二三年提出层累地造成的中国古史说，将经典还原为历史文献，引发古史辨运动。他研究民间故事，创办禹贡学会，晚年投入二十四史点校。疑古之勇与整理之慎在他身上并存，学界对其评价至今仍有分歧，而他提出的问题意识则影响深远。"},{"id":"lu-simian","title":"吕思勉：被低估的通史大家","period":"近代·中国","tags":["近代","通史","史学大家","断代史"],"summary":"终身执教光华大学，以《白话本国史》《吕著中国通史》与四部断代史独自贯通上古至五代，又积数十年札记成《吕思勉读史札记》。治史重实证，留心户口、赋役与制度细节，材料密集而论断简省，被视为通博一派的代表。"},{"id":"su-dingfang","title":"苏定方：从西陲名将到跨海灭国","period":"唐·高宗朝","tags":["唐代","名将","战争"],"summary":"苏定方西灭西突厥、东灭百济，是高宗朝扩张最得力的执行者之一。曳咥河与泗沘城的胜利改变了西域与半岛格局，而灭国之后的留守、羁縻与军纪问题，也让他背上纵兵与争功的弹劾。正史详其战功而略其争议，小说又把他写成反派，两面合看才算完整。"},{"id":"yeon-gaesomun","title":"渊盖苏文：高句丽末年的权臣与操盘手","period":"高句丽·宝藏王时代","tags":["高句丽","权臣","隋唐"],"summary":"渊盖苏文弑荣留王、立宝藏王，以莫离支执掌高句丽二十余年。他联百济、拒新罗、表面事唐，把半岛争端推成与唐朝的长期对抗；依托山城防线挡住太宗亲征，却也耗尽了国力。死后诸子内讧，唐军乘隙东进，高句丽随之灭亡。"},{"id":"enin-monk","title":"圆仁：漂洋过海入唐的求法僧","period":"唐·武宗朝","tags":["唐代","佛教","日记"],"summary":"圆仁以请益僧身份入唐，本求天台经典，却因风与许可之阻滞留不归，前后近十年，辗转扬州、五台山与长安。他亲历会昌灭佛，逐日记录寺院废毁、僧尼还俗与沿途物价里程，写成《入唐求法巡礼行记》。这部日记既是佛教劫难的证词，也是唐代社会的一份取样。"},{"id":"eulji-mundeok","title":"乙支文德：萨水岸边的守国者","period":"隋·高句丽","tags":["高句丽","隋唐","军事"],"summary":"隋大业八年，乙支文德以七战七退诱隋军深入，于萨水半渡而击，三十万之众溃于一旦。他的名字、官职与那首劝退诗，几乎全部来自十二世纪的《三国史记》，中国正史只记战事而不记其人。后世层层塑造的忠臣形象，与萨水岸边那位调度军队的将领，隔着很远的距离。"},{"id":"li-ji","title":"李勣：从瓦岗到平壤的唐军统帅","period":"唐·太宗高宗朝","tags":["唐代","军事","高句丽"],"summary":"李勣本姓徐，出瓦岗而归唐，赐姓李氏，历高祖、太宗、高宗三朝。贞观十九年统陆军征辽，总章元年为诸军之主攻灭高句丽。用兵稳健，善抚士卒；晚年以“此陛下家事”一语应对废立之议，遂成史评争议的焦点。军功与分寸，是他一生的两面。"},{"id":"xue-rengui","title":"薛仁贵：白衣先登的唐将","period":"唐·太宗高宗朝","tags":["唐代","军事","高句丽"],"summary":"薛仁贵绛州龙门人，贞观十九年安市城下白衣先登，为太宗赏识。此后征西突厥、击铁勒，有三箭定天山之说，然记载已多夸饰；乾封年间征高句丽，破金山、扶余城。咸亨元年大非川之败，是他军旅中最重的挫折。演义里的白袍完人，与史传中的寒门勇将并不相同。"},{"id":"liu-rengui","title":"刘仁轨：白江口与百济故地的治理者","period":"唐·高宗朝","tags":["唐代","军事","百济"],"summary":"刘仁轨汴州尉氏人，以文吏起家，因海运失船被免，白衣从军，遂留镇百济故地。龙朔三年白江口一战，以少船焚倭军四百艘，百济复国之望断绝。战后屯田修城、抚辑遗民，后入朝为相。由文转武、再由武转相，他是唐前期文武不隔的一个显例。"},{"id":"bojang","title":"宝藏王：高句丽的末代君主","period":"高句丽·末王","tags":["高句丽","亡国","唐代"],"summary":"宝藏王高藏于642年由泉盖苏文拥立，在位二十六年而军政皆出权臣之手。668年平壤陷落被俘，唐授以官职并安置内地，具体官称与居地史载不一。他几乎不见自主决策的记录，其象征意义不在行事，而在王位只剩名分这一事实本身。"},{"id":"chen-yuan","title":"陈垣：史源学与宗教史之间","period":"近代·中国","tags":["史学家","元史","校勘学"],"summary":"广东新会人，自学出身的史学家与教育家，长期主持辅仁大学。治元史与宗教史，以《元也里可温教考》《元西域人华化考》著称；又治校勘学与避讳学，著《校勘学释例》《史讳举例》，抗战中借《通鉴胡注表微》寄寓故国之思。"},{"id":"huang-renyu","title":"黄仁宇：大历史与数目字管理","period":"现代·美国","tags":["史学家","明史","大历史"],"summary":"湖南长沙人，抗战时在驻印军服役，后赴美获密歇根大学博士学位，以明代财政为研究起点。《万历十五年》以1587年为切口写制度与人物，提出「大历史观」与「数目字管理」，另著《中国大历史》《资本主义与二十一世纪》。"},{"id":"fernand-braudel","title":"布罗代尔：长时段与地中海","period":"20世纪·法国","tags":["史学家","年鉴学派","地中海"],"summary":"法国年鉴学派第二代领袖，主持高等研究实践学院与《年鉴》杂志，重视地理、气候与日常生活。《地中海与菲利普二世时代的地中海世界》以地理、局势、事件三层时间立论，提出「长时段」；晚年著《十五至十八世纪的物质文明、经济和资本主义》。"},{"id":"eric-hobsbawm","title":"霍布斯鲍姆：年代四部曲的作者","period":"20世纪·英国","tags":["史学家","马克思主义史学","现代史"],"summary":"生于埃及亚历山大，长于维也纳与柏林，1933年赴英，长期任教于伯贝克学院。英国共产党历史学家小组成员，以马克思主义方法治劳工史与民族主义，著「年代四部曲」与《原始的叛乱》，并与兰格合编《传统的发明》。"},{"id":"yan-gengwang","title":"严耕望：扎实的治史者","period":"现代·中国","tags":["史学家","中古史","历史地理"],"summary":"安徽桐城人，武汉大学出身，受业于钱穆，后任中央研究院史语所研究员、香港中文大学与新亚研究所教授。以《唐代交通图考》《唐仆尚丞郎表》《中国地方行政制度史》复原唐代交通路线与行政地理，另著《治史三书》谈治学方法与师承。"},{"id":"sima-qian","title":"司马迁：忍辱著书的人","period":"西汉·武帝朝","tags":["史学家","史记","西汉"],"summary":"司马迁承父遗命而作《史记》，因李陵之祸受宫刑，忍辱成书，开纪传体通史之例。本文述其壮游、史官生涯与发愤著述之志，说明五体与十表八书的结构，并论实录精神与传闻异辞并存的两面，指出读《史记》须留意其史料层次与文学笔法。"},{"id":"ban-gu","title":"班固：断代为史的立法者","period":"东汉·明帝朝","tags":["史学家","汉书","东汉"],"summary":"班固续父班彪之书，私撰国史下狱，得明帝赏识而入兰台，历二十余年成《汉书》，开断代为史之例。本文述其生平、十志的贡献与白虎观撰集，并比较《汉书》与《史记》的批判尺度，说明断代体例的得失，交代八表与《天文志》由班昭、马续续成。"},{"id":"liu-zhiji","title":"刘知几：史通与史家的自我审视","period":"唐·中宗朝","tags":["史学家","史通","唐代"],"summary":"刘知几久任史馆，因不满监修之弊而私撰《史通》，为中国第一部系统的史学批评专著。本文述其生平、六家二体之说与才学识三长论，兼及《疑古》《惑经》《直书》《曲笔》的锋芒，以及《史通》在后世的接受，指出其价值在于把史家本身当作审视对象。"},{"id":"zhao-yi","title":"赵翼：札记里的史识","period":"清·乾嘉","tags":["史学家","廿二史札记","清代"],"summary":"赵翼由翰林、军机处出任边郡知府，中年归里著述，成《廿二史札记》三十六卷。本文述其生平与札记写法，论布衣将相之局、气运与势等命题在乾嘉学术中的位置，也指出其结论粗疏、引证偶误的一面，说明札记体史学的长处与限度。"},{"id":"wang-fuzhi","title":"王夫之：明清之际的史论家","period":"明清之际","tags":["史学家","读通鉴论","明清之际"],"summary":"王夫之明亡后起兵抗清，失败后隐居石船山著述，成《读通鉴论》《宋论》。本文述其生平与气学背景，论以势与理考察制度变迁的方法、对郡县制与君主专制的判断，以及夷夏之辨等局限，并述船山学在清末的重新发现与史论气学的关联。"},{"id":"marc-bloch","title":"马克·布洛赫：为历史学辩护","period":"20世纪·法国","tags":["史学家","年鉴学派","法国"],"summary":"布洛赫与费弗尔创办《年鉴》，以《国王神迹》《封建社会》把史料扩展到仪式、地名与账册，主张史料批判、比较方法与长时段；二战中参加抵抗运动，1944 年被盖世太保枪杀，遗稿《为历史学辩护》成为年鉴学派的方法宣言。"},{"id":"karl-polanyi","title":"卡尔·波兰尼：嵌入性与大转型","period":"20世纪·欧美","tags":["经济史","波兰尼","方法论"],"summary":"波兰尼在《大转型》中提出嵌入与脱嵌、虚构商品与双向运动，认为 19 世纪市场社会的扩张必然引发社会保护的反向运动；其实质主义立场影响了经济人类学与经济史，斯宾汉姆兰一节则因叙述过整而受批评，其问题意识在今天的市场争论中仍然有效。"},{"id":"herbert-butterfield","title":"巴特菲尔德：辉格史观的批判者","period":"20世纪·英国","tags":["史学家","史学理论","英国"],"summary":"巴特菲尔德以《辉格党式的历史阐释》批判站在现在回望过去、把历史写成进步故事的写法，主张先还原时代处境的技术史；此说与剑桥学派的语境主义相通，他也因拒绝道德判断而被批评为保守，这一告诫至今仍是史学方法的常识。"},{"id":"carlo-ginzburg","title":"金兹堡：微观史学的匠人","period":"20世纪·意大利","tags":["史学家","微观史学","意大利"],"summary":"金兹堡以《夜间的战斗》《奶酪与蛆虫》细读宗教裁判所的审讯记录，提出证据范式，把磨坊主梅诺基奥的宇宙论读成民间文化与权力相遇的个案；微观史学缩小尺度是为显出结构，而非猎奇，其细读史料的方式影响了此后的个案研究。"},{"id":"tan-qixiang","title":"谭其骧：为历史地理立坐标","period":"现代·中国","tags":["史学家","历史地理","中国"],"summary":"谭其骧以政区沿革考证为根基，主持编绘《中国历史地图集》，以清代鼎盛疆域界定历史上的中国、各朝只画实际控制区；其关于东汉以后黄河长期安流的研究，把河道变迁与中游土地利用相连，主编工作也使历史地理成为可协作的公共工程。"},{"id":"luo-zhenyu","title":"罗振玉：甲骨、敦煌与内阁大库","period":"近代·中国","tags":["甲骨学","敦煌","近代学术"],"summary":"罗振玉（1866—1940）是近代最重要的古物收藏与刊布者之一：为《铁云藏龟》作序，考释甲骨，抢救敦煌写本与内阁大库档案，确立殷墟地望；同时追随溥仪出任伪满官职，学术功业与政治污点并存，二者难以互相抵消。"},{"id":"wang-guowei","title":"王国维：二重证据法与《观堂集林》","period":"近代·中国","tags":["甲骨学","二重证据法","近代学术"],"summary":"王国维（1877—1927）以卜辞证《殷本纪》，提出二重证据法，确立地下材料与纸上材料互证的范式；《观堂集林》遍及殷周制度、文字音韵与西北史地。1927年自沉昆明湖，其人其学成为近代学术与时代紧张关系的象征，后世解释纷纭。"},{"id":"dong-zuobin","title":"董作宾：五期断代与《殷历谱》","period":"近代·中国","tags":["甲骨学","断代","殷墟"],"summary":"董作宾（1895—1963）主持殷墟第一次发掘，以十项标准建立甲骨五期断代，又以《殷历谱》与周祭研究重建商代年代与礼制；其框架沿用至今，具体结论则屡经修正，仍是今日甲骨断代工作的起点，也奠定了商代年代学的规模。"},{"id":"li-ji-archaeologist","title":"李济：中国考古学的奠基者","period":"近代·中国","tags":["考古学","殷墟","近代学术"],"summary":"李济（1896—1979）主持西阴村与殷墟发掘，把地层记录、陶器类型与体质测量引入中国考古，奠定田野规范与人才培养制度；其类型学与体质人类学的具体结论多已过时，方法取向仍被继承，影响至今，是近代学术转型中承前启后的人物。"},{"id":"fu-sinian","title":"傅斯年：史语所与史料学派","period":"近代·中国","tags":["史学史","史语所","近代学术"],"summary":"傅斯年（1896—1950）创办中央研究院历史语言研究所，以「上穷碧落下黄泉，动手动脚找东西」为口号扩张史料，提出《夷夏东西说》；其贡献主要在学术组织与制度，而非专著，身后评价亦多集中于组织之功，为现代史学提供了可复制的组织样本。"},{"id":"guo-moruo","title":"郭沫若：卜辞、金文与古代社会","period":"现代·中国","tags":["甲骨学","金文","马克思主义史学"],"summary":"郭沫若（1892—1978），诗人、古文字学家，1949年后长期主持中国科学院。他以《卜辞通纂》《两周金文辞大系》系统整理甲骨与金文，又以《中国古代社会研究》首倡以唯物史观解释商周社会。其考释常有推进过快之处，晚年政治表态亦使学术与政治角色难以分开评说。"},{"id":"chen-mengjia","title":"陈梦家：甲骨断代与西周铜器","period":"现代·中国","tags":["甲骨学","青铜器","现代学术"],"summary":"陈梦家（1911—1966），早年以新月派诗人知名，后专治甲骨与西周铜器，任职中国科学院考古研究所。《殷虚卜辞综述》集甲骨学之大成，《西周铜器断代》以器形、纹饰、铭文与共存关系建立框架。1957年被划为右派，1966年去世，身后著作重印，评价渐趋肯定。"},{"id":"chang-kuang-chih","title":"张光直：商文明与萨满说","period":"现代·美国","tags":["考古学","商代","海外汉学"],"summary":"张光直（1931—2001），生于北京，哈佛大学博士，任教于耶鲁与哈佛。《古代中国考古学》《商文明》长期是英语学界的标准参考；他倡聚落考古与区域调查，并以萨满式宇宙观解释商代权力的来源。其宏观假说影响深远，也因证据间接而屡遭批评。"},{"id":"hsu-cho-yun","title":"许倬云：古代中国与《西周史》","period":"现代·美国","tags":["古代史","西周","海外汉学"],"summary":"许倬云（1930— ），生于江苏无锡，芝加哥大学博士，任教于匹兹堡大学。《中国古代社会史论》以《左传》人物统计社会流动，《西周史》综合金文与文献重建封建宗法，《汉代农业》讨论农业集约化。其社会科学取向与长时段视野影响广泛，晚年公众写作亦引发不同评价。"},{"id":"ho-ping-ti","title":"何炳棣：明清社会流动与人口","period":"现代·美国","tags":["明清史","社会流动","海外汉学"],"summary":"何炳棣（1917—2012），生于天津，哥伦比亚大学博士，任教于芝加哥大学。《明清社会史论》以登科录统计进士家庭出身，《明初以降人口及其相关问题》辨析册籍人口数据，揭示十八世纪的人口增长。其量化取向开拓了领域，样本代表性也一直是争论焦点。"},{"id":"gwanggaeto","title":"广开土王：好太王碑上的征服与记忆","period":"4世纪末—5世纪初·高句丽","tags":["高句丽","好太王碑","4-5世纪"],"summary":"以好太王碑为中心，梳理广开土王的即位、对百济与新罗的用兵及与倭的冲突，说明碑文如何把军事胜利写成王权记忆、把守墓人烟户写成制度；末段讨论碑的发现、释读分歧，并指出碑文既是战功清单也是政治宣传，其自夸需与半岛局势对读。"},{"id":"jangsu","title":"长寿王：平壤时代的开端","period":"5世纪·高句丽","tags":["高句丽","平壤","5世纪"],"summary":"从集安的将军坟写起，讲长寿王迁都平壤的背景与南进百济的顶点，兼及他对北魏与南齐的双轨外交，以及好太王碑、王陵与佛寺如何共同塑造国家形象；末段指出迁都造成的南北失衡与百济复仇，盛世的边界同时是负担，这些问题在他身后逐一显现。"},{"id":"yeongnyu","title":"荣留王：修长城与最后的和平","period":"7世纪·高句丽","tags":["高句丽","7世纪","唐丽关系"],"summary":"从千里长城的修筑切入，写荣留王对唐的缓和、道教与佛寺的引入，以及泉氏权臣政治如何使和平路线难以为继，终至642年他被弑杀；他的缓和缺乏内部支撑，和平的失败不在个人德行而在权力结构，泉氏与王室的关系是合作也是寄生。"},{"id":"quan-namsaeng","title":"泉男生：从莫离支之子到唐将","period":"7世纪·高句丽/唐","tags":["高句丽","唐","泉氏"],"summary":"从1922年洛阳出土的泉男生墓志切入，讲他嗣位后被兄弟排挤、据国内城归唐、为唐军向导的经过，并借墓志与正史的对读，讨论降将的双重身份与史料的宣传性质；降将的处境介于两套叙事之间，他能选择的余地其实很小，两种文本各有剪裁。"},{"id":"quan-namgeon","title":"泉男建：平壤城破时的守者","period":"7世纪·高句丽","tags":["高句丽","平壤","668"],"summary":"以668年平壤被围开篇，写泉男建在盖苏文死后的夺权、对唐作战与城破后的顽抗，以及流配黔州的结局；末段讨论史书凶悖评语背后的胜利者书写，守城者的形象最终被胜利者反复涂抹，他的顽抗没有改变结局，只留下一个标签。"},{"id":"go-yeonsu","title":"高延寿：安市城下的十五万援军","period":"7世纪·高句丽","tags":["高句丽","安市城","645"],"summary":"645年，高延寿率高句丽与靺鞨兵十五万救援安市，在驻跸山被唐军分兵合击而溃，与高惠真率三万六千八百人降唐。太宗释俘授官，任其为鸿胪卿。此役暴露了援军号令不一、地形不熟的弱点，也标志高句丽野战主力的丧失。"},{"id":"zhang-liang","title":"张亮：平壤道行军大总管","period":"唐·太宗朝","tags":["唐","水军","645"],"summary":"张亮出身寒微，因玄武门之变前守口如瓶而得太宗信任，官至刑部尚书，图形凌烟阁。645年他以平壤道行军大总管率舟师四万余人自东莱渡海，攻拔卑沙城，却未能与陆军协同直取平壤。战后因养假子五百人被劾谋反，斩于市，籍没其家。"},{"id":"li-daozong","title":"李道宗：辽东战场上的宗室将领","period":"唐·太宗朝","tags":["唐","宗室","辽东"],"summary":"李道宗是唐高祖堂侄，封江夏王，早年从李世民征战，贞观年间镇灵州御突厥，又送文成公主入吐蕃。645年东征为辽东道副总管，率四千骑击破高句丽援军，督筑土山攻安市而伤足。永徽四年被长孙无忌借房遗爱案牵连，流象州，病卒于道，年五十四。"},{"id":"qibi-hel","title":"契苾何力：蕃将的忠诚与伤痕","period":"唐·太宗高宗朝","tags":["唐","蕃将","契苾"],"summary":"契苾何力出身铁勒契苾部，贞观六年随母率部归唐，授左领军将军。被薛延陀执去时割耳不屈，太宗以和亲赎归。征辽中为槊所伤，太宗亲为敷药，他拒杀刺客高突勃。总章元年率部先抵平壤，参与灭高句丽，是唐初蕃将中的代表人物，卒后陪葬昭陵。"},{"id":"lai-huer","title":"来护儿：隋代水军的最后一战","period":"隋·炀帝朝","tags":["隋","水军","东征"],"summary":"来护儿是隋代最著名的水军将领，江都人，生年不详，早年即以舟师见长。大业八年率楼船自东莱渡海攻平壤，入城后纵兵俘掠，中伏大溃。三次东征高句丽，他均统水军出海，终未能与陆军协同破城。大业十四年江都之变中遇害。"},{"id":"mingnim-dapbu","title":"明临答夫","period":"高句丽·次大王至新大王","tags":["高句丽","国相","2世纪"],"summary":"高句丽次大王至新大王时期的国相，活动于二世纪中后期。据《三国史记》通行说法，一七二年出任国相，同年迎击汉辽东太守耿临的进攻，兼掌军政。其事迹仅见于这一部书，属单一史源，人物形象经后世贤相叙事修饰，细节多不可校验。"},{"id":"eulpaso","title":"乙巴素","period":"高句丽·故国川王","tags":["高句丽","国相","2世纪"],"summary":"高句丽故国川王时期的国相，出身地方、门第不高，经人举荐被破格任用。任内整肃吏治、减轻徭役，并以赈贷救济灾民，试图借官僚制约束部族贵族。其贤相形象经《三国史记》加工，所载言论不可尽信，其事迹亦仅见于《三国史记》一源。"},{"id":"buyeo-pung","title":"扶余丰","period":"百济·义慈王之后","tags":["百济","复国","7世纪"],"summary":"百济义慈王之子，国破前长期质于倭国。六六一年在鬼室福信拥立下归国即位，据周留城复国。因缺乏本土根基而受制于权臣，六六三年杀福信，同年白江口大败，逃奔高句丽，此后下落记载不一，难以论定。其政权始终依赖倭国与权臣，根基薄弱。"},{"id":"gwishil-bokshin","title":"鬼室福信","period":"百济·复国运动","tags":["百济","复国","7世纪"],"summary":"百济亡后复国运动的核心组织者，与僧道琛据周留城起兵，迎立扶余丰，一度围困唐军泗沘守军。后因专权与君臣猜忌为扶余丰所杀。复国军随之失去统一指挥，三年而败。其起落显示这场运动缺乏稳固的政治基础，其败亦由内部分裂所致。"},{"id":"kim-yushin","title":"金庾信","period":"新罗·真德王至文武王","tags":["新罗","统一","7世纪"],"summary":"新罗真德王至文武王时期的统帅，与金春秋一政一军相互配合，主持对百济、高句丽的战事，参与六六〇年灭百济与六六八年灭高句丽。本传神异化明显，其忠勇形象经后世层累塑造，不宜视为当时实录，其功业与唐罗关系的演变密不可分。"},{"id":"cheng-mingzhen","title":"程名振","period":"唐·高祖至太宗朝","tags":["唐","将领","征辽"],"summary":"唐初将领，洺州平恩人，隋末依附窦建德，归唐后历任边职。贞观年间参与对高句丽的袭扰与征辽，六四五年以平壤道行军副帅攻沙卑城、围辽东城，是唐丽战争中典型的前线执行者。其子程务挺亦为高宗朝名将，父子两代跨越唐初扩张的高峰。"},{"id":"pang-xiaotai","title":"庞孝泰","period":"唐·太宗至高宗朝","tags":["唐","将领","征辽"],"summary":"唐初白州地方首领出身的将领，随军远征高句丽，龙朔二年战死于蛇水，旧籍与方志称其父子同殁，甚至有十三子之说。正史记载简略，地方记忆则以其父子死事为忠烈；生卒与官职诸书不一，战功与败因均难详考，两种叙述的落差正折射出边将在帝国扩张中的位置。"},{"id":"gao-kan","title":"高侃","period":"唐·太宗至高宗朝","tags":["唐","将领","征辽"],"summary":"唐高宗朝的边将，显庆年间屡与高句丽交战，总章元年参与灭其国，战后出任安东都护府都护一类职务。事迹零散，战功不显，其价值更多体现在长期驻防与羁縻治理，而非某一场决定性战役；生平细节多不可考，其名亦少为后世所道。"},{"id":"xue-wanche","title":"薛万彻","period":"唐·高祖至太宗朝","tags":["唐","将领","征辽"],"summary":"唐初关中将门之后，玄武门之变中为太子李建成力战，后为太宗收用，从征吐谷浑、高句丽，以勇决著称。永徽四年牵连房遗爱谋反案被诛。临刑不屈的传闻与官方定案并存，此案是否为冤狱至今仍有讨论，其一生显示功臣在皇权更迭中的脆弱处境。"},{"id":"ashina-sheer","title":"阿史那社尔","period":"唐·太宗朝","tags":["唐","蕃将","突厥"],"summary":"东突厥处罗可汗之子，汗国崩解后西走据地，贞观九年率众归唐，尚衡阳长公主。从征高句丽，又以昆丘道大总管平定龟兹。其任用显示唐廷对蕃将的倚重，也显示其权力与受信任程度的明确边界，请殉昭陵一事尤见其处境之微妙。"},{"id":"jin-yufu","title":"金毓黻","period":"近代·中国","tags":["史学史","东北史","20世纪"],"summary":"近代东北史研究的奠基者之一，辽宁辽阳人。九一八后入关，在民族危机中撰《东北通史》，辑印《辽海丛书》，著《渤海国志长编》。其学以文献考订见长，也受救亡语境与时代材料的双重限制，《东北通史》仅成上编，隋唐以后的部分未及写出。"},{"id":"qian-mu","title":"钱穆","period":"现代·中国","tags":["史学史","国学"," twentieth-century"],"summary":"由小学教员自学而入北大、清华，抗战中写成《国史大纲》，卷首以「温情与敬意」重提本国历史的价值；1949年后赴香港创办新亚书院，晚年居台北素书楼讲学不辍。其通史以士风串通制度，识见宏阔，而回护传统之处亦招后人批评。"},{"id":"lei-haizong","title":"雷海宗","period":"现代·中国","tags":["史学史","世界史","文化形态"],"summary":"清华出身、芝加哥大学博士，以《中国文化与中国的兵》从兵制切入文化盛衰，并借文化形态论提出以淝水之战为界的中国史两周说。抗战中声名显著，1957年被划为右派后讲学中断，著作久不流通，其文化形态的宏观假说至今仍受质疑。"},{"id":"zhang-yinlin","title":"张荫麟","period":"现代·中国","tags":["史学史","通史","宋史"],"summary":"清华出身、以宋史研究见长的通史家，《中国史纲》仅成先秦至东汉一册，却以史识与文笔著称。他讲究笔削取舍，主张通史须写出一个时代的精神；抗战中辗转浙江大学，三十七岁病逝，遗稿散失，留下一个至今仍被讨论的通史范本。"},{"id":"meng-wentong","title":"蒙文通","period":"现代·中国","tags":["史学史","经学","地方史"],"summary":"蒙文通（1894—1968），四川盐亭人，执教于成都大学、四川大学。由今文经学入手，著《经学抉原》梳理汉代经学家法与地域，又以《古史甄微》提出海岱、河洛、江汉三系说，晚年治百越与巴蜀史。其学重师承与文献，推论大胆，系统写定者少。"},{"id":"fu-yiling","title":"傅衣凌","period":"现代·中国","tags":["史学史","社会经济史","明清"],"summary":"傅衣凌（1911—1988），福建福州人，执教于厦门大学。以民间契约、账簿与族谱研究明清社会经济，著《明清时代商人及商业资本》《明代江南市民经济试探》等，关注商帮资本流向与江南市镇。其法开契约文书研究先河，然抽样有限，受资本主义萌芽框架约束。"},{"id":"liang-fangzhong","title":"梁方仲","period":"现代·中国","tags":["史学史","明代","赋役"],"summary":"梁方仲（1908—1970），广东番禺人，任职中央研究院，后执教岭南大学、中山大学。以经济学与统计学训练治明代赋役，著《一条鞭法》《明代赋役制度》，并编《中国历代户口、田地、田赋统计》。其学重口径与出处，奠定明代财政研究基础。"},{"id":"jian-bo-zan","title":"翦伯赞","period":"现代·中国","tags":["史学史","马克思主义史学","通史"],"summary":"翦伯赞（1898—1968），维吾尔族，湖南桃源人，北京大学历史系主任。马克思主义史学代表，著《历史哲学教程》《秦汉史》，主编《中国史纲要》，使唯物史观通史进入课堂。其框架受时代限制，晚年于文革中受迫害自尽。"},{"id":"wu-han","title":"吴晗","period":"现代·中国","tags":["史学史","明史","社会史"],"summary":"吴晗（1909—1969），浙江义乌人，清华出身，后任北京市副市长。以考证治明史，著《朱元璋传》《明史简述》《读史札记》，辑《朝鲜李朝实录中的中国史料》。其通俗写作影响广泛，而《海瑞罢官》引发大批判，学术与政治的纠葛贯穿一生。"},{"id":"dae-musin","title":"大武艺：高句丽的扩张与对唐冲突","period":"高句丽·9世纪","tags":["高句丽","君主"],"summary":"渤海武王，719年袭位，受唐册封而自用「仁安」年号。在位期间北攻黑水靺鞨，逼弟大门艺奔唐，732年遣水军袭登州，又与日本通使以牵制唐与新罗。以战促和的两面政策为渤海换来生存空间，其族属与继承关系至今仍有争议。"},{"id":"kim-chunchu","title":"金春秋：新罗的对唐同盟者","period":"新罗·7世纪","tags":["新罗","外交"],"summary":"新罗武烈王，真智王之孙、真平王外孙，因王统争议而亟需外力。642年大耶城之失促其两度入唐请兵，648年与唐结盟并改行唐制。660年联唐灭百济，在位七年推进集权。同盟的收益是统一，代价是罗唐战争，后世视其为三国统一的起点。"},{"id":"munmu-of-silla","title":"文武王：统一之后的新罗","period":"新罗·7世纪","tags":["新罗","君主"],"summary":"新罗文武王，金春秋长子。660年灭百济、663年白江口之战、668年助攻灭高句丽，其后转身对抗唐，676年迫使安东都护府内迁，统一大同江以南。火葬散骨东海之事仅见《三国史记》，海中陵之说尚待考古印证。"},{"id":"wei-cuncheng","title":"魏存成：高句丽考古的整理者","period":"现代·中国","tags":["考古学","高句丽"],"summary":"中国考古学家，长期任教于吉林大学，专治高句丽与渤海考古。以集安城址、积石墓与封土石室墓的类型学排比建立年代框架，并以瓦当断代。《高句丽考古》一类综论把散见材料整理成体系，但受限于境内材料与少量纪年依据。"},{"id":"geng-tiehua","title":"耿铁华：好太王碑与高句丽史研究","period":"现代·中国","tags":["高句丽","碑刻"],"summary":"中国高句丽史与碑刻研究者，毕生用力于好太王碑的校释与集释。他以早期拓本互校，考订碑文纪年与征伐路线，与日、韩学者在改刻说、倭之指涉等问题上分歧明显。其集释提供了共同文本底本，但碑文数字与残字复原仍须审慎。"},{"id":"ikeuchi-hiroshi","title":"池内宏：日本东洋史学的满洲朝鲜研究","period":"近代·日本","tags":["东洋史学","满洲朝鲜"],"summary":"池内宏是日本东洋史学的代表人物，长期参与满鲜历史地理调查，以《满鲜史研究》系统考订高句丽、渤海的史地与交通。其考证精细，方法克制，却与殖民调查体制深度绑定；评价他既要用其具体结论，也须交代调查的时代位置。"},{"id":"lee-byung-do","title":"李丙焘：韩国国史编纂与高句丽研究","period":"现代·韩国","tags":["韩国史学","高句丽"],"summary":"李丙焘是韩国古代史研究的奠基者，主持国史编纂与《三国史记》译注，以实证方法重建三国时代与高句丽的历史框架。其研究兼具民族立场与文献批判，力图摆脱殖民史观；其成绩与局限同源于早期史料稀薄而民族期望过重。"},{"id":"niu-jinda","title":"牛进达：贞观末年的征辽将领","period":"唐·太宗朝","tags":["唐代","将领"],"summary":"牛进达是唐太宗朝将领，贞观二十一年率青丘道海路偏师进攻高句丽，克石城、破积利城，配合李勣陆路。其事迹散见史纪与墓志，记载简略，正可见海路偏师在征辽全局中的辅助位置，也提醒读者注意正史叙事本身的选择性。"},{"id":"zhang-jian","title":"张俭：营州都督与征辽前锋","period":"唐·太宗朝","tags":["唐代","营州"],"summary":"张俭以营州都督率胡兵为征辽前锋，渡辽水趋建安城，把羁縻体系转为军事动员。他兼具边地行政与前线统兵的双重角色，事迹记载相当简略，其形象更多依托职位与制度，而非可考的个性细节，评价他时应留有余地，不可过度坐实。"},{"id":"zhang-shigui","title":"张士贵：征辽军中的募兵与部将","period":"唐·太宗朝","tags":["唐代","将领"],"summary":"张士贵是唐太宗朝老将，征辽时统兵募兵，薛仁贵即应募其军中，驻跸山战后由其举荐得擢。后世演义把他改写成冒功害人的奸臣，与正史及墓志所记相距甚远，可见民间叙事为忠奸对立的需要而重塑人物，这一层距离值得读者警惕。"},{"id":"soeurim","title":"小兽林王：佛教传入与高句丽的制度转向","period":"4世纪·高句丽","tags":["高句丽","佛教","4世纪"],"summary":"高句丽第17代王，名丘夫，371年至384年在位。372年接受前秦佛像经文，同年立太学，373年颁律令，借佛教与儒学重建王权。改革受贵族政治掣肘，所谓汉化实为选择性吸收，未及于地方社会，成果要到广开土王时才显现。"},{"id":"gogukyang","title":"故国壤王：广开土王之前的扩张","period":"4世纪·高句丽","tags":["高句丽","君主","4世纪"],"summary":"高句丽第18代王，384年至391年在位。385年出兵四万袭辽东、玄菟二郡，掳万余口，同年为后燕收复；南线与百济反复交战。在位七年为广开土王的扩张奠定军事与地理基础，但扩张依赖对手内乱，未转为稳定控制。"},{"id":"munja","title":"文咨王：北魏眼中的高句丽","period":"5世纪·高句丽","tags":["高句丽","君主","5世纪"],"summary":"高句丽第21代王，491年至519年在位。492年受北魏册封，拒遣世子入朝；在位朝贡三十三次，并接受南齐、梁封号。494年接收夫余来降，南线与百济、新罗争夺。南北两面外交维持体面，代价是南线消耗；其册封与朝贡的细节，主要见于中国正史。"},{"id":"yangwon","title":"阳原王：北齐北周之间的选择","period":"6世纪·高句丽","tags":["高句丽","君主","6世纪"],"summary":"高句丽第24代王，545年至559年在位。550年受北齐册封，551年击退突厥围城，同年百济与新罗夺取汉江流域。他在位期间北朝更替频繁，突厥进入东北亚，半岛南部的均势也随之改变。对外保守自保，避免更大损失，却使高句丽在半岛由攻转守，被视为衰落的开端。"},{"id":"yeongyang","title":"婴阳王：隋军压境时的国王","period":"6—7世纪·高句丽","tags":["高句丽","隋唐","6-7世纪"],"summary":"高句丽第26代王，590年至618年在位。598年拒隋文帝，612年萨水之战大败隋炀帝远征军，此后两次应对征讨。他在位二十八年，几乎与隋的兴亡相始终。其评价因史源而分裂：半岛史书称其济世安民，中国正史记其反复，战功多归乙支文德。"},{"id":"zhangsun-wuji","title":"长孙无忌：贞观朝的宰相与东征的反对者","period":"唐·太宗高宗朝","tags":["唐代","宰相","政治"],"summary":"唐太宗、高宗朝宰相，长孙皇后之兄，玄武门之变的核心策划者。贞观末受遗诏辅政，领衔撰成《唐律疏议》。对东征主张隐忍待时，反对仓促亲征；后因反对废后失势，流放黔州自缢。他在高宗朝掌权不到十年，身后评价随政局反复。"},{"id":"chu-suiliang","title":"褚遂良：谏阻东征的中书令","period":"唐·太宗高宗朝","tags":["唐代","谏臣","东征"],"summary":"唐太宗、高宗朝大臣，书法列初唐四家。644年上疏谏阻太宗亲征高丽，主张命将出偏师，勿以万乘轻渡辽海。649年受遗诏辅政，655年因反对废王皇后被贬潭州，再贬爱州，卒于贬所。他的谏诤与书法在后世同被称道，但两者都未能改变他所面对的政治。"},{"id":"yan-lide","title":"阎立德：造船、布桥与工部尚书","period":"唐·太宗朝","tags":["唐代","工程","征辽"],"summary":"唐初工部尚书、将作大匠，阎立本之兄。644年主持在洪州等地造海船四百艘，645年随征高丽，筑土山攻安市城，回师时于辽泽填土架桥。技术官僚的工程能力是远征得以维持的条件，其代价则落在役夫与地方，也说明唐初对外扩张的工程基础。"},{"id":"hao-chujun","title":"郝处俊：高宗朝的谏臣","period":"唐·高宗朝","tags":["唐代","谏臣","高句丽"],"summary":"唐高宗朝宰相，贞观进士。乾封年间副李勣征高丽，以胆略著称；后谏止高宗服丹药、谏二王分朋，上元三年力谏阻止天后摄政。其谏多针对具体政事，引礼制与前朝故事为据，未能改变武后掌权的趋势，其立场与高宗朝的权力紧张始终相伴。"},{"id":"xu-jingzong","title":"许敬宗：修史与政治之间","period":"唐·太宗高宗朝","tags":["唐代","史官","政治"],"summary":"唐太宗、高宗朝史官与宰相，长期监修国史。支持立武后，参与修《晋书》《姓氏录》。因私人恩怨与受贿在传记中曲笔，被《新唐书》列入奸臣传。其案例暴露官修史书监修权的弊病，也说明史学一旦服从政治，实录的可信度便难以维持。"},{"id":"uija","title":"义慈王：百济的末代君主","period":"百济·7世纪","tags":["百济","亡国","7世纪"],"summary":"义慈王是百济末代君主，六四一年即位，在位期间宫廷内斗不断，对外一面应付唐廷的停战要求，一面持续攻掠新罗。六六〇年唐罗联军自海上登陆，泗沘城陷落，他与太子出降。后世史书把亡国归因于君德，本文辨析道德化叙述与制度、外交困境之间的关系。"},{"id":"buyeo-yung","title":"扶余隆：熊津都督府下的百济王室","period":"百济·7世纪","tags":["百济","羁縻","7世纪"],"summary":"扶余隆是义慈王太子，六六〇年随父降唐，后被授为熊津都督，成为唐在百济故地代理统治的名义首领。他参与六六五年的熊津会盟，却始终未能真正行使权力，最终留居唐境。本文讨论羁縻体制下王室符号的用处与限度，以及名号与实权分离的处境。"},{"id":"heukchi-sangji","title":"黑齿常之：从百济降将到唐军名将","period":"百济·唐·7世纪","tags":["百济","唐","蕃将"],"summary":"黑齿常之是百济降将，六六三年归唐后在对吐蕃、突厥的战事中屡立军功，官至大将军，主持河源屯田与烽戍建设，六八九年因酷吏诬告下狱自尽。本文讨论蕃将的上升通道、边防贡献与政治风险，以及降将家族融入唐制的路径。"},{"id":"jindeok","title":"真德女王：新罗的对唐外交","period":"新罗·7世纪","tags":["新罗","女王","外交"],"summary":"真德女王六四七至六五四年在位，是新罗对唐外交的关键推动者。她安置金春秋、遣使请兵、以织锦颂进献唐廷，并在六五〇年改行唐年号。本文讨论女主身份如何被转化为外交符号，以及这种策略的限度与七年统治的实际建树。"},{"id":"kim-inmoon","title":"金仁问：往返长安的新罗使臣","period":"新罗·7世纪","tags":["新罗","外交","唐"],"summary":"金仁问是新罗王族，六二九至六九四年，长期在唐宿卫任职，参与灭百济与高句丽的战事，唐罗关系破裂时被留在长安。本文以他的往返经历，讨论使臣在同盟内部承担议价与抵押的双重角色，以及质子制度对王位继承的影响。"},{"id":"shiratori-kurakichi","title":"白鸟库吉：东洋史学的建立者","period":"近代·日本","tags":["东洋史学","满洲朝鲜","近代"],"summary":"白鸟库吉一八六五至一九四二，东京帝国大学教授，东洋史学的建制者之一。他主张尧舜禹为传说，主持受满铁资助的满洲历史地理调查，以比较语言学与文献考证研究北方民族。本文讨论其学术贡献与帝国事业的纠缠，并辨析其考证的可取处与被修正的假说。"},{"id":"tsuda-soukichi","title":"津田左右吉：批判与争议中的东洋史","period":"近代·日本","tags":["东洋史学","思想史","近代"],"summary":"津田左右吉一八七三至一九六一，早稻田大学教授，以记纪文献批判著称。他论证神代叙事为后世政治构造，一九四〇年因不敬罪被起诉判刑。本文讨论其方法的贡献、政治压制下的处境与实证主义的局限，以及战后评价翻转所反映的标准变化。"},{"id":"bai-genxing","title":"拜根兴：唐与新罗关系的研究者","period":"现代·中国","tags":["唐史","新罗","现代学术"],"summary":"拜根兴是陕西师范大学唐史学者，以《七世纪中叶唐与新罗关系研究》为代表，利用新出墓志与正史互证，考订百济、新罗出身者在唐的行迹。本文讨论石刻材料如何修正旧说，说明墓志作为史料的边界，并指出以石刻补史在理论上的薄弱之处。"},{"id":"sun-jinji","title":"孙进己：东北民族史的系统整理","period":"现代·中国","tags":["东北史","民族史","现代学术"],"summary":"孙进己一九三一至二〇一四，辽宁社会科学院研究员，以多卷本东北民族史著作系统整理族群材料。本文讨论他以民族为单位的叙述框架如何改变东北史的重心，以及这一框架在族群流动与边界问题上的局限，并指出宏观框架与地方研究之间的张力。"},{"id":"wang-mianhou","title":"王绵厚：高句丽遗迹的调查者","period":"现代·中国","tags":["考古","高句丽","现代学术"],"summary":"王绵厚是辽宁的考古研究者，长期实地调查高句丽山城、墓葬与交通线。本文说明田野工作如何把文献中的城名落到地形上，揭示由城、戍、烽、障组成的防御网络，并讨论调查材料在断代与地名比对上证据强度的局限，以及调查与发掘在结论可靠性上的差别。"}];

const research = [{"id":"tang-goguryeo-background","title":"唐代东北亚国际格局：高句丽、百济、新罗与唐的四方博弈","date":"2026-06-14","tags":["唐与高句丽","东亚史","国际关系"],"summary":"唐初的东北亚并非唐与高句丽的双边对峙，而是唐、高句丽、百济、新罗四方，再加不时介入的倭国与漠北突厥共同构成的体系。高句丽据辽东与半岛北部，百济联倭以制新罗，新罗则以称臣纳贡换取唐朝支持。理解这一格局的地理基础、制度往来、各国动机与联盟转换，是理解此后七十年战争的前提。"},{"id":"tang-taizong-campaign","title":"唐太宗征高句丽：一场不完美的胜利","date":"2026-06-13","tags":["唐与高句丽","战争","李世民"],"summary":"贞观十九年，唐太宗亲率水陆大军征讨高句丽，连下辽东十余城，却在安市城下受阻，因雨季、粮运与严寒被迫撤军。此役战果可观而未竟灭国之功，暴露出府兵远征、补给线过长与辽东气候的三重限制。太宗晚年改行疲敌之策，把决战转为消耗，为高宗朝最终灭国埋下伏笔，此役也成为太宗朝对外用兵的转折点。"},{"id":"tang-goguryeo-fall","title":"高句丽的灭亡：从内部看一个王朝的崩溃","date":"2026-06-12","tags":["唐与高句丽","战争","灭亡原因"],"summary":"总章元年，李勣攻破平壤，高句丽亡。唐朝先灭百济、再南北夹击的方略固然高明，但真正掏空这个七百年政权的，是渊盖苏文专权之后的继承内讧、长期战争造成的人口与仓储损耗，以及城邑联合体在中央权威失效后的迅速离散。高句丽并非集权国家，中央一旦失灵，地方降附便迅速蔓延。外部压力与内部裂痕互为条件，缺一不可。"},{"id":"tang-annandong","title":"安东都护府：唐朝对高句丽故地的统治及其困境","date":"2026-06-11","tags":["唐与高句丽","统治政策","安东都护府"],"summary":"灭亡高句丽后，唐在平壤设安东都护府，下辖九都督府四十二州，试图把辽东与半岛北部纳入直接统治。然而遗民抵抗、新罗北进、吐蕃牵制与后勤成本叠加，都护府不到十年便内迁辽东，继而退往辽西、幽州。它的收缩说明边疆统治取决于成本与收益的平衡，也取决于本地合作者的向背；这不足十年的经营更像一次多方试探，而非单向的统治实验。"},{"id":"sui-goguryeo-campaigns","title":"隋征高句丽：大业年间三次东征的失败逻辑","date":"2026-08-05","tags":["隋与高句丽","战争","隋炀帝"],"summary":"612至614年，隋炀帝三次征讨高句丽，百万大军久困于辽东坚城之下，萨水一役九军溃散，生还者寥寥，杨玄感之乱又迫使仓促撤军。远征的失败不只是军事问题，更暴露了隋朝强大动员能力与僵化战略决策之间的巨大落差。后勤、指挥与时机，构成了三次远征共同的失败逻辑，也把大业盛世推向了崩溃的边缘。"},{"id":"baekgang-east-asia","title":"白江口之战的东亚意义：海权与朝贡秩序","date":"2026-08-03","tags":["唐代","白江口","海权"],"summary":"663年白江口之战，唐军以七千余人、一百七十艘战船大破倭国水军，焚其战船四百余艘，百济复国运动随之终结。此战之后，半岛局势与倭国的国家转型同时被改写，唐朝在东亚朝贡秩序中的核心地位由此确立。战事规模有限，影响却绵延千年。一场海战如何重塑七世纪东亚的国际结构，海权在其中又扮演了什么角色？"},{"id":"tang-silla-war-revisited","title":"唐罗战争再考：半岛主导权之争的始末","date":"2026-07-30","tags":["唐代","新罗","唐罗战争"],"summary":"668年唐罗联军攻灭高句丽，不到两年盟友反目。双方在城戍与粮道之间反复拉锯，新罗以山地游击牵制唐军，唐朝则因吐蕃西线告急而力不从心，在核算成本之后选择了体面的收缩。676年安东都护府内迁，半岛主导权之争以唐的事实退让告终。这场常被忽略的战争，如何改写了半岛与中原关系的走向？"},{"id":"salsu-battle","title":"萨水之战：隋军东征的崩溃","date":"2026-11-20","tags":["唐与高句丽","隋唐","军事史"],"summary":"大业八年，隋炀帝以号称二百万之众东征，九军三十万五千人渡辽，水军自东莱直趋平壤。高句丽大臣乙支文德以请和窥探虚实，又以七战七退诱隋军深入。萨水半渡之际伏兵齐发，九军一夜溃散，还至辽东城者仅二千七百人。此役断送第一次东征，也把隋朝动员的极限与决策的僵化一同暴露，水陆脱节与指挥不一是溃败的直接缘由。"},{"id":"ansic-seige","title":"安市城之役：唐太宗攻坚的极限","date":"2026-11-19","tags":["唐与高句丽","唐太宗","攻城战"],"summary":"贞观十九年，唐太宗连下辽东、白岩诸城，进围安市。安市依山为城，守御坚固，唐军筑土山、昼夜强攻，土山崩塌压城而守军旋即堵塞缺口；薛仁贵白衣先登实发生于城东南的驻跸山之战。久攻不下，辽左早寒、粮运将尽，太宗只得班师。此役使唐放弃一举灭国的设想，改取长期消耗，为高宗朝先灭百济、再图平壤的方略留下伏笔。"},{"id":"quan-brothers-coup","title":"泉氏兄弟之乱与平壤的陷落","date":"2026-11-16","tags":["唐与高句丽","高句丽内政","灭国"],"summary":"乾封元年泉盖苏文死后，长子泉男生与弟泉男建、泉男产争权，男生据国内城自守，遣子献诚入唐求援。唐以李勣为辽东道行军大总管，分道进击，新城、扶余城相继失守。总章元年平壤被围，宝藏王出降，男建固守至城门被启，高句丽亡。兄弟阋墙为唐军提供了向导与口实，城邑联合体的离散则使抵抗难以持续。"},{"id":"goguryeo-mountain-fortresses","title":"高句丽的山城：城邑防御与战争形态","date":"2026-11-18","tags":["唐与高句丽","军事地理","城防"],"summary":"高句丽的政治与军事组织以城为单位，王城与山城构成平原城居住、山城避战储粮的组合。丸都山城、国内城与平壤一带的城址显示石筑与土筑并存、马面与瓮城等设施渐备。这种城邑网络迫使隋唐以长期围城和逐城争夺取代一战决胜，城破后的降服与迁民又重塑了辽东的人口与秩序，也使战争形态长期停留于攻城与守城。"},{"id":"tang-liaodong-logistics","title":"唐军征辽的后勤：海运、转输与羁縻兵","date":"2026-11-17","tags":["唐与高句丽","后勤","军事制度"],"summary":"唐军征辽受制于距离与季节：辽左早寒，草枯水冻，陆路须经营州、辽西转输，海路自东莱一带渡海，运量受风涛与滩险限制。军粮、资储、器械与马匹的转运成本，加上契丹、奚、靺鞨、突厥降部等羁縻兵的征调与可靠性问题，共同限制了战争规模与持续时间。太宗贞观十九年因粮尽班师，正是这一约束的明证。"},{"id":"sources-on-tang-goguryeo-war","title":"唐丽战争的史料谱系：两《唐书》《通鉴》与《三国史记》","date":"2026-11-21","tags":["唐与高句丽","史料","史学史"],"summary":"唐丽战争的传世记载多成于战后，分属中国正史与朝鲜半岛史书两个传统。本文清理两《唐书·东夷传》、《资治通鉴》唐纪与《考异》、《唐会要》《册府元龟》《通典》以及《三国史记》《三国遗事》的史源与编纂意图，并以好太王碑、平百济碑、泉氏墓志等石刻相参，讨论兵力、路线与日期记载分歧的成因，并提出多源对勘、区分叙事与制度的原则。"},{"id":"goguryeo-remnants-bohai","title":"战后高句丽遗民与渤海国的成立","date":"2026-11-22","tags":["唐与高句丽","遗民","渤海"],"summary":"668 年高句丽灭亡后，唐廷将王室、贵族与大批民户迁往中原、营州与河南等地，遗民反抗与安东都护府的内迁随之而来。696 年营州之乱给了粟末靺鞨东奔的机会，大祚荣于 698 年建震国，后受唐册封为渤海。以下梳理迁徙、叛乱、羁縻与质子关系，并检讨渤海族属之争及小高句丽、投突厥与投新罗诸支流。"},{"id":"tang-fan-generals-goguryeo","title":"蕃将与降众：唐军中的非汉兵力","date":"2026-11-23","tags":["唐与高句丽","蕃将","军事制度"],"summary":"唐军征辽的兵力中，突厥、契丹、奚、靺鞨、高句丽与百济的部落兵占了相当比重。这里从羁縻体制、质子宿卫与入朝制度入手，讨论蕃将的双重身份、蕃兵在骑兵、向导与译语方面的作用及其可靠性，并以泉男生、高侃、黑齿常之为例，分析降众安置的三条路径与蕃将忠诚的结构性两难，兼及安史之乱后的格局变化。"},{"id":"goguryeo-diplomacy-northern-dynasties","title":"高句丽的南北外交：从北魏到陈隋","date":"2026-11-24","tags":["唐与高句丽","外交","南北朝"],"summary":"五世纪起，高句丽同时向北魏与南朝遣使受封，以两套正统互相制衡。辽东归属、百济求援与好太王碑所记的南征，构成这套外交的现实背景；使节或经幽州陆路，或自东莱渡海。北齐、北周与陈并立时封号层层加码，突厥兴起后东北亚又多一角。隋统一后朝贡收紧，598年的冲突宣告两面外交走到尽头。"},{"id":"tang-naval-goguryeo","title":"跨海之师：唐军的水军与登陆作战","date":"2026-11-25","tags":["唐与高句丽","水军","登陆战"],"summary":"唐征高句丽的关键一环是跨海投送。来护儿自东莱入海，孤军深入而败；张亮取卑沙城，在辽东半岛南端建立登陆点；苏定方自成山渡海，直取锦江口灭百济；刘仁轨与杜爽在锦江下游确立制海权。船型、季风与滩险约束航路，登陆点的选择与水陆协同的得失，决定灭国战能否成立。唐军前后经营二十余年，海路始终是其中一环。"},{"id":"goguryeo-armor-weapons","title":"高句丽的甲骑与兵器：壁画与出土物所见","date":"2026-11-26","tags":["唐与高句丽","军事","考古"],"summary":"高句丽军事装备研究依赖集安、平壤壁画墓与城址出土物两类材料。壁画显示四至五世纪已有具装骑兵，马铠、兜鍪、札甲形制与中原、鲜卑技术圈相通；出土铁甲片、双镫马具与箭镞则揭示本地工艺与实战面相。作者强调壁画具仪卫与程式化性质，不能当写实照片，甲骑规模亦不宜夸大，须与出土物、文献互证。"},{"id":"tang-liaodong-fortifications","title":"唐军在辽东的筑城与驻防","date":"2026-11-27","tags":["唐与高句丽","军事地理","城防"],"summary":"唐丽战争的骨架是城与路：辽东城、白岩城、安市城的攻守，背后是转输、季节与驻军结构。唐军善用云梯、抛车、土山，却受辽左早寒与粮道漫长的约束，安市城久攻不下即是明证。灭高句丽后安东都护府一再内迁，说明唐的据点经营多为修缮旧城、以点控线，攻城易而守土难，成本始终受制于后勤与人力。"},{"id":"baekje-restoration","title":"百济复国运动：灭亡之后的三年","date":"2026-11-28","tags":["唐与高句丽","百济","东亚史"],"summary":"660 年百济灭亡后，鬼室福信与僧道琛拥立扶余丰，据周留城等据点起兵，并向倭国求援。663 年白江口之战，唐军水师击败倭国与百济联军，复国运动随之瓦解。作者指出，复国失败根源于抵抗分散、缺乏统一后勤；战后百济遗民分入唐、入倭与留居故地，而唐罗对百济故地的安排已埋下双方冲突的种子。"},{"id":"silla-unification-cost","title":"统一新罗的代价：战争、户口与地方秩序","date":"2026-11-29","tags":["唐与高句丽","新罗","社会史"],"summary":"新罗借唐之力灭百济、高句丽，又在 670 年代与唐交战，完成半岛大部分的统一。作者把视线从疆域转向代价：战争造成人口损耗与迁徙，军功集团需要安置，百济、高句丽故地的地方豪族被纳入州郡县的双层结构，而骨品制并未随疆域扩大而改造。这些结构性问题在九世纪的地方动乱中显现，统一的账单远比传统叙述复杂。"},{"id":"goguryeo-buddhism","title":"高句丽的佛教与国家：寺院、僧侣与王权","date":"2026-11-30","tags":["唐与高句丽","佛教","制度"],"summary":"佛教于 372 年由前秦传入高句丽，走的是使者送经、国王接纳的国家通道，因而自始与王权绑定。寺院多建于都城附近，佛教为王权提供超越血缘的正当性，却与山神、始祖祭祀并存而非取代。僧侣兼具外交与情报角色，道琳的故事虽属传奇，仍反映时人想象。与百济、新罗相比，高句丽佛教与王权结合早而制度化程度较浅。"},{"id":"tang-goguryeo-diplomacy","title":"唐与高句丽的交涉：诏书、表文与礼仪","date":"2026-12-01","tags":["唐与高句丽","外交","史料"],"summary":"唐丽之间近三十年的诏书与表文往来，表面是礼仪交锋，实质是两种秩序观的碰撞。唐以汉四郡旧地为据，要求拆长城、还人口、停攻新罗；高句丽以数百年据有为据，只在谢罪与献方物上周旋。册封、质子与和亲的缺席，说明唐把它放在郡县旧地而非对等外国的位置，交涉因此没有妥协空间。"},{"id":"khitan-goguryeo","title":"契丹与高句丽：草原与半岛之间","date":"2026-12-02","tags":["唐与高句丽","契丹","北方民族"],"summary":"契丹夹在突厥、高句丽与唐之间，羁縻与朝贡都只是权宜，依附强者才是常态。696年营州之乱因赵文翙的苛待与饥荒而起，李尽忠、孙万荣据营州称汗，唐军两败，最终靠奚人与突厥默啜的夹击才平定。乱后营州失守、靺鞨东走建渤海，东北人群重组，契丹终成另一个秩序中心。唐的东北秩序也从此改观。"},{"id":"goguryeo-migrations","title":"高句丽人口的流散：入唐、入突厥、入渤海","date":"2026-12-03","tags":["唐与高句丽","遗民","人口史"],"summary":"668年高句丽灭亡后，唐分层处置其人口：王族与富户迁入江淮、山南，降将编入唐军，贫弱者留守安东。泉男生、高仙芝家族在唐获得新位置，部分遗民北投突厥、东入渤海，留居者渐入新罗。流散持续数十年，故地换了主人，东北的人群结构也由此重塑。唐的羁縻安排与遗民的再流动互为因果。"},{"id":"tang-east-asia-order","title":"唐初的东亚秩序：礼仪、册封与利益","date":"2026-12-04","tags":["唐与高句丽","国际关系","制度"],"summary":"唐初东亚秩序以册封、羁縻府州、质子宿卫与朝贡为骨架，礼仪与利益在其中交错。高句丽、百济、新罗、倭各有用法，唐的调停与征伐受实力、后勤与季节约束。把它看成单向支配会失掉真相：这是一套可谈判的制度语言，稳定取决于利益交换，礼仪只是外壳。它的边界始终由军力与后勤画定。"},{"id":"historiography-goguryeo-modern","title":"近代史学中的高句丽：民族叙事与考古","date":"2026-12-05","tags":["唐与高句丽","史学史","考古"],"summary":"高句丽研究有民族叙事与考古实证两条线索。好太王碑1877年发现于集安，把研究从文献转述推向原始记录；此后日本满鲜史、朝韩的民族叙事与中国边疆史观各自展开，2002年东北工程引发争议。考古提供年代、形制与交流的证据，归属却是政治与历史叙事的建构。把两者分开，才谈得上真正的讨论。"},{"id":"campaign-season-climate","title":"出征的季节：唐丽战争与气候条件","date":"2026-12-15","tags":["唐与高句丽","气候","军事"],"summary":"唐丽战争的作战窗口，由辽河封冻、河北山东的农时与渤海风信共同划定。本文从贞观十九年班师诏的「辽左早寒，草枯水冻」入手，考察气候如何压缩远征时间、牵动海运与粮运，并说明气候只是约束条件，胜负仍取决于攻坚与政治。文章也提醒，气候重建的尺度是区域与十年，与编年记载中的某一天并不重合。"},{"id":"goguryeo-five-departments","title":"高句丽的五部与地方统治","date":"2026-12-14","tags":["高句丽","制度","五部"],"summary":"五部常被画成五个整齐的方位行政区，实际更像王畿内以族属与居地为基础的贵族集团。本文梳理五部名称、褥萨等官号与城村关系，讨论王权与贵族的张力，并对照唐的羁縻府州与安东都护府，指出唐的府州只是授号，未能替换地方权力，细节仍有讨论，读材料要分清名称、官号与运作三层。"},{"id":"tang-allied-cavalry","title":"唐军中的蕃骑：突厥、契丹与奚的参战","date":"2026-12-13","tags":["唐代","蕃兵","军事"],"summary":"贞观十九年渡辽的唐军里有契丹、奚的骑兵与突厥降户，他们既是野战机动的主力，也是最易哗变的一环。本文从羁縻征发、蕃将笼络、赏赐军纪与战后安置入手，分析以夷制夷的成本与风险，指出唐廷以婚姻与官爵购买忠诚，而忠诚的价格随局势浮动，正史于部众数目、编制与补给则语焉不详。"},{"id":"liaodong-city-645","title":"辽东城之战：贞观十九年的第一场硬仗","date":"2026-12-12","tags":["唐与高句丽","攻坚","贞观"],"summary":"贞观十九年五月，唐军兵临辽东城下，这是整场战役的第一场硬仗。本文复原李勣与李道宗的部署、土山冲车与火攻的工序，分析风向、工期与补给如何决定成败，并与安市城对照，说明唐军攻坚的技术上限，以及诸书对同一战斗记载的差异，守军一侧则几无材料，只能从唐军叙述反推攻城细节。"},{"id":"goguryeo-royal-succession","title":"高句丽的王位继承与婚姻网络","date":"2026-12-11","tags":["高句丽","王权","婚姻"],"summary":"高句丽七百余年二十八王，父子相继与兄终弟及并存，继承始终没有定为一尊。本文讨论王后族属、母族势力与五部拥立如何左右王位，追踪泉氏专权与唐的介入，并检讨《三国史记》与《好太王碑》各自能看到什么，认为继承规则的不确定正是政治动荡的结构性来源，也为唐的介入留出缝隙。"},{"id":"expedition-finance","title":"征辽的钱粮：隋唐如何供养远征军","date":"2026-12-10","tags":["唐与高句丽","财政","后勤"],"summary":"隋唐两代征辽，后勤的差别决定了战争的形态。隋靠仓储与运河做一次性总动员，粮道从涿郡铺到辽东，民夫征发误了农时，也点燃了隋末民变；唐以租庸调为底，辅以和籴、河北转输、江南造船与就地补给，把战争摊到二十多年。军费数字多不可信，但粮道的距离与损耗是硬的：财政能力不决定战争为何发生，却决定它能打多久。"},{"id":"tang-maps-guides","title":"向导与地图：唐军如何认识辽东","date":"2026-12-09","tags":["唐与高句丽","情报","地理"],"summary":"唐军对辽东的地理知识，来自隋代旧档、使节目见、蕃族向导与斥候，而非系统地图。泉男生降唐后指点城邑兵力，是高宗灭高句丽的关键情报；太宗亲征仍靠指授方略，诏令滞后于前线。安市城下的判断失误说明：知道多少不等于能决断多少。本文兼及《通鉴》叙事为太宗回护的可能，把信息优势放回它的限度里。"},{"id":"goguryeo-wooden-tablets","title":"木简与城民：高句丽社会的出土文书","date":"2026-12-08","tags":["高句丽","出土文献","社会"],"summary":"集安与平壤出土的高句丽木简，多为残断的标签、簿籍与文书残件，数量有限而释读困难。其中的城民、谷仓、官号记录，显示高句丽有以城为单位的户籍、仓储与文书行政，可与《三国史记》互证，却不能替代编年叙事。本文讨论木简能证明什么、不能证明什么，以及废弃堆积造成的样本偏差。"},{"id":"japan-after-663","title":"白江口之后：日本律令国家的防御转向","date":"2026-12-07","tags":["日本史","白江口","律令"],"summary":"663年白江口战败后，天智朝在九州筑水城、大野城、基肄城，置防人与烽，同时加速律令编纂、造庚午年籍、迁都近江。防御工程借百济遗民的技术，学习唐制与戒备唐军并行。《日本书纪》成书于半世纪后，把应急举措写成圣君决策。本文辨析制度事实与叙事建构，说明战败如何被转化为国家建设的动力。"},{"id":"goguryeo-textbooks","title":"教科书里的高句丽：四国叙事的差异","date":"2026-12-06","tags":["高句丽","史学史","教育"],"summary":"高句丽在四国教科书里位置不同：中国置于边疆史与统一叙事，朝鲜与韩国置于三国与民族谱系，日本置于东亚互动。归属、好太王碑与东北工程是争议焦点，各方史料依据与盲区并存。本文并置四种叙述的前提，区分可检验的史料问题与超出史料的政治判断，不做站队，只说明教育如何塑造集体记忆。"},{"id":"tang-army-organization","title":"唐军的编制与行军：折冲府、行军大总管与六军","date":"2026-12-25","tags":["唐丽战争","军事制度","行军"],"summary":"贞观十八年冬，幽州城南按团旅队火列队的府兵，引出折冲府的编制、自备资装与关内调兵的距离；再论行军大总管属临时统兵、六军是后世追加的标签，并以安市之战的临时编组与粮运驿传，说明这支军队能走远却难以久战：胜负往往取决于粮车而非阵列，这一点，诏令里从不明写，史书也语焉不详。"},{"id":"soldier-life-expedition","title":"征人的日常：军书、家书与徭役","date":"2026-12-24","tags":["唐丽战争","士兵","社会史"],"summary":"一名府兵的行囊里装着九斗麦饭、二斗米和一张弓，点兵文书决定他何时离家。文章由此串起征发、转输、口粮、伤病与徭役，比较正史、墓志、家书与诗歌的立场与缺口，指出士兵经验在史料中只剩轮廓；末段回到行囊的重量，追问国家的承诺与农家的付出是否对等，而墓志只肯记住体面的那一面。"},{"id":"mohe-allies-goguryeo","title":"靺鞨与高句丽：战争中的北方同盟","date":"2026-12-23","tags":["唐丽战争","靺鞨","同盟"],"summary":"安市城下，高句丽援军里的靺鞨人战后被与高句丽俘虏分开处置。文章由此辨析靺鞨七部与高句丽的役属关系，说明唐以羁縻名号与物资招抚、高句丽以征发与赏赐维系，同盟的脆弱源于间接统治与酋长在两条依附线之间的计算；并提醒读者，把靺鞨当作统一的行为体，是讨论同盟时最常见的陷阱。"},{"id":"goguryeo-noble-politics","title":"大对卢与贵族政治：高句丽权力结构的内侧","date":"2026-12-22","tags":["唐丽战争","高句丽","政治史"],"summary":"《旧唐书》记大对卢三年一代，交替之日或勒兵相攻。文章由此分析五部贵族与王权的张力：任期制只定任期而未定仲裁，莫离支靠个人压服诸家，泉氏兄弟内斗遂成亡国导火索；并检讨中原文献与《三国史记》的层层改写，收束于那个始终没有仲裁者的交接机制，看它如何耗尽一个政权的余地。"},{"id":"tang-military-law","title":"军法与赏功：唐律中的行军条款","date":"2026-12-21","tags":["唐丽战争","军法","唐律"],"summary":"《唐律疏议·擅兴律》规定守城弃去者斩。文章由此梳理失期、逃亡、冒名与掠夺等条款，说明军法以刑罚替代议价、以勋赏维持士气，再以安市赐帛、俘获分配与张亮之诛为例，辨析法典文本与行军实践之间的落差；军法的效力，最终仍取决于粮车、天气与朝廷的政治计算，条文本身并不能决定。"},{"id":"wounded-medicine-expedition","title":"伤病与救护：远征军中的医疗","date":"2026-12-20","tags":["唐丽战争","医疗","后勤"],"summary":"从贞观十九年撤军路上的伤员写起，梳理箭伤、冻伤与疫病在远征中的分布，考察随军医工、药材供应与后送据点的实际条件，说明运输能力如何限定救护的上限，指出医疗组织对攻城与撤退节奏的反向约束，并辨明太宗亲为契苾何力敷药一类记载的叙事性质：它能证明仁君形象被生产与传抄，不能证明普通士卒所得的医疗水平。"},{"id":"homefront-expedition","title":"后方的家：征人家庭的生计与赋役","date":"2026-12-19","tags":["唐丽战争","赋役","家庭"],"summary":"从贞观年间河北乡村的一次点丁写起，说明租庸调与府兵自备资装如何叠加成家庭的一次性支出，运输与造船差科如何占用农时，摊逃机制如何把一户的破产传导给邻户，减免与复除在执行中又如何折损，并指出正史、政书与墓志的官府视角、统计口径与阶层偏差，以及复员与勋赏兑现的延迟。战争于是从一次征发变成乡村社会的长期重组。"},{"id":"pyeongyang-siege-668","title":"平壤之围：都城如何陷落","date":"2026-12-18","tags":["唐丽战争","平壤","攻城"],"summary":"以总章元年平壤受降为线索，复原唐军肃清外围、鸭绿栅与辱夷城之战、月余围城、白幡出降与信诚开门的过程，分析渊盖苏文死后贵族分裂如何使内应成为可能，并以安市城久攻不下作对照，说明唐军的胜利来自城内分裂而非攻城器械的突破，围城时间也受自身补给线的限制，投降仪式的细节则多出自唐军报捷文本。"},{"id":"war-edicts-rhetoric","title":"诏令中的战争：唐廷如何论证东征","date":"2026-12-17","tags":["唐丽战争","诏令","政治修辞"],"summary":"以贞观十八年亲征诏令为材料，拆解弑君、救新罗、复旧疆三套说辞的分工与互补，说明它们分别面向官僚、军队、藩属与民间，比较诏令、纪功碑与谏表三种文本的受众差异，讨论宣传文本能证明什么、不能证明什么，并指出同一套说辞会随战局由动员转为解释与抚纳，修辞因此是动员机制的一部分，受众不同，同一理由的分量也不同。"},{"id":"battlefield-archaeology","title":"战场考古：萨水、安市与白江口的实地","date":"2026-12-16","tags":["唐丽战争","考古","战场"],"summary":"从清川江下游的地貌写起，讨论萨水、安市城与白江口三处战场的文献定位与考古现状，说明河道变迁、遗物回收、地层改造与跨国准入如何限制战场考古，评估遥感、地球物理与沉积采样的限度，并指出地名层证据的不可靠，主张以军事地理与后勤条件为解释框架，而不是对某场战役的指认，考古与文献因而是两类证据。"},{"id":"tang-armor-weapons-workshops","title":"甲胄与兵器：唐军在辽东的装备来源","date":"2026-12-28","tags":["唐与高句丽","军事史","军工"],"summary":"唐军甲仗的来源一分为二：弓刀行装由士兵自备，甲胄、长槊与攻守器械由官府调发。军器监的甲坊、弩坊掌重器制造，地方作院承担消耗品，成品经武库与军府库点验发放；远征中靠随军工匠修补，靠攻克城池缴获补充。高句丽同样有铁札甲与甲骑传统，考古出土的甲片散乱难复原，难换算守军装备率。双方差别多在组织与补给能力，而非单件工艺。"},{"id":"fubing-expedition-mobilization","title":"府兵、募兵与征辽动员","date":"2026-12-27","tags":["唐与高句丽","制度史","军事史"],"summary":"贞观、显庆、总章几次东征的兵源并非单一：折冲府征发的府兵是骨干，召募的兵募、归附的蕃部骑兵与新罗助攻部队同时并用。府兵受田免役，却有服役期限，远役数千里使轮换与补给都很吃力；募兵以赐物勋赏为诱，蕃兵可充向导斥候而纪律难保。路程与粮运压缩了可用作战天数，几次班师都与此有关。兵力数字多出自诏书军报，需谨慎对待。"},{"id":"tang-grain-transport-liaodong","title":"海运与漕运：征辽的粮道","date":"2026-12-26","tags":["唐与高句丽","经济史","后勤"],"summary":"征辽的粮道分陆海两途：河北道依托永济渠与驿道分段北输，河南道自登州、莱州泛海，张亮舟师即由此攻卑沙城。海运载量大却受季风与船期限制，韦挺因馈运失期获罪，可见朝廷对粮运的倚重。前线仓廪设于怀远镇、辽东城等据点，就地取给又常被坚壁清野破坏。辽左早寒、粮运不继，几次班师与解围都发生在这个节点上。"},{"id":"goguryeo-fortress-supply","title":"山城的粮储与围城耐受","date":"2026-12-25","tags":["唐与高句丽","军事史","考古"],"summary":"高句丽山城多筑于山脊与河谷台地，石墙顺地形起伏，城内有水池、仓址与作坊，与平原城互为表里。城与城以道路、烽燧相连，一城受攻，邻城可策应或断粮道，故围城常以月计。安市城久攻不下，辽东城、白岩城却先后失守，说明城防并非不可破。考古所见的炭化粮谷能证明储粮，却不足以推算可守时日；城址面积也难换算守军人数。"},{"id":"tang-scouts-intelligence","title":"斥候与间谍：战场情报的获取","date":"2026-12-24","tags":["唐与高句丽","军事史","情报"],"summary":"唐军在辽东的情报主要来自斥候、向导、俘虏口供与降人。斥候沿山脊河谷多路搜索，向导多出于蕃部、俘民与商旅，可靠与否直接影响行军安全。高句丽则以坚壁清野应对，撤民入城、焚匿刍粮、断道毁桥，使唐军野无所掠，也切断了其与地方社会的联系。安市城下对守军与援军规模的误判，说明情报不足是常态，「不知虚实」之评需分辨纪事与评语。"},{"id":"goguryeo-cavalry-warfare","title":"高句丽骑兵与骑战传统","date":"2026-12-23","tags":["唐与高句丽","军事史","骑兵"],"summary":"从集安壁画中的甲骑具装图像入手，说明骑兵在高句丽城防体系中的机动角色，并与唐军轻骑的战术节奏作对比。文章指出壁画年代与唐丽战争相距百年，墓葬图像服从构图与身份表达，不能当作编制表；重骑的维持成本与马匹来源，则解释了图像与实战之间的落差。文章最后回到图像与实战的距离。"},{"id":"siege-machines-tang","title":"攻城器械与炮石","date":"2026-12-22","tags":["唐与高句丽","军事史","技术史"],"summary":"以645年辽东城、安市城的攻防为线索，考察冲车、云梯、抛车在唐丽战争中的实际使用。文章辨析「炮石」与「烈风发火弩」的记载，指出抛车并非火药火炮，器械效能受运输、就地取材与守方应对制约。攻城是系统工程，唐军的进退多由粮运与人力决定，技术叙事常掩盖这层因果，并指出器械优势常被粮运与守方抵消。"},{"id":"winter-warfare-liaodong","title":"冬季作战与冻馁","date":"2026-12-21","tags":["唐与高句丽","军事史","气候"],"summary":"从唐太宗班师诏中「辽左早寒」一语出发，考察秋季之后草料、粮运与海运的困境，以及冻伤、疫病对军队减员的影响。文章认为寒冷主要通过后勤与营地条件起作用，气候解释不能替代政治、城防与决策分析，并比较冬季海运与陆运在运量上的差异，说明结冰与风浪如何压缩补给。把退兵全归于天气，会漏掉补给与决策的环节。"},{"id":"goguryeo-elite-after-668","title":"战后高句丽精英的入唐与安置","date":"2026-12-20","tags":["唐与高句丽","社会史","移民"],"summary":"以泉男生、泉男产、泉男建三支的不同结局为线索，考察668年后唐廷对高句丽降人的授官、内徙与安东都护府下的酋渠任官。结合洛阳出土的泉氏墓志，分析入唐精英如何在官爵、婚姻与葬俗中重编身份，并追踪泉氏后人在武周、玄宗朝的踪迹，指出精英身份得以延续而政权早已消失，其家族史随后并入唐朝的谱系。"},{"id":"tang-silla-border-disputes","title":"唐罗边界交涉与「买地」之争","date":"2026-12-19","tags":["唐与高句丽","外交史","新罗"],"summary":"以668年后唐罗对百济故地、高句丽南境的争夺为线索，梳理文武王时期上表、谢罪与出兵并行的双轨策略，以及674年至676年间的战事与安东都护府内迁。文章辨析《三国史记》所载「买地」之说，指出其属于新罗一方的叙述立场，并对七重城、买肖城等城戍归属的记载差异略作讨论，兼及兵力与补给线对边界形态的影响。"},{"id":"goguryeo-prisoners-migration","title":"战俘、迁民与人口流动","date":"2026-12-18","tags":["唐与高句丽","社会史","人口"],"summary":"总章二年移高丽户二万八千二百的诏令，把战争的收尾写成一次有车有牛的搬家。文章辨析历次俘获数字的重复与夸饰，追踪江淮、山南与并凉诸州的安置、附籍与逃户，再论安东都护府内迁与辽东人口真空，指出迁民是持续数十年的过程，被迁者逃亡、再迁、通婚改姓，最终以「消失」收束。"},{"id":"goguryeo-diaspora-japan","title":"渡日高句丽人及其后裔","date":"2026-12-17","tags":["唐与高句丽","东亚","移民"],"summary":"灵龟二年，一千七百九十九名高丽人被迁到武藏国，始置高丽郡。文章由此追踪高句丽亡后的渡海路径、赐姓与任官，说明高丽、背奈、狛诸氏如何被编入日本氏姓秩序，技术传播与在地聚落如何留下痕迹，并检讨「渡来人」叙述在古代朝廷、殖民时期与战后的不同用途，以及它如何遮蔽当事人的处境。"},{"id":"postwar-commemoration-steles","title":"战后纪念：碑刻与记忆","date":"2026-12-16","tags":["唐与高句丽","记忆史","碑刻"],"summary":"悯忠寺拖了五十一年才建成，好太王碑却把功业与守墓义务一次刻定。文章比较唐军纪功刻石、阵亡追赠与地方祠庙，与高句丽王陵碑刻一类纪念碑的政治功能，辨析碑与志的差别，并从拓本失真、后世重修与「满鲜史」叙事，讨论碑刻作为史料能证明什么、不能证明什么，以及记忆如何被反复编排。"},{"id":"sogdians-silk-road","title":"粟特人：丝路上的商业社群","date":"2027-01-07","tags":["粟特","丝绸之路","商业"],"summary":"从敦煌出土的粟特语信札切入，讨论粟特城邦为何依赖商队贸易，家族商号、共享语言与萨保制度如何降低远距离交易的成本；结合古信札、穆格山文书与汉文墓志，辨析三类材料的视角差异；并追踪安史之乱后网络随回鹘、大食与海上贸易兴起而收缩的过程，说明粟特人既是族群标签也是商业组织方式。"},{"id":"silver-global-trade","title":"白银与全球贸易：16—18世纪","date":"2027-01-06","tags":["白银","全球贸易","明清"],"summary":"以马尼拉海关记录的可信度为起点，梳理十六至十八世纪美洲银与日本银进入中国的通道，分析一条鞭法之后白银财政与银钱双轨如何运作，商帮与汇兑承担了怎样的角色；并讨论物价、存量估算与白银帝国说的限度，指出中国是最大需求端而非规则制定者，十九世纪白银外流暴露了这一体系的脆弱。"},{"id":"frontier-governance-qing","title":"清代的边疆治理：盟旗与伯克","date":"2027-01-05","tags":["清代","边疆","治理"],"summary":"从《理藩院则例》的条文差异入手，说明清朝以理藩院、军府与驻藏大臣为骨架，在蒙古推行盟旗、在南疆保留伯克、在西藏监督转世、在西南改土归流；分析因俗而治与分而治之如何借助中介精英降低治理成本，并讨论财政、驻军与清末新政对这套安排的改造及其弹性与脆弱，指出统一依赖权威与利益网络而非制度一致。"},{"id":"historiography-institutes-republic","title":"民国史学机构：史语所与中研院","date":"2027-01-04","tags":["民国","史语所","学术制度"],"summary":"以1928年史语所成立为线索，讨论现代研究所如何以经费、设备、刊物与田野许可改变史学生产；梳理傅斯年的办所方针、安阳发掘、方言与人类学调查、集刊与学术网络，并辨析史料即史学被简化的过程，以及战时迁徙与机构化对学术自主性的双重影响，指出制度既扩展了学术能力也带来新的约束。"},{"id":"oracle-discovery-doubt-antiquity","title":"甲骨发现与疑古思潮","date":"2027-01-03","tags":["甲骨","疑古","史料"],"summary":"从1899年甲骨进入学者视野说起，梳理刘鹗、罗振玉的搜集与王国维的二重证据法，分析甲骨作为同时代占卜记录为何能成为证据、又受限于王室档案的性质；讨论董作宾的断代、辨伪与缀合等技术工作，说明疑古与考古在材料标准上的互补与冲突，并指出证据标准的变化比结论本身更持久。"},{"id":"dunhuang-manuscripts-dispersal","title":"敦煌文书的流散与整理","date":"2027-01-02","tags":["敦煌","文书","学术史"],"summary":"从1900年藏经洞的发现、斯坦因与伯希和的攫取讲起，梳理敦煌文书的分藏格局、编号体系与中国学者的编目刊布历程；分析俗文学与寺院经济文书的史料价值及其证据边界，讨论「流散」带来的研究便利与伦理困境，以及数字化时代缀合与共享的可能；藏经洞封闭原因与伪卷问题仍是未决之处。"},{"id":"cartography-age-of-discovery","title":"地图与大航海：知识的边界","date":"2027-01-01","tags":["地图","大航海","知识史"],"summary":"从波特兰海图、托勒密地理学与中世纪世界地图三条传统入手，考察大航海时代海图如何把局部精确与整体空白结合起来；分析墨卡托投影、条约线与殖民地图的权力逻辑，以及耶稣会士入华与《坤舆万国全图》引发的观念冲突，讨论地图作为知识载体与领土宣称工具的双重性质，兼及投影失真与底图来源的辨析。"},{"id":"cold-war-social-sciences","title":"冷战与历史学的社会科学化","date":"2026-12-31","tags":["冷战","社会科学","史学史"],"summary":"从战后区域研究与基金会的资助结构入手，考察现代化理论、计量史学与年鉴学派如何共同推动史学的社会科学化；分析冷战经费如何塑造研究议程，以及教区登记、税收册等数据的生成过程为何本身即构成史料学难题；最后讨论叙事复兴的批评与解释、理解之间的持久张力，以及这一张力在冷战结束后的延续。"},{"id":"medieval-towns-communes","title":"中世纪的城市与公社","date":"2026-12-30","tags":["中世纪","城市","公社"],"summary":"从十一世纪的城市复兴入手，比较意大利公社的执政官制与北方以誓约结成的市民团体，考察特许状如何把特权落成文字、行会与议事会如何组织市政、城市空间如何承载公共秩序；分析城市在领主与王权之间的博弈位置及自治的实际限度，并讨论特许状文本、行会章程与公社起源叙述的史料问题，兼及自治的代价。"},{"id":"edo-bakuhan-system","title":"日本江户的幕藩体制与身份","date":"2026-12-29","tags":["日本","江户","身份"],"summary":"从德川幕府的领国结构与石高制入手，分析参勤交代如何同时实现政治控制与交通消费，考察村请制、株仲间与町自治的运作方式；讨论士农工商作为规范框架与实际身份流动之间的落差，并从财政、身份与分散治理三个层面解释幕末体制的解体，兼及株仲间政策的反复所反映的财政困境与身份秩序的规范性质。"},{"id":"goguryeo-beacon-warning","title":"烽燧与斥候：高句丽的情报体系","date":"2027-01-08","tags":["高句丽","军事","情报"],"summary":"高句丽的预警靠山城、烽燧与斥候三层目视网络，不依赖文书，受地形、视距与值守人力制约。烽燧只传警报与来向，斥候补足细节。唐方史书以「大骇，城邑皆闭门自守」概括贞观十九年渡辽后的反应，能证明震动与收缩防御，却无法还原传递流程。唐军以多路并进与张俭前锋制造判断困难。结论是山城的防御强点同时是情报弱点，节点固定便易被绕过。"},{"id":"tang-warhorse-administration","title":"战马从哪来：唐军征辽的马政与损耗","date":"2027-01-09","tags":["唐代","马政","后勤"],"summary":"唐军征辽的约束在畜力而非兵员。战马出自陇右监牧、蕃部贡马与边境市马，监牧数字含驿马驮马，不能直当坐骑。数千里行军的损耗来自负重、严寒与草料短缺，运草又需驮畜，驮畜远超战马且常先垮。骑兵多用于侦察、追击与断粮道，攻坚仍靠步兵。马匹存量决定出征规模，损耗决定能走多远。"},{"id":"tang-ritual-military-campaign","title":"类祭、告庙与献俘：唐丽战争中的军礼","date":"2027-01-10","tags":["唐代","军礼","礼仪"],"summary":"军礼由出征前的类祭、告庙、授钺与班师后的献俘、饮至、策勋构成，分别诉诸天、祖与专征之权，并把战功换算为勋官爵位。其功能在宣示正当性、分配荣誉与安抚将士。安市不克而班师，诏书却把撤退写成体恤士卒。礼典所载是标准程式，实际执行常有增减；军礼不在指导战争，而在收束战争。"},{"id":"tang-ando-garrison","title":"安东都护府的驻军与轮换","date":"2027-01-11","tags":["唐代","安东都护府","驻防"],"summary":"平壤陷落后，安东都护府以羁縻外壳承担军事占领，兵力来自府兵番上、募兵与蕃兵。治所初设平壤以宣示取代，却受河北道转运与登州海路制约；仪凤年间迁辽东故城、再迁新城，渤海兴起后侨治，肃宗时名存实亡。占领成本在兵力、粮运与政治三层面，轮换本身亦耗运力。粮道一断，都护府只剩名义。"},{"id":"goguryeo-border-markets","title":"互市与走私：战时边境贸易","date":"2027-01-12","tags":["高句丽","边境","贸易"],"summary":"唐与高句丽、靺鞨的边境贸易以互市监为外壳，马匹、铁器属禁物，粮食与盐视时局松紧。禁令依托关津律条与过所公验，执行却靠边吏，边境线长而漏洞常在。战时互市停摆，交易转入私下，边吏、商人与部落首领结成灰色网络，羁縻州与营州充当中介。禁运越严，走私利润越高，边境贸易不只是经济行为。"},{"id":"war-women-households","title":"征发之后：战争中的妇女与家庭","date":"2027-01-13","tags":["唐代","社会史","家庭"],"summary":"从差科簿上的征行注记入手，梳理丁男出征后租调不免、庸仅名义放免的制度缺口，以及留守妇女以纺织完调、以借贷周转、以诉讼护产的具体应对。再借判文与墓志讨论户内支配权向留守者转移，指出赐帛与放免多为一次性补偿，战争成本终在家庭内部被逐年消化，而这一层很少进入战报，账面数字与家庭实感之间始终有一段距离。"},{"id":"tang-river-crossing","title":"渡辽水：浮桥、冰面与江河作战","date":"2027-01-14","tags":["唐代","辽水","作战"],"summary":"辽水与浿水的渡口受季节约束，浮桥可拆可移，阎立德布土成桥则适于窄浅河段，冰封期又提供一座会自行消失的桥。撤桥以坚士卒之心的记载带有叙事加工，其真实意义在后勤：桥是补给线的咽喉。河流因此不是边界，而是决定战争时间表的节奏，开冻与封冻都比将帅的意志更有力，将帅能做的只是顺应与等待。"},{"id":"pyeongyang-urban-defence","title":"平壤城的形制与防御","date":"2027-01-15","tags":["高句丽","平壤","城市"],"summary":"平壤由宫城、外城与山城叠合而成，城墙形制不一，水源与仓储是围城中的两个变量。唐军以云梯、冲车、砲与地道并攻，守方以滚木、听瓮与夜袭应对；661年因大雪粮尽而退，668年城破则与粮竭、上层分裂及内应相关。攻方须同时解决墙、山与江三个问题，缺一则围城必拖长，三者之中最难的是断江上之路。"},{"id":"goguryeo-command-ranks","title":"褥萨、处闾与佰位：高句丽的军制等级","date":"2027-01-16","tags":["高句丽","军制","官制"],"summary":"中原史籍所记十二级官阶，是史家整理的产物，与军职并非一一对应。褥萨军政合一，主一城；处闾的层级仍有讨论；佰位与队嵌在城的动员体系里，五部与诸城的关系层叠而松散。军制因此是城的联合而非军的编制，长于守而短于决战，战略主动权易落对手之手，此后历次战事中反复显现，攻守之势长期由对手掌握。"},{"id":"postwar-tax-registers-ando","title":"战后的户籍与赋税：安东都护府的治理账本","date":"2027-01-17","tags":["唐代","安东都护府","赋税"],"summary":"安东都护府下辖九都督府、四十二州、百县，以酋渠为都督刺史而与华人参理，形成双轨。编户受制于遗民逃亡、豪族隐户与基层薄弱，赋税多以轻税、土贡过渡，收入难抵驻军转运之费。治所内迁说明控制收缩；能收上税的地方才叫领土，账本比战报更诚实，而两者的差额正是占领的真实成本。"},{"id":"surrender-policy-tang","title":"受降的规矩：唐军对降卒与降将的处置","date":"2027-02-06","tags":["唐丽战争","军事","制度"],"summary":"从驻跸山三万六千八百名降卒的处置入手，梳理唐军受降的程序与分类逻辑：简出酋长三千五百人迁往内地，余众纵归，战利品另行分配。比较白岩城、安市城下与平壤三次处置，指出宽严取决于粮运能力、地理可达与政治目标，而非君主德性，并检讨降卒数字与唐方记载的局限，说明受降是约束条件下的解。"},{"id":"goguryeo-horse-supply","title":"高句丽的马匹与骑兵补给","date":"2027-02-05","tags":["唐丽战争","军事","马政"],"summary":"高句丽的马来自本地牧养、掠夺与互市，山地地形限制了牧场的连片与马群规模，马因此分散于城主与贵族之手，马政也更接近贵族分有制；壁画中的马具与甲骑具装只能证明形制、不能证明编制。驻跸山缴获五万匹马的数字需打折扣，骑兵在山地城防体系中更多承担突击、追击与传信，而不是草原式的大集团冲锋。"},{"id":"tang-archery-crossbow","title":"弓弩与远程火力：唐军的射术与装备","date":"2027-02-04","tags":["唐丽战争","军事","装备"],"summary":"从唐军弓弩的制式与箭矢补给入手，讨论攻城时远程火力的实际作用：弓弩负责压制城头、掩护器械接近，火弩焚楼依赖风向与木构目标，对石墙无效。射程与威力的具体数字多属推测，远程火力能改变攻城的节奏，却不能单独决定一座城的下落，安市城久攻不下即为例证，攻城最终仍要靠围困与断粮。"},{"id":"goguryeo-city-residents-mobilization","title":"城民与战时征发：高句丽的动员基础","date":"2027-02-03","tags":["唐丽战争","社会","动员"],"summary":"高句丽的城是军政单元，城民承担兵役、粮秣与劳役，山城的储粮与烽燧联络支撑长期防御。唐军以攻取、迁民、毁城三步拆解防线，六四五年与六六八年两次迁民使故地人口骤减，城墙虽在而防线失效；城的实质是人口，不是墙体，安东都护府的困境正源于此，这也是唐在故地设治难以持久的原因。"},{"id":"tang-navy-ports-shipyards","title":"船场与港口：唐军海运的基地","date":"2027-02-02","tags":["唐丽战争","后勤","水军"],"summary":"从阎立德在洪、饶、江三州造船四百艘入手，梳理唐军海运的造船、港口、粮仓与季节窗口，指出莱州、登州的卸载与仓储能力决定远征规模。四百艘的实数与艘的载重均难确证，海运的瓶颈不在船，而在港口、季节与回程安排，这限制了唐军历次远征的时间表，也使海运始终只是陆路的补充。"},{"id":"war-epidemics-expedition","title":"军中疫病：远征的另一场战争","date":"2027-02-01","tags":["唐丽战争","医疗","人口"],"summary":"贞观十九年唐军围攻安市不下而班师，诏书只提早寒与粮尽，营中的疾病被略过。本文从饮水、营地、补给与季节四条线索拆解疫病如何在大兵团中放大，指出「士卒多死」一类记载能证明疾病发生，却无法支撑病死率估算；疫病更多是压缩了继续围城的选择空间，而非单独的败因；把它放回后勤条件中，才看得出它的分量。"},{"id":"tang-battlefield-signals","title":"旗鼓号令：战场上的通信与指挥","date":"2027-01-31","tags":["唐丽战争","军事","指挥"],"summary":"唐军在辽东的指挥依赖旗、鼓、角、金、烽火与传令骑兵，每一层都有物理上限。本文估算大兵团在山谷地形中的有效指挥半径，说明为何实战多取分道而进、期会而战的形式，并把「鼓噪而进」一类套语还原为仪式化书写，指出信号失灵造成的战机丧失常被记成个别将领的过失；指挥半径的收缩，往往比兵力的差距更能解释战场上的迟疑。"},{"id":"goguryeo-divination-war","title":"占卜与祭祀：高句丽的战前仪式","date":"2027-01-30","tags":["唐丽战争","宗教","仪式"],"summary":"高句丽的祭天、卜吉与择日，在汉文史料中只剩几条风俗条目。本文讨论仪式的时间同步、等级确认与情绪动员三层功能，指出卜的结果可被重新解释，仪式提供的是程序合法性而非决策本身，并检讨东夷传的分类叙述与《三国史记》晚出追述各自的局限。仪式因此既是动员，也是史料框架的投影，这种投影比仪式本身更接近史料的真实状态。"},{"id":"tang-war-decision-process","title":"唐廷如何决定出兵：宰相、制敕与朝议","date":"2027-01-29","tags":["唐丽战争","制度","决策"],"summary":"贞观十八年的出兵决定常被写成皇帝一人之志，实际要经过宰相议政、中书起草、门下审覆与尚书执行。本文以人事任命与制敕措辞为线索，说明军事框架先于诏书宣示，谏诤被纳入论证程序而非改变结论；并检讨《资治通鉴》的对话体叙事与诏书的宣示性质；决策的门槛与政治气候，决定了这套程序的实际重量。"},{"id":"hebei-regional-economy-war","title":"河北道与征辽：区域经济的负担","date":"2027-01-28","tags":["唐丽战争","经济","区域"],"summary":"征辽的粮草来自河北道数十州，永济渠与官道构成运输网络，转运损耗、徭役与造船征马层层落在民户。本文分析负担如何被制度化并沉淀为仓储、船厂与边军，指出这一过程使幽州一带军事化加深，但安史之乱的成因不能简单归到征辽一事；区域负担的转移与制度沉淀，比总量数字更值得追问，也更能解释地方的长期变化。"},{"id":"postwar-liaodong-prefectures","title":"战后辽东的州县重建与侨置","date":"2027-01-27","tags":["唐丽战争","制度","行政"],"summary":"总章元年唐在平壤设安东都护府，九府四十二州的名号多取自高句丽旧城，刺史都督则授降附酋帅。本文把名号、治所与人口分开考察：民户被大批内迁，建制随之侨置河北，安东逐渐空壳化。地理志的名录、墓志与城址各能证明一段，却不能互相替代；所谓州县重建，一半是治理，一半是投影。"},{"id":"tang-siege-engineering","title":"攻城工兵：土山、地道与填壕","date":"2027-01-26","tags":["唐丽战争","军事","工程"],"summary":"唐军攻辽东城，填壕、筑土山、掘地道、推撞车，工序环环相扣，全靠人力与时间堆出来。本文拆解工程顺序与后勤消耗，说明山城地形如何抵消工兵优势：坡陡则土山难高，岩层则地道难进。战报里的克之拔之掩盖了伤亡与工期，考古城址能证防御设计，却证不了具体战法。工程能决定一城得失，决定不了战争结束。"},{"id":"war-weather-omens","title":"占候与天时：行军中的气象判断","date":"2027-01-25","tags":["唐丽战争","军事","气候"],"summary":"贞观十九年班师诏书把撤退归因于辽左早寒与粮尽，天时从此成为固定修辞。本文分辨两套知识：太史局的占候提供正当性，向导与老卒的经验提供可行性；辽泽泥淖与季风航期才是真正的约束。天文志的占辞写在事后，诏书省略不利，两者都不能当作行军日志。天时既是约束，也是卸责的语言。"},{"id":"prisoners-of-war-tang","title":"战俘的命运：献俘、没官与安置","date":"2027-01-24","tags":["唐丽战争","社会","战俘"],"summary":"献俘、没官、配流与再利用，是唐处理高句丽战俘的四条基本路径，按身份分层：王与贵族入朝授官，工匠乐工编入官署，普通丁口没为奴婢或配流。本文分析三种用途彼此冲突，指出献俘的数字是修辞，律文与墓志各自只能证明制度与精英。战俘后裔渐融于唐，踪迹留在墓志边角与户籍残卷里。"},{"id":"silla-role-in-war","title":"新罗的参战：出兵、粮运与情报","date":"2027-01-23","tags":["唐丽战争","新罗","同盟"],"summary":"新罗借唐之力灭百济、高句丽，出兵、运粮、供情报，却不承担决战。本文以成本分担与收益分配解释同盟的限度：唐求羁縻秩序，新罗求实土，胜利之后算法不同，遂有唐罗战争。并检讨《三国史记》的新罗本位、《日本书纪》的倭方视角与唐史的责备措辞，指出反目是结构性的，而非背信。"},{"id":"tang-field-camps","title":"营寨与野战工事","date":"2027-01-22","tags":["唐丽战争","军事","工事"],"summary":"从贞观十九年安市城下的营地入手，梳理唐军宿营的选址、壕栅构造、内部分区与昼夜警戒，说明营寨的强度不在木栅厚薄，而在信息传递与结营纪律；并结合高句丽山城突袭的战法，分析遭袭风险与夜惊处置。末段检讨正史与兵书材料的限制：营制细节多不载，兵书是理论汇总，不能直接当作辽东前线的实录。"},{"id":"goguryeo-iron-industry","title":"冶铁与兵器生产：高句丽的手工业","date":"2027-01-21","tags":["唐丽战争","考古","手工业"],"summary":"以集安出土的铁甲片与史载铁甲万领对读，梳理高句丽铁器的类别、冶铁遗存的分布与块炼铁、生铁铸造并存的工艺，讨论城邑制下分散的手工业组织如何支撑长期守城。同时指出考古证据的支持与限制：能证明本地生产，却难以估算产量与分配；兵器自给说因此需要加上限定条件，不能推及所有装备。"},{"id":"military-documents-front","title":"前线文书：军令、牒文与奏报","date":"2027-01-20","tags":["唐丽战争","文书","行政"],"summary":"从行军元帅府的文书班子入手，梳理诏敕、军令、牒符、露布与捷报的类别与驿传路径，分析旬月往返的时间差如何迫使制度给前线留出便宜从事的空间，又通过事后追认收回权力。末段检讨露布的修辞如何经实录、国史层层放大数字，塑造了今日所知的战争叙事，并指出文书的分类本身就在筛选记忆。"},{"id":"tang-buddhism-war-prayer","title":"祈战与随军僧：佛教与战争","date":"2027-01-19","tags":["唐丽战争","宗教","佛教"],"summary":"从幽州悯忠寺的建立入手，考察寺院祈战、斋僧与阵亡超度在唐丽战争中的实际运作，分析国家与僧团之间的交换：田产、免役与度僧名额换取仪式服务与动员正当性。并以平壤僧人信诚内应一事为个案，讨论僧团在城中的位置，同时指出佛教史料大多后出、带有护教立场、数字常被夸大的局限。"},{"id":"war-in-tang-poetry-epitaphs","title":"诗与墓志中的唐丽战争","date":"2027-01-18","tags":["唐丽战争","文学","记忆"],"summary":"以唐太宗《伤辽东战亡》与洛阳出土墓志对读，考察从征人诗的传统与帝王视角，分析墓志体例如何把从军经历压缩成套语与资历，进而讨论战争如何被文学化与家族化。末段检讨墓志书写中的沉默：它能证明制度与观念，却不能还原战役细节与士兵心态；诗与墓志合起来，才是较为完整的记忆装置。"}];

const books = [{"id":"fernel-braudel","title":"地中海与菲利普二世时代的地中海世界","author":"费尔南·布罗代尔","rating":5,"desc":"年鉴学派第二代领军人物的代表作。布罗代尔将历史分为三种时间层次：长时段的自然环境史、中时段的社会经济史、短时段的政治事件史。这种分层方法深刻地改变了我们理解历史的方式。","cover":""},{"id":"kun-huantian","title":"历史研究","author":"阿诺德·汤因比","rating":4,"desc":"汤因比以文明为单位考察历史，提出了挑战—应战的文明兴衰模式。虽然其宏观理论框架在今天看来有不少可商榷之处，但其视野之开阔、材料之丰富，仍是不可绕过的经典。","cover":""},{"id":"qianmu","title":"国史大纲","author":"钱穆","rating":5,"desc":"在民族危亡之际写就的中国通史。钱穆以“温情与敬意”的态度审视本国历史，在考据与义理之间取得了令人叹服的平衡。其“中国历史是一种和平的文化演进”的论断，至今仍有启发性。","cover":""},{"id":"yu-yingshi","title":"士与中国文化","author":"余英时","rating":5,"desc":"余英时对“士”这一阶层的系统研究。从先秦到清代，他梳理了士人如何在不同的政治环境下调整自己的角色与理想。书中对宋代士大夫的分析尤其精彩。","cover":""},{"id":"wanli-15nian","title":"万历十五年","author":"黄仁宇","rating":5,"desc":"以万历十五年为横截面，通过张居正、申时行、戚继光、李贽等人物的命运，展现明代政治运作的内在逻辑。黄仁宇的“大历史”观在此书中得到了完美的实践——从细微处入手，揭示宏大历史的结构性困境。","cover":""},{"id":"what-is-history","title":"历史是什么？","author":"爱德华·卡尔","rating":4,"desc":"卡尔在1961年剑桥讲座中提出的问题至今仍是每一个历史学入门者无法回避的起点。他关于“历史是历史学家与事实之间连续不断的互动过程”的论断，在客观主义与相对主义之间为历史研究开辟了一条辩证的中道。","cover":""},{"id":"modern-china","title":"追寻现代中国","author":"史景迁","rating":5,"desc":"史景迁以叙事史学的笔法，将1600年以来的中国历史娓娓道来。作为西方中国史研究的代表人物，他以“局外人”的视角对中国的现代化历程进行了既富同情心又不失批判力的审视。书中对明清更替与近代转型的叙述尤为精彩。","cover":""},{"id":"autumn-middle-ages","title":"中世纪的秋天","author":"约翰·赫伊津哈","rating":4,"desc":"文化史领域的传世经典。赫伊津哈以十四至十五世纪的法国与尼德兰为中心，描绘了中世纪晚期文化的全景图卷。他关于“游戏”与“仪式”的文化分析视角，对后来的文化史与心态史研究产生了深远的影响。","cover":""},{"id":"history-three-keys","title":"历史三调：作为事件、经历和神话的义和团","author":"柯文","rating":5,"desc":"柯文以义和团运动为个案，精辟地分析了历史认知的三个层次：作为客观事件的历史、作为亲历者经验的历史、作为后设建构的神话。这本书不仅是对义和团的研究，更是对“历史认识论”的一次深刻探索。","cover":""},{"id":"soulstealers","title":"叫魂：1768年中国妖术大恐慌","author":"孔飞力","rating":5,"desc":"“孔飞力以1768年席卷中国的“叫魂”恐慌为切入点，展开了一幅关于清代政治、社会与文化的全景图。书中不仅细致重建了这场荒诞而可怖的民间恐慌如何从一个省份蔓延至整个帝国，更揭示了乾隆盛世表象下潜伏的政治焦虑与制度困境。孔飞力将微观事件与宏观分析完美结合，堪称新文化史与政治史融合的典范之作。”","cover":""},{"id":"orientalism","title":"东方学","author":"爱德华·萨义德","rating":5,"desc":"“萨义德的《东方学》是二十世纪后半叶最具冲击力的学术著作之一。他揭示了西方关于“东方”的知识生产如何与殖民权力纠缠在一起——所谓中立的学术研究，实际上参与了对东方的想象、定型与支配。这本书对于任何在非西方世界从事历史研究的人来说，都是一面不得不正视的镜子：我们使用的概念工具、理论框架，是否本身就是某种权力结构的产物？”","cover":""},{"id":"zhaizi-zhongguo","title":"宅兹中国：重建有关“中国”的历史论述","author":"葛兆光","rating":5,"desc":"“葛兆光在这本书中追问一个看似简单却至关重要的问题：什么是‘中国’？他从观念史的角度梳理了‘中国’作为一个政治与文化共同体的自我认知如何在不同时代被建构和调整。”","cover":""},{"id":"wangshi-zhi-si","title":"王氏之死：大历史背后的小人物命运","author":"史景迁 (Jonathan Spence)","rating":4,"desc":"“史景迁以清初山东郯城一个普通农妇王氏的死亡案件为线索，重构了17世纪中国底层社会的日常生活图景。通过地方志、司法档案和笔记小说，他让那些被正史遗忘的小人物重新获得了讲述自己故事的机会。”","cover":""},{"id":"montaillou","title":"蒙塔尤","author":"埃马纽埃尔·勒华拉杜里","rating":5,"desc":"年鉴学派微观史经典。勒华拉杜里利用宗教裁判所的审讯记录，重建了十四世纪法国南部一个比利牛斯山小村庄几乎全部的生活细节--信仰、私情、流言、嫉妒。它证明了最宏大的历史可以藏在最微小的角落里。","cover":""},{"id":"great-divergence","title":"大分流","author":"彭慕兰","rating":5,"desc":"全球经济史的里程碑之作。彭慕兰追问：为什么欧洲在十九世纪走向了工业化，而同为发达地区的江南却没有？他的回答打破了欧洲中心论的固有叙事，将煤炭、殖民地与生态约束推到了历史的前台。","cover":""},{"id":"empire-of-cotton","title":"棉花帝国：一部全球史","author":"斯文·贝克特","rating":5,"desc":"贝克特以棉花为线索，串联起奴隶贸易、工业革命与全球资本主义。一部商品的全球史，也是一部被编织进棉花纤维中的权力与暴力史。","cover":""},{"id":"zuzong-zhifa","title":"祖宗之法：北宋前期政治述略","author":"邓小南","rating":5,"desc":"邓小南对宋代政治史的经典研究。祖宗之法并非成文法典，而是在实践中不断被诠释、被建构的政治传统。这本书为理解中国古代政治文化的运作逻辑提供了一个精微的范本。","cover":""},{"id":"silk-roads","title":"丝绸之路：一部全新的世界史","author":"彼得·弗兰科潘","rating":4,"desc":"弗兰科潘将丝绸之路重新置于世界史的中心。从中亚的绿洲城邦到两大帝国的博弈，他提醒我们：连接东西方的通道从未真正中断，而今天的全球格局在某种程度上仍在重复古老的地理逻辑。","cover":""},{"id":"steppe-empire","title":"草原帝国","author":"勒内·格鲁塞","rating":5,"desc":"纵览欧亚草原游牧民族三千年兴衰的经典通史。从斯基泰、匈奴到突厥、蒙古，格鲁塞以法国式的开阔视野，勾勒出草原文明与农耕文明相互塑造的宏大图景。他既写草原帝国的军事征服，也写丝绸之路上的商业往来与文化传播，让欧亚大陆的历史因草原而连为一体。对于理解北族王朝与中原的关系、蒙古帝国的世界性，这本书是绕不开的起点。","cover":""},{"id":"collapse-of-celestial-empire","title":"天朝的崩溃：鸦片战争再研究","author":"茅海建","rating":5,"desc":"以严格的史料考据重新审视鸦片战争。茅海建不满足于落后挨打的简单叙事，而是深入清军的武器装备、兵力部署、指挥系统与决策机制，追问清王朝的防御体系为何如此脆弱。他提出战争失败的关键不仅在技术差距，更在于制度性的战略失能。书中对琦善、林则徐等人物功过的重新评价，冲击了传统叙事，是近代史研究的方法论典范。","cover":""},{"id":"eastern-jin-politics","title":"东晋门阀政治","author":"田余庆","rating":5,"desc":"中国中古政治史研究的高峰之作。田余庆提出，东晋的“门阀政治”实际上是皇权政治的变态——士族与皇权之间不是简单的从属，而是“皇帝垂拱、士族当权”的权力分享格局。从琅琊王氏、颍川庾氏、龙亢桓氏到陈郡谢氏，他精细梳理了各大士族与皇权博弈的兴衰脉络。史料之扎实与史识之深刻，使其成为研究魏晋南北朝史不可绕过的基础读本。","cover":""},{"id":"discovering-history-in-china","title":"在中国发现历史：中国中心观在美国的兴起","author":"柯文（Paul A. Cohen）","rating":5,"desc":"美国中国学的方法论反思之作。柯文逐一检讨「冲击—回应」「传统—近代」「帝国主义」三种解释框架，指出它们都以西方为尺度裁剪中国经验，进而提出「中国中心观」：从中国自身的社会结构、问题意识与内部脉络出发理解中国的变化。书中对二十世纪七十年代以前美国中国史研究的梳理，至今仍是入门这一领域的地图。","cover":""},{"id":"tang-political-history","title":"唐代政治史述论稿","author":"陈寅恪","rating":5,"desc":"以「关陇集团」与「关中本位政策」为线索，重述唐代政治的三次转折：李唐创业与关陇集团的兴衰、武周革命与科举寒门的上升、安史之乱后河北藩镇的半独立。陈寅恪把族属、地域、婚姻与仕进四条线索交织论证，使制度史与政治史合为一体。全书篇幅不大，却长期是唐史研究的枢纽，其结论至今仍在被检验与修正。","cover":""},{"id":"imagined-communities","title":"想象的共同体：民族主义的起源与散布","author":"本尼迪克特·安德森","rating":5,"desc":"把民族视为「想象的政治共同体」的经典论述。安德森从印刷资本主义、方言的崛起、「空洞而同质的时间」与殖民地行政体系出发，解释民族主义为何先在美洲出现、再经欧洲与东南亚扩散。书中关于人口普查、地图与博物馆的讨论，对理解近代国家如何塑造认同尤其有用。","cover":""},{"id":"age-of-extremes","title":"极端的年代：1914—1991","author":"艾瑞克·霍布斯鲍姆","rating":5,"desc":"「年代四部曲」的终卷，把二十世纪写成「短的二十世纪」：自一战至苏联解体，历经灾难时期、黄金时代与危机年代。霍布斯鲍姆以马克思主义史学家的眼光处理经济、政治与文化的整体变动，也坦率记录自己对时代的判断与误判。它既是二十世纪史的综览，也是一份知识分子的见证。","cover":""},{"id":"wang-fansen-power","title":"权力的毛细管作用：清代的思想、学术与心态","author":"王汎森","rating":4,"desc":"讨论清代皇权与士人思想之间的微妙关系。王汎森以「权力的毛细管作用」形容政治权力如何渗入日常生活、学术趣味与自我审查：从文字狱、禁书运动，到理学与考据学的消长，看思想如何被塑造、又如何自我设限。对理解清代学术转向与士人心态的压抑机制，颇多启发。","cover":""},{"id":"cheese-and-worms","title":"奶酪与蛆虫：一个16世纪磨坊主的宇宙","author":"卡洛·金兹堡","rating":5,"desc":"从一份宗教裁判所审讯记录出发，重建十六世纪意大利磨坊主梅诺基奥的世界观。他把宇宙想成一块正在发酵的奶酪，因而被控异端。微观史学的开山之作，示范了如何让一个无名者开口说话，也提醒读者：审讯记录里的声音，始终经过权力的转述。","cover":""},{"id":"return-of-martin-guerre","title":"马丁·盖尔归来","author":"埃马纽埃尔·勒华拉杜里","rating":5,"desc":"十六世纪法国乡村的一桩冒名顶替案：离家多年的马丁·盖尔归来，妻子认下了他，直到真正的丈夫出现。作者把司法档案、土地契约与口述传统编织成一部历史人类学杰作，追问身份、记忆与社群如何彼此确认。","cover":""},{"id":"metahistory","title":"元史学：十九世纪欧洲的历史想象","author":"海登·怀特","rating":5,"desc":"以情节化、形式论证与意识形态三个层次，分析十九世纪四位史学大家的文本，提出历史书写在结构上近于文学建构。此书是后现代史学理论的地基，也是理解「叙事转向」绕不开的一本书，读来未必轻松，但概念工具极有用。","cover":""},{"id":"the-idea-of-history","title":"历史的观念","author":"R. G. 柯林武德","rating":5,"desc":"从希腊到近代的史学思想史，主张一切历史都是思想史，史家应在自己心中重演过去的思想。二十世纪最重要的史学理论著作之一，对「史料是什么」「历史知识如何可能」的追问，至今仍在被引用与争论。","cover":""},{"id":"apologie-pour-lhistoire","title":"为历史学辩护","author":"马克·布洛赫","rating":5,"desc":"布洛赫在抵抗运动期间未完成的遗稿，谈史料批判、比较方法与史学的技艺。篇幅短小，分量极重，被视作年鉴学派的方法宣言；「历史学家的技艺」一节尤其值得反复读。","cover":""},{"id":"the-invention-of-tradition","title":"传统的发明","author":"埃里克·霍布斯鲍姆、特伦斯·兰格","rating":5,"desc":"苏格兰格子呢、王室仪式与民族国家的庆典，一组个案论证「传统」常常是近代的创造。民族主义研究必读，也提醒读史者：看起来最古老的习俗，可能只有一百多年的历史。","cover":""},{"id":"whig-interpretation","title":"辉格党式的历史阐释","author":"赫伯特·巴特菲尔德","rating":4,"desc":"批评以当下价值审判过去、把历史写成通往现在的进步直线。一部薄书改变了英语世界史学写作的自觉；对今天读史仍有提醒：不要急着替古人排座次。","cover":""},{"id":"southeast-asia-trade","title":"东南亚的贸易时代：1450—1680","author":"安东尼·瑞德","rating":5,"desc":"以季风、港口与商品为线索，重建东南亚贸易时代的繁荣与危机：香料、白银、华人移民与港口城市。把区域史放进全球史框架的典范之作，可与印度洋贸易的著作对读。","cover":""},{"id":"law-and-society-china","title":"中国法律与中国社会","author":"瞿同祖","rating":5,"desc":"从家族、阶级与宗教三个切口，分析传统中国法律与社会结构的关系：礼与法的分工、身份差等在刑罚中的体现。用社会学眼光读法制史的经典，篇幅不大，问题意识极清晰。","cover":""},{"id":"chinese-gentry","title":"中国绅士：关于其在19世纪中国社会中作用的研究","author":"张仲礼","rating":4,"desc":"以地方志与绅士名录为数据，量化十九世纪绅士的构成、收入来源与地方功能，讨论他们在赈济、教育、公共工程与纠纷调解中的角色。中国社会史量化研究的早期范例，方法与结论都值得讨论。","cover":""},{"id":"shang-civilization","title":"商文明","author":"张光直","rating":5,"desc":"以考古材料重建商代的国家形态、都城布局、手工业与祭祀体系，提出萨满式宇宙观与权力获取的假说；材料与推论分得很清，是英语世界最系统的商代综论。","cover":""},{"id":"western-zhou-history","title":"西周史","author":"许倬云","rating":5,"desc":"以文献、青铜器铭文与考古发现互证，讨论西周的封建、宗法与官僚化进程，兼及族群关系与礼制；制度分析与人事叙述并重，是西周史入门与进阶都好用的综论。","cover":""},{"id":"ladder-of-success","title":"明清社会史论","author":"何炳棣","rating":5,"desc":"以登科录、朱卷与家谱统计明清社会流动，讨论科举、财富、家族与地域的关系，提出可量化的流动率框架；结论后来屡被修正，方法与问题意识仍是计量社会史的开端。","cover":""},{"id":"boci-tongzuan","title":"卜辞通纂","author":"郭沫若","rating":4,"desc":"甲骨卜辞的分类纂辑与考释，按祭祀、征伐、田猎等内容分组编排，附拓本与释文；既可当工具书检索辞例，也能看到早期甲骨学在材料有限时的推断方式。","cover":""},{"id":"guantang-jilin","title":"观堂集林","author":"王国维","rating":5,"desc":"王国维的学术论文集，涵盖甲骨、金文、古史、简牍、文学与戏曲，多为由小学入手的考证文章；二重证据法的示范之作，读其单篇可见方法如何落到具体问题。","cover":""},{"id":"ancient-china-archaeology","title":"古代中国考古学","author":"张光直","rating":5,"desc":"从旧石器时代到商周的考古通论，注重聚落形态、区域互动与技术变迁，配有大量线图与遗址分布；叙述框架偏人类学，是理解中国史前与早期文明的可靠导论。","cover":""},{"id":"archaeology-six-lectures","title":"考古学专题六讲","author":"张光直","rating":4,"desc":"六次讲演整理成的理论与方法小书，讨论聚落考古、区系类型、文化因素分析与解释框架；篇幅短、问题意识清楚，适合作为进入考古学方法论的第一个台阶。","cover":""},{"id":"pre-qin-history","title":"先秦史","author":"吕思勉","rating":4,"desc":"以制度与史事并重的先秦通史，取材遍及经子与出土材料，断制谨慎而对旧说多有辨析；读来可见传统史学向现代转型时的写法、关怀与限度。","cover":""},{"id":"tang-historical-geography","title":"唐代历史地理研究","author":"史念海","rating":5,"desc":"以历史地理学方法考察唐代的疆域、政区、交通与河湖变迁，兼及长安、洛阳的城市布局，是理解唐代空间格局的基础性研究。","cover":""},{"id":"historical-atlas-china","title":"中国历史地图集","author":"谭其骧","rating":5,"desc":"八册本历代疆域与政区地图集，上起原始社会下迄清季，考订严谨、图幅清晰，附地名索引；查证政区沿革与古今地名对照的基准工具书，读史时随手可查。","cover":""},{"id":"haotaiwang-bei-research","title":"好太王碑研究","author":"王健群","rating":4,"desc":"以好太王碑的拓本与实地考察为基础，逐段校读碑文，讨论立碑年代、碑文所述征伐的对象与路线，是国内研究该碑的奠基性著作，适合与《三国史记》对读。","cover":""},{"id":"goguryeo-archaeology","title":"高句丽考古","author":"魏存成","rating":5,"desc":"系统梳理高句丽的山城、墓葬、壁画与城址布局，把文献记载与考古材料对照，是了解高句丽物质文化与社会结构最实用的入门书，配图与遗址清单都好用。","cover":""},{"id":"korean-history-new","title":"韩国史新论","author":"李基白","rating":5,"desc":"韩国史学界的通史名著，以社会结构与政治变迁为线索梳理从古代到近代的半岛历史，对高句丽、百济、新罗的叙述简明而有判断。","cover":""},{"id":"tang-goguryeo-baekje-migrants","title":"唐代高丽百济移民研究","author":"拜根兴","rating":4,"desc":"以墓志与传世文献互证，考察高句丽、百济亡国后迁入唐境的王室、将领与民众的安置、仕宦与身份变化，是唐丽关系研究的新著。","cover":""},{"id":"east-asian-world-formation","title":"东亚世界形成史论","author":"韩昇","rating":5,"desc":"从册封体制、礼仪与文化交流入手，讨论七世纪东亚国际秩序的形成与唐丽战争的背景，把军事史放进外交与制度的框架里，适合用来校正单一战争叙事。","cover":""},{"id":"tang-silla-relations","title":"七世纪中叶唐与新罗关系研究","author":"拜根兴","rating":4,"desc":"以金石碑志与汉籍互证，重建 645 至 676 年间唐与新罗的同盟、摩擦与战争过程，对唐丽战争后期的半岛格局与唐罗战争起因有细致考订。","cover":""},{"id":"sui-tang-empire-formation","title":"隋唐帝国形成史论","author":"谷川道雄","rating":4,"desc":"从府兵制、贵族制与地方社会的角度解释隋唐帝国的构造，理解征辽战争所需的动员能力与政治结构；先读这本，再看军事史的细节会更清楚。","cover":""},{"id":"tang-jimi-prefectures","title":"唐代羁縻府州研究","author":"刘统","rating":4,"desc":"考订唐代羁縻府州的设置、地理与运作，涉及安东都护府与高句丽故地的行政安排、蕃将任用与降众安置，是研究战后统治的重要参考。","cover":""},{"id":"sui-tang-history","title":"隋唐史","author":"岑仲勉","rating":5,"desc":"以专题体例论述隋唐的政治、制度、民族与对外关系，考订细密、多有创见，是二十世纪隋唐史研究的代表作之一。","cover":""},{"id":"tang-historical-sources","title":"唐史史料学","author":"黄永年","rating":4,"desc":"系统介绍研治唐史的史料类型与使用方法，从正史、政书到碑志、笔记，讲版本、辨真伪，是入门与治学的实用指南。","cover":""},{"id":"tang-keju-institution","title":"唐代科举制度研究","author":"吴宗国","rating":4,"desc":"考察唐代科举的科目、考试内容、录取与选官的关系，兼及科举对社会流动与士人风气的影响，是唐代选举制度研究的代表作。","cover":""},{"id":"tang-fanzhen-study","title":"唐代藩镇研究","author":"张国刚","rating":5,"desc":"以类型分析重新审视藩镇，区分河朔割据、中原防遏、边疆御边与东南财源等类型，修正了藩镇即割据的简单印象。","cover":""},{"id":"tang-fiscal-history","title":"唐代财政史稿","author":"李锦绣","rating":4,"desc":"分门别类考述唐代的财政机构、收支结构与财务运作，兼及仓廪、漕运与军费，是唐代财政史研究的系统性著作。","cover":""},{"id":"high-tang-northeast-asia","title":"盛唐时代与东北亚政局","author":"王小甫","rating":5,"desc":"以盛唐的东北亚政策为中心，考察唐与高句丽、百济、新罗、日本及靺鞨、契丹的关系，分析区域格局的变动与战争成因。","cover":""},{"id":"liang-qichao-methods","title":"中国历史研究法","author":"梁启超","rating":5,"desc":"近代史学方法论的奠基之作，分论史的目的、史料、史迹的论次与史家的修养，可为入门者建立「如何提问、如何取证」的框架。","cover":""},{"id":"liang-qichao-academic","title":"中国近三百年学术史","author":"梁启超","rating":5,"desc":"以学派与人物为线索梳理清初至清末的学术流变，兼顾经学、史学、小学与地理，是理解清代学术地图的经典导览。","cover":""},{"id":"liu-yizheng-guoshi","title":"国史要义","author":"柳诒徵","rating":4,"desc":"以「史原、史权、史统、史联、史德、史识、史例、史术、史化、史义」十题立论，讲中国传统史学的体例与精神。","cover":""},{"id":"xiang-da-changan","title":"唐代长安与西域文明","author":"向达","rating":5,"desc":"以长安为枢纽考察西域人、胡商、宗教与乐舞的东传，兼及敦煌与中外交通，是唐代中外交流史的名著。","cover":""},{"id":"chenyinke-institutions","title":"隋唐制度渊源略论稿","author":"陈寅恪","rating":5,"desc":"从礼仪、职官、刑律、音乐、兵制、财政诸端追溯隋唐制度的北朝、南朝与河西三源，是制度史研究的典范。","cover":""},{"id":"xu-zhuoyun-han-agriculture","title":"汉代农业：早期中国农业经济的形成","author":"许倬云","rating":4,"desc":"以农作技术、土地制度与政府角色为线索，解释汉代农业经济的形成与精耕细作传统的确立。","cover":""},{"id":"xie-guozhen-parties","title":"明清之际党社运动考","author":"谢国桢","rating":4,"desc":"考察东林、复社与几社等党社的兴衰及其与政治、科举的关系，是明清士人群体研究的重要早期著作。","cover":""},{"id":"qi-xia-song-economy","title":"宋代经济史","author":"漆侠","rating":5,"desc":"系统论述宋代农业、手工业、商业与交通，兼及阶级结构与赋役，是宋代经济史研究的集大成之作。","cover":""},{"id":"tang-changru-weijin","title":"魏晋南北朝史论丛","author":"唐长孺","rating":5,"desc":"以制度、阶级、民族与宗教诸题考论魏晋南北朝，注重出土文书与传世文献互证，影响深远。","cover":""},{"id":"deng-guangming-wanganshi","title":"北宋政治改革家王安石","author":"邓广铭","rating":4,"desc":"以变法进程与北宋政治格局为背景重评王安石，兼顾史料考订与人物理解，是宋史研究的经典传记。","cover":""},{"id":"yan-gengwang-traffic","title":"唐代交通图考","author":"严耕望","rating":5,"desc":"以驿道、关隘、里程为纲，逐条考订唐代交通路线，附详细地图与史料出处。研究唐军行军路线、粮运与驿传的必备工具书，缺点是卷帙浩繁、检索需耐心。","cover":""},{"id":"rong-xinjiang-foreign","title":"中古中国与外来文明","author":"荣新江","rating":5,"desc":"围绕粟特、胡人、宗教与物质文化，讨论中古中国与西域的互动。文章多为专题考证，兼顾出土文书与传世文献，适合做外来文明与边疆社会的入门与进阶阅读。","cover":""},{"id":"zhang-guangda-documents","title":"文书、典籍与西域史地","author":"张广达","rating":4,"desc":"以敦煌吐鲁番文书与西域史地为中心，展示如何用碎片材料重建制度与人群。方法意识强，考据细密，适合学习史料批判与跨语言材料的处理方式。","cover":""},{"id":"wu-yugui-tujue","title":"突厥汗国与隋唐关系史研究","author":"吴玉贵","rating":4,"desc":"系统梳理突厥汗国的兴衰与隋唐两朝的互动，兼顾政治、军事与贸易。对理解唐初北方战略、蕃兵使用与羁縻体制很有帮助，叙述偏学术。","cover":""},{"id":"ma-changshou-northern","title":"北狄与匈奴","author":"马长寿","rating":4,"desc":"早期民族史研究的代表作，讨论匈奴的社会结构、经济与汉匈关系。材料以正史为主，观点带有时代印记，但基本框架与史料梳理仍可参考。","cover":""},{"id":"zhu-zongbin-prime-minister","title":"两汉魏晋南北朝宰相制度研究","author":"祝总斌","rating":4,"desc":"从尚书、中书、门下的演变入手，辨析「宰相」的权力边界与制度运作。制度史训练的经典读本，适合理解中枢权力如何被程序与名分塑造。","cover":""},{"id":"yan-buke-rank","title":"品位与职位","author":"阎步克","rating":5,"desc":"以品位、职位与官僚等级为线索，重建秦汉至隋唐官制的结构变化。概念清晰、论证绵密，是理解官阶与权力分配的重要参考。","cover":""},{"id":"wang-zengyu-song-military","title":"宋朝兵制初探","author":"王曾瑜","rating":4,"desc":"讨论宋代禁军、厢军、募兵与军费，兼及军政运作与边防。材料扎实，适合作为宋代军事与财政的入门，部分论断仍有讨论空间。","cover":""},{"id":"chen-xulu-metabolism","title":"近代中国社会的新陈代谢","author":"陈旭麓","rating":5,"desc":"以「新陈代谢」概括近代中国的结构变动，兼顾思想、制度与社会生活。文笔通畅、视野开阔，是近代史通论中影响较大的一种。","cover":""},{"id":"yu-yingshi-shi-culture","title":"士与中国文化","author":"余英时","rating":5,"desc":"从先秦到明清梳理「士」的角色与精神传统，讨论道统、政统与知识人的关系。文章贯通、问题意识强，适合作为思想史与文化史的进阶读物。","cover":""},{"id":"gushi-bian","title":"古史辨","author":"顾颉刚","rating":5,"desc":"疑古史学的奠基之作。顾颉刚提出「层累地造成的中国古史」，把上古传说按时代层次拆开，追问每个故事最早出于何处，书中考辨大禹与三皇五帝的来历。方法上的冲击远大于具体结论：读它主要是学如何追问史料是怎么形成的，而不是接受全部判断。","cover":""},{"id":"yuanbai-shijianzhenggao","title":"元白诗笺证稿","author":"陈寅恪","rating":5,"desc":"以诗证史的典范。陈寅恪从元稹、白居易的诗篇与相关文献互证，考索唐代的婚宦、党争与社会风气，示范了文学作品如何被当作史料使用。行文简峭，结论多从细处逼出，最适合学习「以文证史」的分寸与限度。","cover":""},{"id":"weijin-suitang-sanlun","title":"魏晋南北朝隋唐史三论","author":"唐长孺","rating":5,"desc":"唐长孺晚年对中古史的总结。以土地制度、身分等级与权力结构三条线索贯通魏晋至隋唐，讨论均田、部曲、士族与地方社会的变化。理论框架克制，史料扎实，是理解中古社会转型的入门与进阶之作。","cover":""},{"id":"qinhan-weijin-tanwei","title":"秦汉魏晋史探微","author":"田余庆","rating":5,"desc":"田余庆的秦汉魏晋史论文结集。诸篇多从一个具体制度或事件切入，层层追到政治结构的变化，《东三郡与蜀魏历史》《论轮台诏》等篇尤其示范了怎样把考据与政治史解释结合起来。","cover":""},{"id":"weijin-zhaji","title":"魏晋南北朝史札记","author":"周一良","rating":4,"desc":"周一良读史札记的结集。逐条考订魏晋南北朝史中的名物、制度与词语，篇幅短小而多所发明，兼有对旧注与清人考据的回应。适合作为读正史时的工具书，也提醒人：许多看似熟知的词，含义并不简单。","cover":""},{"id":"songshi-shijiang","title":"宋史十讲","author":"邓广铭","rating":4,"desc":"邓广铭的宋史讲稿。以政治、军事与制度为线索串讲两宋，强调史料辨析与问题意识，对王安石变法、宋代兵制等题目有提纲挈领的说明，可以作为进入宋史的第一本书。","cover":""},{"id":"mingqing-shehui-jingji","title":"明清社会经济变迁论","author":"傅衣凌","rating":4,"desc":"傅衣凌关于明清社会经济史的论文集。关注乡族、商人、佃仆与地方市场，主张从民间文书与族谱里找材料，把社会经济史从制度条文拉回具体人群，是明清社会史研究的本土路径之一。","cover":""},{"id":"mingdai-liangzhang","title":"明代粮长制度","author":"梁方仲","rating":5,"desc":"梁方仲的明代粮长制度研究。从粮长的充任、职权与演变入手，讨论国家如何借地方富户完成赋税征收，以及这一中介角色的兴衰。制度史与财政史结合的经典，篇幅不大而问题清楚。","cover":""},{"id":"mingchu-renkou","title":"明初以降人口及其相关问题","author":"何炳棣","rating":5,"desc":"何炳棣关于明清人口与户籍的经典研究。辨析丁、户、口等统计口径的差异，指出官方数字与实际人口之间的距离，并讨论移民、占籍对地方社会的影响。读它主要是学如何处理「不可靠的统计」。","cover":""},{"id":"xiandaihua-xinlun","title":"现代化新论","author":"罗荣渠","rating":4,"desc":"罗荣渠关于现代化理论的论文集。梳理现代化研究的不同范式，讨论中国近代转型的特殊路径，主张以本土经验修正西方模型，适合作为理解二十世纪中国现代化叙事的理论背景。","cover":""},{"id":"zhonghua-diguo-panluan","title":"中华帝国晚期的叛乱及其敌人","author":"孔飞力","rating":5,"desc":"孔飞力关于中华帝国晚期地方军事化的研究。讨论团练、地方精英与国家对基层控制的变化，说明太平天国之后权力如何下沉到地方。社会史与政治史结合，问题意识很强。","cover":""},{"id":"zhuxi-lishi-shijie","title":"朱熹的历史世界","author":"余英时","rating":5,"desc":"余英时关于朱熹与南宋士大夫政治文化的研究。把理学放回当时的政治与士人网络里去读，讨论道学群体如何介入朝政、又如何自我定位。思想史与政治史互证的示范之作。","cover":""},{"id":"jindai-sixiang-xueshu","title":"中国近代思想与学术的系谱","author":"王汎森","rating":5,"desc":"王汎森关于近代思想与学术的论文集。讨论从传统学术到现代史学的转折，关注概念如何传播、群体如何形成，以及思想在具体处境中的变形，适合理解近代史学何以成为今天的样子。","cover":""},{"id":"zhongguo-sixiangshi","title":"中国思想史","author":"葛兆光","rating":5,"desc":"葛兆光的两卷本中国思想史。不以精英哲学为唯一线索，而把一般知识、信仰与观念世界纳入叙述，重建思想在日常生活里的存在方式。体例与视野都不同于传统的哲学史。","cover":""},{"id":"chaju-zhidu-bianqian","title":"察举制度变迁史稿","author":"阎步克","rating":4,"desc":"阎步克关于察举制度变迁的研究。追踪汉代察举到魏晋选举的演变，讨论选官标准、科目与政治结构的关系，说明制度如何在具体人事中变形。制度史研究的细致样本。","cover":""},{"id":"handai-zhengzhi-chunqiu","title":"汉代政治与春秋学","author":"陈苏镇","rating":4,"desc":"陈苏镇关于汉代政治与春秋学的专著。讨论经学如何进入政治决策、又如何被政治需要重塑，从《公羊》学到汉廷的合法性论述，展示思想与制度的互相塑造。","cover":""},{"id":"heizhan-beiwei","title":"黑毡上的北魏皇帝","author":"罗新","rating":4,"desc":"罗新关于北魏皇帝即位仪式的考证。从「黑毡」这一细节入手，追索拓跋政权的仪式传统与草原旧俗，讨论北魏如何在汉制与部族传统之间安排皇权。小切口、大问题的写法。","cover":""},{"id":"dunhuangxue-shibajiang","title":"敦煌学十八讲","author":"荣新江","rating":5,"desc":"荣新江的敦煌学入门讲义。介绍敦煌文献的构成、流散与整理，说明各类文书的史料价值与使用限制，并附研究史与工具书指引，是进入敦煌研究最实用的第一本书。","cover":""},{"id":"tangli-zheyi","title":"唐礼摭遗","author":"吴丽娱","rating":4,"desc":"吴丽娱关于唐代礼制的论文集。讨论郊祀、宗庙与礼仪运作中的实际安排，注意礼书规定与施行之间的差距。把礼制当作制度与政治来做，而不只是条文梳理。","cover":""},{"id":"changan-hebei","title":"长安与河北之间","author":"仇鹿鸣","rating":5,"desc":"仇鹿鸣关于唐后期长安与河北政治的研究。以墓志与碑刻为主要材料，重建安史之乱后中央与藩镇之间的人物网络与政治选择，展示出土文献如何改写政治史叙述。","cover":""}];

